(window.GIM_TS=window.GIM_TS||{})["Shabbat.6"]={"from":144,"a":[["\u0003אף על גב דאיכא דדמיא\u0004 \u0005[אף על פי שיש\u0006 מלאכה אחרת \u0005שדומה]\u0006 \u0003לה\u0004 — \u0003חשיב לה\u0004 \u0005[מונה אותה],\u0006 שכל מלאכה שהיתה במשכן חשובה היא למנותה. ושואלים: \u0003וליחשב נמי\u0004 \u0005[ושימנה גם כן]\u0006 מלאכת \u0003כותש,\u0004 שכותשים את החיטה להסיר ממנה את קליפתה החיצונית ומעין זה היה במשכן! \u0003אמר אביי:\u0004 מלאכת הכתישה איננה מן המלאכות הרגילות בכל מאפה לחם, כיון ש\u0003עני אוכל פתו\u0004 כשהיא עשוייה מקמח ש\u0003לא\u0004 עבר \u0003כתישה\u0004 ובלחמו מעורבים הסובין, וכיון שכבר מנה מלאכת דש לא הזכיר כותש בתהליך עשיית הלחם. \u0003רבא אמר\u0004 נימוק אחר: \u0003הא מני\u0004 \u0005[\u0006משנה \u0005זו של מי היא]\u0006 — של \u0003רבי היא,\u0004 ש\u0003אמר:\u0004 מנין \u0003אבות מלאכות\u0004 הוא \u0003ארבעים חסר אחת,\u0004 ולמד את הדברים מרמז שבכתוב, ואין להוסיף עליהן, \u0003ואי חשיב\u0004 \u0005[ואם ימנה]\u0006 גם את מלאכת \u0003כותש הויא ליה\u0004 \u0005[יהיו לו]\u0006 אם כן \u0003ארבעים,\u0004 ולא שלושים ותשע. ומקשים: \u0003וליפוק חדא מהנך ולעייל\u0004 \u0005[ושיוציא אחת מאלה\u0006 כגון בורר וזורה \u0005ושיכניס]\u0006 \u0003כותש\u0004 ועדיין ישאר המספר המקובל! \u0003אלא מחוורתא\u0004 \u0005[ברורו\u0006 יותר\u0005]\u0006 \u0003כ\u0004פי שהסביר \u0003אביי.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא בענין דיני בורר: \u0003היו לפניו מיני אוכלין\u0004 ורוצה אחד או יותר מתוך השאר — \u0003בורר ואוכל, בורר ומניח. ולא יברור, ואם בירר\u0004 — \u0003חייב חטאת.\u0004 ותוהים: \u0003מאי קאמר\u0004 \u0005[מה אמר]?\u0006 והלא ברייתא זו סופה סותר את תחילתה! \u0003אמר עולא: הכי קאמר\u0004 \u0005[כך אמר]:\u0006 \u0003בורר ואוכל ל\u0004צורך \u0003בו ביום,\u0004 למזונות יום השבת, \u0003ובורר ומניח ל\u0004צורך \u0003בו ביום. ו\u0004אולם לצורך \u0003מחר לא יברור, ואם בירר\u0004 — \u0003חייב חטאת. מתקיף לה\u0004 \u0005[מקשה עליה]\u0006 \u0003רב חסדא\u0004 על הסברה זו: \u0003וכי מותר לאפות לבו ביום? וכי מותר לבשל לבו ביום?\u0004 והלא אין מלאכה האסורה בשבת שהותרה לצורך השבת, והוא הדין לכאורה גם לענין בורר!","\u0003אלא אמר רב חסדא,\u0004 כך יש להבין: \u0003בורר ואוכל פחות מכשיעור\u0004 (כגרוגרת, שהוא השיעור הקטן ביותר המחייב מן התורה), \u0003בורר ומניח פחות מכשיעור. וכשיעור לא יברור, ואם בירר\u0004 — \u0003חייב חטאת. מתקיף לה\u0004 \u0005[מקשה עליה]\u0006 \u0003רב יוסף: וכי מותר לאפות\u0004 לכתחילה \u0003פחות מכשיעור?\u0004 והלא נאסרו המלאכות בכל שהוא, אף אם אין חיוב גמור מן התורה אלא בשיעורים הקצובים לכך. ולכן אין לומר שמותר לברור לכתחילה אף בפחות מכשיעור. \u0003אלא אמר ר' יוסף: בורר ואוכל\u0004 אם בורר \u0003ביד\u0004 בלבד, \u0003בורר ומניח,\u0004 כשבורר \u0003ביד.\u0004 ואולם \u0003בקנון ובתמחוי\u0004 (כלים גדולים ושטוחים שנוהגים לברור בהם ביד כמויות גדולות) \u0003לא יברור\u0004 לכתחילה, \u0003ואם בירר\u0004 — \u0003פטור\u0004 מחטאת אם עשה כן בשוגג, או \u0003מסקילה אם היה זה במזיד, אבל אסור\u0004 לעשות כן מלכתחילה. \u0003ובנפה ובכברה, לא יברור, ואם בירר\u0004 — \u0003חייב חטאת.\u0004","\u0003מתקיף לה\u0004 \u0005[מקשה עליה]\u0006 \u0003רב המנונא: מידי\u0004 \u0005[וכי]\u0006 במשנה \u0003קנון ותמחוי קתני\u0004 \u0005[שנינו]?\u0006 והרי עיקר הסברו של רב יוסף נבנה על הוספת מילים שאינן כתובות בברייתא המקורית! \u0003אלא אמר רב המנונא: בורר ואוכל\u0004 אם מוציא את ה\u0003אוכל מתוך הפסולת,\u0004 וכן \u0003בורר ומניח\u0004 — \u0003אוכל מתוך הפסולת.\u0004 ואולם \u0003פסולת מתוך אוכל לא יברור, ואם בירר\u0004 — \u0003חייב חטאת.\u0004 כי הדרך הרגילה בברירה היא בהוצאת הפסולת מתוך האוכל, ועל ידי שינוי זה שוב אינו מתחייב. \u0003מתקיף לה\u0004 \u0005[מקשה עליה]\u0006 \u0003אביי: מידי\u0004 \u0005[וכי]\u0006 במשנה \u0003אוכל מתוך פסולת קתני\u0004 \u0005[שנינו]?\u0006 והלא גם דברים אלה אינם מפורשים בברייתא! \u0003אלא אמר אביי: בורר ואוכל לאלתר,\u0004 וכן \u0003בירר ומניח\u0004 ו\u0003לאלתר, ו\u0004אולם \u0003לבו ביום\u0004 — \u0003לא יברור, ואם בירר\u0004 — \u0003נעשה כבורר לאוצר\u0004 (למחסן) \u0003וחייב חטאת.\u0004 שבהסבר זה אין תוספת מהותית של מילים אלא עמידה על דיוק משמעותן ש\"בורר ואוכל\" משמעו בורר ואוכל מיד. ומסופר כי \u0003אמרוה רבנן קמיה\u0004 \u0005[חכמים\u0006 להסבר זה של אביי \u0005לפני]\u0006 \u0003רבא. אמר להו\u0004 \u0005[להם]:\u0006 \u0003שפיר\u0004 \u0005[יפה]\u0006 \u0003אמר נחמני,\u0004 אביי.","עד כה דובר בברירה סתם, כאשר יש להפריד בין האוכל לבין הפסולת. ואולם במקרה ש\u0003היו לפניו שני מיני אוכלין, ובירר ואכל\u0004 רק אחד מהם, \u0003ובירר והניח\u0004 אחד מהם. \u0003רב אשי מתני\u0004 \u0005[\u0006היה \u0005שונה]:\u0006 \u0003פטור, ר' ירמיה מדיפתי מתני\u0004 \u0005[\u0006היה \u0005שונה]:\u0006 \u0003חייב.\u0004 ושואלים: איך \u0003רב אשי מתני\u0004 \u0005[\u0006היה \u0005שונה]\u0006 \u0003פטור, והא תני\u0004 \u0005[והרי שנינו]\u0006 שבכגון זה \u0003חייב!\u0004 ומתרצים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה];\u0006 \u0003הא\u0004 \u0005[זה],\u0006 ששנינו שאמר שפטור הרי זה באופן שבורר \u0003ב\u0004אמצעות \u0003קנון ותמחוי\u0004 שאין בברירה בדרך זו משום מלאכת אומן, ואילו \u0003הא\u0004 \u0005[\u0006ו\u0005זה]\u0006 ששנינו שחייב, הרי זה כשבורר \u0003ב\u0004אמצעות \u0003נפה וכברה\u0004 שברירה בהם היא דרך מעשה אומן.","ומסופר: \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל לבבל \u0003אמר: שבתא\u0004 \u0005[שבת]\u0006 שזמנו של \u0003רב ביבי\u0004 לטפל בהגשת האוכל לתלמידים \u0003הואי\u0004 \u0005[היתה],\u0006 \u0003ואיקלעו\u0004 \u0005[והזדמנו]\u0006 \u0003ר' אמי ור' אסי\u0004 לביתו. \u0003שדא קמייהו כלכלה דפירי\u0004 \u0005[הניח לפניהם סל פירות]\u0006 כמו שנקטפו, ולא נתן להם את הפירות נקיים בלא העלים והענפים. \u0003ו\u0004אולם \u0003לא ידענא\u0004 \u0005[אינני יודע]\u0006 \u0003אי\u0004 \u0005[אם]\u0006 עשה זאת \u0003משום\u0004 ש\u0003סבר\u0004 כי אפילו בירור \u0003אוכל מתוך פסולת\u0004 שלא לאכילה מיד \u0003אסור,\u0004 או \u0003משום עין יפה הוא דמכוין\u0004 \u0005[שהתכוון],\u0006 שנראה הדבר נאה יותר כשהסל מלא יותר, שנתינת סל מלא פירות לאורחים היא ביטוי לנתינה ברוחב לב, ושיוכלו לקחת כאוות נפשם. ואם כן אין לדעת אם אפשר ללמוד הלכה ממעשה זה.","\u0003חזקיה אמר: הבורר תורמוסים\u0004 לאחר שליקתם \u0003מתוך\u0004 ה\u0003פסולת שלהן\u0004 — \u0003חייב\u0004 משום בורר. ובאים לברר את שיטתו: \u0003לימא קסבר\u0004 \u0005[האם נאמר\u0006 כי \u0005סבור]\u0006 \u0003חזקיה\u0004 שאף בירור \u0003אוכל מתוך פסולת אסור?\u0004 ודוחים: אין זו ראיה, אלא \u0003שאני תורמוסים\u0004 \u0005[שונים התורמוסים]\u0006"],["\u0003דשלקי ליה שבעא זימני\u0004 \u0005[שמבשלים אותם שבע פעמים],\u0006 \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא שקלי ליה\u0004 \u0005[לוקחים אותו]\u0006 מן הקליפות הריהו \u0003מסרח\u0004 \u0005[\u0006\u0005מסריח]\u0006 \u0003וכפסולת מתוך אוכל דמי\u0004 \u0005[נחשב],\u0006 שגוף התורמוס הרך גורם לקלקל את ריח הקליפות, יש להוציאו משם כדי שלא יהא ריח רע בבית.","בין אבות המלאכות המנויות במשנה נמנית גם מלאכת \u0003הטוחן. אמר רב פפא: האי מאן דפרים סילקא\u0004 \u0005[מי שחותך סילקא לחתיכות קטנות]\u0006 בשבת \u0003חייב משום\u0004 מלאכת \u0003טוחן,\u0004 שהרי עושה פעולה הדומה לטחינה. ו\u0003אמר רב מנשה: האי מאן דסלית סילתי\u0004 \u0005[מי שחותך קיסמים דקים]\u0006 כדי להשתמש בנסורת (רמב\"ם), \u0003חייב משום טוחן.\u0004 והוסיף ו\u0003אמר רב אשי: אי קפיד אמשחתא\u0004 \u0005[אם מקפיד\u0006 הוא \u0005ב\u0006חיתוך \u0005על\u0006 \u0005המידה]\u0006 לעשות את הקיסמים בגודל מסויים, \u0003חייב\u0004 גם \u0003משום\u0004 מלאכת \u0003מחתך.\u0004","\u0003והלש והאופה\u0004 נימנו גם הם במשנה בין אבות המלאכות. ותהה \u0003ואמר רב פפא: שבק\u0004 \u0005[עזב]\u0006 ה\u0003תנא דידן\u0004 \u0005[שלנו]\u0006 במשנה את המלאכה של \u0003בישול\u0004 שהיתה ב\u0003סממנין\u0004 של הצבע \u0003דהוה\u0004 \u0005[שהיתה]\u0006 \u0003במשכן ונקט\u0004 \u0005[ולקח]\u0006 את מלאכת \u0003אופה\u0004 שלא היתה במשכן?! והלוא כאמור כל אבות מלאכות נלמדו ממלאכות המשכן, ומדוע לא מנה בישול! ומשיבים: \u0003התנא דידן\u0004 \u0005[שלנו]\u0006 את \u0003סידורא דפת נקט\u0004 \u0005[סידור\u0006 עשיית \u0005הלחם לקח],\u0006 והשתמש בכך כבסיס לסידור את אבות המלאכות, שהתחיל בחרישה וסיים בגמר מלאכת הלחם.","\u0003אמר רב אחא בר רב עוירא: האי מאן דשדא סיכתא לאתונא\u0004 \u0005[המכניס יתד לתנור]\u0006 כדי לייבשו, \u0003חייב משום\u0004 מלאכת \u0003מבשל.\u0004 ומקשים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]!\u0006 ומתרצים: \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 כי \u0003לשרורי מנא קא מיכוין\u0004 \u0005[לחזק\u0006 את \u0005הכלי הוא מתכוון],\u0006 שהרי לבסוף היתד מתקשה בשהותה בתנור, ולעומת זאת מלאכת הבישול הגדרתה ריכוך דברים על ידי אש, על כן \u0003קא משמע לן דמירפא רפי והדר קמיט\u0004 \u0005[השמיע לנו ש\u0006קודם העץ \u0005מתרפה\u0006 ומתרכך \u0005ואחר כך מתקשה].\u0006 \u0003אמר רבה בר רב הונא: האי מאן דארתח כופרא\u0004 \u0005[מי שהרתיח זפת],\u0006 \u0003חייב משום\u0004 מלאכת \u0003מבשל.\u0004 ומקשים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]!\u0006 ומתרצים: \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 כי \u0003כיון דהדר ואיקושא אימא לא\u0004 \u0005[שחוזרת ומתקשה,\u0006 אחר כך אמור \u0005שאין\u0006 זה בישול\u0005]\u0006 ולא שינה הבישול בתכונתה של הזפת, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאף זה שפעל לשעתו נקרא בישול.","\u0003אמר רבא: האי מאן דעבד חביתא\u0004 \u0005[מי שעשה\u0006 בשבת בשוגג \u0005חבית\u0006 חרס\u0005],\u0006 \u0003חייב משום שבע חטאות.\u0004 שכן בכך הוא מפורר (טוחן) את גושי העפר, ובורר מתוכם את האבנים, ולש את הטיט, ומחתך את הטיט למידה הראויה, ובונה את תבניתו, ומבעיר את האש, ואחר כך שורף (אופה) את כלי החרס (גאונים), והעושה \u0003תנורא\u0004 \u0005[תנור]\u0006 \u0003חייב משום שמונה חטאות,\u0004 שלאחר גמר העבודה עוד מוסיף מריחה נוספת של טיט לסיים מלאכתו והרי זה ממחק. \u0003אמר אביי: האי מאן דעבד חלתא\u0004 \u0005[מי שעושה\u0006 בשבת \u0005בשוגג\u0006 \u0005כוורת\u0006 קנים\u0005],\u0006 \u0003חייב אחת עשרה חטאות.\u0004 שכשהוא זומר את הקנים חייב משום קוצר ומשום נוטע (שהקנים הנשארים ממהרים אחר כך לצמוח) כשאוספם הרי זה מעמר, כשמבררם הרי זה בורר, כאשר מחליקם ומיישרם הרי זה ממחק, כשחותכם לחלקים קטנים הרי זה טוחן, כשחותכם למידה מסויימת הרי זה מחתך. ואחר כך כשמתחיל לארוג את הקנים, יש בכך משום מלאכות מיסך, ועושה שני בתי נירין ואורג. והעמדת כל התבנית יש בה משום בונה (גאונים) \u0003ואי חייטיה לפומיה\u0004 \u0005[ואם תפר את פיה\u0006 של הכוורת\u0005],\u0006 \u0003חייב שלש עשרה חטאות,\u0004 שיש להוסיף כאן מלאכת תופר ומלאכת קושר.","בין המלאכות המנויות במשנה נמנו גם \u0003הגוזז את הצמר והמלבנו,\u0004 שהן מלאכות הקשורות בגזיזת הצמר ובטוויתו. \u0003אמר רבה בר בר חנה אמר ר' יוחנן: הטווה\u0004 בשבת בשוגג \u0003צמר שעל גבי\u0004 ה\u0003בהמה\u0004 (שהוא מחובר עדיין) \u0003בשבת, חייב שלש חטאות, אחת משום גוזז\u0004 שכן חלק מן הצמר נתל ש, \u0003ואחת משום מנפץ,\u0004 כלומר, סורק צמר, \u0003ואחת משום טווה.\u0004 ו\u0003רב כהנא אמר: אין דרך גזיזה בכך, ואין דרך מנפץ בכך, ואין דרך טווי\u0004 \u0005[טוויה]\u0006 \u0003בכך.\u0004 ומקשים: \u0003ולא?\u0004 והאין זו דרך טוויה? \u0003והתניא משמיה\u0004 \u0005[והרי שנינו\u0006 בברייתא \u0005משמו]\u0006 של \u0003ר' נחמיה,\u0004 את הנאמר בכתוב במלאכת המשכן \"וכל הנשים אשר נשא לבן אותנה בחכמה טוו את העיזים\" (שמות לה, כו) יש לפרשו: \u0003שטוף\u0004 השיער \u0003בעזים\u0004 עצמם, \u0003וטוו בעזים\u0004 עצמם מבלי לגזוז את שערן קודם לכן. \u0003אלמא\u0004 [מכאן] ש\u0003טוויה על גבי בהמה שמה טוויה!\u0004 ומתרצים: \u0003חכמה יתירה שאני\u0004 \u0005[שונה],\u0006 ואף שיחידים יכולים לעשות מלאכת טוויה זו כתיקונה, עבור סתם אדם הריהי מלאכה שלא כדרך עשייתה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בתוספתא: \u0003התולש\u0004 בשבת בשוגג \u0003את הכנף\u0004 (נוצה גדולה מכנף עוף) \u0003והקוטמו\u0004 (חותך את קצהו) \u0003והמורטו\u0004 (מוריד את החוטים הדקים היוצרים את הנוצה), \u0003חייב שלש חטאות. ואמר ר' שמעון בן לקיש\u0004 בהסבר הדבר: ה\u0003תולש\u0004 את הנוצה — \u0003חייב משום\u0004 מלאכת \u0003גוזז,\u0004 ה\u0003קוטם\u0004 — \u0003חייב משום מחתך,\u0004 וה\u0003ממרט\u0004 את השיער — \u0003חייב משום ממחק.\u0004","בין אבות המלאכות במשנה נימנו גם \u0003הקושר והמתיר.\u0004 ושואלים: \u0003קשירה במשכן היכא הואי\u0004 \u0005[היכן היתה]?\u0006 \u0003אמר רבא: שכן קושרין ביתדות אהלים,\u0004 שהיו קושרים את המשכן אל יתדותיו. ודוחים: וכי לכך קוראים \u0003קושרים\u0004 כמלאכה גמורה?! הלא \u0003ההוא קושר על מנת להתיר הוא,\u0004 שהרי במסעם היו מפרקים את המשכן ומתירים בתוך כך את כל הקשרים, וכל קשר העומר להתרה אין חייבים על עשייתו בשבת. \u0003אלא אמר אביי: שכן אורגי יריעות שנפסקה להן נימא\u0004 (חוט) \u0003קושרים אותה. אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא: תרצת\u0004 מלאכת \u0003קושר,\u0004 ואולם מלאכת \u0003מתיר מאי איכא למימר\u0004 \u0005[מה יש לומר\u0006 בה\u0005]?\u0006 היכן מוצא אתה במשכן שמתירים קשר? \u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 ותפרש בדרך זו: \u0003דאי מתרמי ליה תרי חוטי קיטרי בהדי הדדי, שרי חד וקטר חד\u0004 \u0005[שאם מזדמנים לו שני חוטים קשורים זה ליד זה, מתיר אחד וקושר אחד],\u0006 ואולם \u0003השתא\u0004 \u0005[עכשיו,\u0006 הרי] \u0003לפני מלך בשר ודם אין עושין כן,\u0004 שהיריעה שכך עשו בה נראית פגומה, \u0003לפני מלך מלכי המלכים הקדוש ברוך הוא,\u0004 במשכן העדות \u0003עושין?! אלא אמר רבא ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003ר' עילאי, שכן צדי חלזון\u0004 שהיו נצרכים לו לצביעת המשכן \u0003קושרין ומתירין\u0004 את הרשתות שלהם.","עוד שנינו במשנה בין המלאכות המנויות גם את \u0003התופר שתי תפירות.\u0004 ומקשים: \u0003והא לא קיימא\u0004 \u0005[והרי אינה מתקיימת]!\u0006 שהרי שתי תפירות בלבד מתפרקות מיד, ומלאכה שאין לה קיום אינה נחשבת מלאכה! על כן \u0003אמר רבה בר בר חנה\u0004 שכך \u0003אמר ר' יוחנן: והוא שקשרן,\u0004 שלא יצא החוט, ובדרך זו התפירה קיימת אף בשתי תפירות.","עוד שנינו במשנה ש\u0003הקורע על מנת לתפור\u0004 אף זו בין אבות המלאכות. ושואלים: \u0003קריעה במשכן מי הוה\u0004 \u0005[האם היתה?\u0006 \u0003רבה ור' זירא דאמרי תרווייהו\u0004 \u0005[שאמרו שניהם]\u0006 בהסבר הדבר:"],["שכן הדרך היא ש\u0003יריעה שנפל בה דרנא\u0004 \u0005[תולעת]\u0006 ועשתה חור, \u0003קורעין בה\u0004 כדי להרחיב במעט את החור \u0003ותופרין אותה\u0004 אחר כך באופן שלא יכירו את החור.","\u0003אמר רב זוטרא בר טוביה אמר רב: המותח חוט של תפירה בשבת\u0004 — \u0003חייב חטאת,\u0004 שכן אם נפרדו שני חלקי בגד המחוברים בחוט תפירה, והוא מותח את החוט וחוזר ומחברם — הרי זה כאילו תפרם. ואגב כך מביאים עוד את מה שאמר בשם רב: \u0003והלומד דבר אחד מן המגוש\u0004 (כומר פרסי) \u0003חייב מיתה. והיודע לחשב תקופות ומזלות ואינו חושב, אסור לספר הימנו\u0004 (לדבר אתו), לפי שנוהג שלא כהוגן.","וכיון שהוזכר הדבר דנים בו. \u0003מגושתא,\u0004 כלומר, אומנותם ודרכם של האמגושים נחלקו בענין זה \u0003רב ושמואל, חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר\u0004 שזהו \u0003חרשי\u0004 (כישוף) \u0003וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר\u0004 שזהו \u0003גדופי\u0004 \u0005[גידוף,\u0006 כפירה\u0005].\u0006 ומוסיפים: \u0003תסתיים\u0004 \u0005[תוגדר,\u0006 יוכח\u0005]\u0006 ש\u0003רב\u0004 הוא ש\u0003אמר\u0004 שמגושתא היא \u0003גדופי\u0004 \u0005[גידוף],\u0006 שכן \u0003אמר רב זוטרא בר טוביה אמר רב: הלומד דבר אחד מן המגוש חייב מיתה. דאי סלקא דעתך חרשי\u0004 \u0005[שאם יעלה על דעתך\u0006 שהמגוש הוא \u0005כישוף],\u0006 הלא כבר נאמר: \"כי אתה בא אל הארץ אשר ה' אלהיך נותן לך \u0003לא תלמד לעשות\u0004 כתועבות הגויים ההם. לא ימצא בך מעביר בנו ובתו באש קוסם קסמים מעונן ומנחש ומכשף\" (דברים יח, ט–י). ואמרו חכמים: \"לא תלמד לעשות\" — \u0003אבל אתה למד\u0004 בהיתר \u0003להבין ולהורות\u0004 בענין הכישוף. הרי שעצם לימוד הכשפים אין בו איסור, ואסור רק לעשותם. ולכן רב שאסר ללמוד מן המגוש ודאי סבר שהמגושות יש בה כפירה, ולא כשפים בלבד. ומסכמים: אכן \u0003תסתיים\u0004 \u0005[תוגדר]\u0006 שכך אמר רב.","ואגב דברי רב הובא מה ש\u0003אמר ר' שמעון בן פזי\u0004 שכך \u0003אמר ר' יהושע בן לוי משום\u0004 (בשם) \u0003בר קפרא: כל היודע לחשב בתקופות ומזלות ואינו חושב, עליו הכתוב אומר: \"ואת פעל ה' לא יביטו ומעשה ידיו לא ראו\"\u0004 (ישעיהו ה, יב). ו\u0003אמר ר' שמואל בר נחמני\u0004 שכך \u0003אמר ר' יוחנן: מנין שמצוה על האדם לחשב תקופות ומזלות\u0004 — \u0003שנאמר: \"ושמרתם ועשיתם כי היא חכמתכם ובינתכם לעיני העמים\"\u0004 (דברים ד, ו), ופשוט הוא כי \u0003איזו\u0004 היא \u0003חכמה ובינה\u0004 שיש בתורה \u0003שהיא לעיני העמים\u0004 והכל יבולים להעריכה ולהכירה — \u0003הוי אומר: זה חישוב תקופות ומזלות,\u0004 שחישוביו של הבקי בדבר מתאמתים לעין כל.","במשנה נמנתה בין אבות המלאכות גם מלאכת \u0003הצד\u0004 בהמה או חיה, וכגון את ה\u0003צבי. תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בתוספתא: \u0003הצד חלזון, והפוצעו\u0004 (שובר קונכייתו להוציא ממנו את חומר הצבע), \u0003אינו חייב אלא\u0004 חטאת \u0003אחת,\u0004 שאינו מתחייב על הפציעה. \u0003ר' יהודה אומר חייב שתים,\u0004 על הצידה ועל הפציעה. \u0003שהיה ר' יהודה אומר: פציעה\u0004 של חילזון \u0003בכלל\u0004 מלאכת \u0003דישה\u0004 היא, שכן מטרתה כמטרת הדישה להוציא את התוכן הרצוי מתוך קליפה שאיננה רצויה. \u0003אמרו לו\u0004 חכמים: \u0003אין פציעה בכלל דישה. אמר רבא: מאי טעמא דרבנן\u0004 \u0005[מה הטעם של חכמים]\u0006 — \u0003קסברי\u0004 \u0005[סבורים הם]\u0006 כי \u0003אין דישה אלא לגדולי קרקע,\u0004 אבל המפרק בדברים אחרים — פטור. ושואלים: אם אמנם פציעה אין בה משום דישה, אולם \u0003וליחייב נמי\u0004 \u0005[שיתחייב גם כן]\u0006 בפציעתו זו את החילזון \u0003משום נטילת נשמה! אמר ר' יוחנן:\u0004 המדובר כאן \u0003שפצעו\u0004 כשהיה החילזון \u0003מת\u0004 כבר.","\u0003רבא אמר: אפילו תימא\u0004 \u0005[תאמר]\u0006 \u0003שפצעו חי,\u0004 בכל זאת אינו חייב, כיון שאינו מתכוון כלל להמתת החילזון, ולכך \u0003למתעסק\u0004 בלבד נחשב \u0003הוא אצל\u0004 (לגבי) מלאכה זו של \u0003נטילת נשמה,\u0004 שאין לו כל ענין בהמתת החילזון. והקשו: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אביי ורבא\u0004 עצמו \u0003דאמרי תרווייהו\u0004 \u0005[שאמרו שניהם]\u0006 ש\u0003מודה ר' שמעון\u0004 הפוטר כרגיל במלאכה שאינה צריכה לגופה, \u0003ב\"פסיק רישא ולא ימות\"\u0004 \u0005[חתוך ראשו ולא ימות].\u0006 כלומר, בכל מקרה כאשר התוצאה היא הכרחית, אין אדם יכול לטעון שלא התכוין לתוצאה זו. שכל תוקפו של הנימוק שאינו מתכוין הריהו רק כאשר יתכן שאותו דבר לא ייעשה כלל. ואם כן, הפוצע חילזון ודאי נוטל נשמתו, ומדוע סבור רבא שיש בכך משום מתעסק בלבד! ומשיבים: \u0003שאני הכא\u0004 \u0005[שונה כאן]\u0006 שכל \u0003כמה דאית ביה\u0004 \u0005[שיש בו,\u0006 בחילזון\u0005]\u0006 \u0003נשמה טפי ניחא ליה, כי היכי דליציל ציבעיה\u0004 \u0005[יותר נוח לו\u0006 לצייד, \u0005כדי שיצטלל צבעו]\u0006 שהצבע היוצא מחילזון חי מובחר מזה של חילזון מת. וכיון שאינו מתכוון לנטילת נשמה, ולהיפך, כוונתו ורצונו שיחיה החילזון — אין בכך משום איסור.","עוד שנינו במנין המלאכות במשנה גם את \u0003השוחטו\u0004 לאותו צבי שצד או בעל חי אחר בשבת. ושואלים: ה\u0003שוחט\u0004 בהמה \u0003משום מאי\u0004 \u0005[מה,\u0006 איזה איסור\u0005]\u0006 הוא \u0003חייב?\u0004 מה הם עקרונות האיסור שבמלאכה זו? ונחלקו בכך אמוראים: \u0003רב אמר: משום צובע,\u0004 שבשחיטה נצבע מקום השחיטה בדם. \u0003ושמואל אמר: משום נטילת נשמה.\u0004"],["ותוהים: ואף לדעת רב, היתכן שיחשוב ש\u0003משום צובע אין\u0004 \u0005[כן]\u0006 יהא חייב, ו\u0003משום נטילת נשמה לא\u0004 יהא חייב? אלא תקן את הלשון ו\u0003אימא\u0004 \u0005[אמור]\u0006 כך: \u0003אף משום צובע\u0004 חייב. ו\u0003אמר רב: מילתא דאמרי, אימא בה מילתא\u0004 \u0005[הדבר שאמרתי, אומר בו דבר\u0006 הסבר\u0005],\u0006 כדי ש\u0003לא ליתו דרי בתראי וליחכו\u0004 \u0005[יבואו הדורות האחרונים ויצחקו]\u0006 \u0003עלי: צובע במאי ניחא ליה\u0004 \u0005[במה נוח לו]\u0006 — \u0003ניחא דליתווס\u0004 \u0005[נוח\u0006 לו \u0005שיתמלא]\u0006 \u0003בית השחיטה דמא כי היכי דליחזוה אינשי וליתו ליזבנו מיניה\u0004 \u0005[\u0006ב\u0005דם כדי שיראוהו בני אדם ויבואו ויקנו ממנו],\u0006 הרי שהשוחט מעוניין אגב שחיטתו גם בצביעה.","בין המלאכות שנמנו במשנה ישנן גם אלה הקשורות לעיבוד העור, \u0003וכגון המולחו והמעבדו.\u0004 ושואלים: \u0003היינו\u0004 \u0005[זוהי]\u0006 מלאכת \u0003מולח והיינו\u0004 \u0005[וזוהי]\u0006 בדיוק מלאכת \u0003מעבד!\u0004 ששתי המלאכות הללו הן בעצם מלאכה אחת. \u0003ר' יוחנן וריש לקיש דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]:\u0006 \u0003אפיק חד מינייהו ועייל\u0004 \u0005[הוצא אחד מהם והכנס]\u0006 במקומו \u0003שירטוט.\u0004 שלדעתם יש למנות את מלאכת השרטוט — עשיית סימנים בעור — במנין שלושים ותשע המלאכות, במקום אחד משני אלה. \u0003אמר רבה בר רב הונא: האי מאן דמלח בישרא\u0004 \u0005[מי שמולח בשר\u0006 בשבת\u0005]\u0006 לצורך שימורו לזמן ממושך — \u0003חייב משום\u0004 מלאכת \u0003מעבד. רבא אמר: אין עיבוד באוכלין,\u0004 שמה שעושים בדבר מאכל אינו כלול במלאכה זו. \u0003אמר רב אשי: ואפילו רבה בר רב הונא לא אמר\u0004 שיש בכך משום איסור \u0003אלא דקא בעי ליה לאורחא\u0004 \u0005[כשצריך את הבשר לדרך]\u0006 ומולחו ביותר, \u0003אבל לביתא לא משוי איניש מיכליה\u0004 \u0005[אין אדם עושה\u0006 את\u0005]\u0006 \u0003עץ\u0004 \u0005[ל\u0006צורך \u0005ביתו אין אדם עושה את מאכלו עץ]\u0006 ולכן ודאי אינו מולחו במדה יתירה, עד כדי עיבוד.","במשנה נמנו בין המלאכות גם \u0003הממחקו והמחתכו. אמר ר' אחא בר חנינא: השף\u0004 את העור \u0003בין העמודים בשבת,\u0004 ששם את העור בין עמודים העשויים לכך ומשפשפו ביניהם (רה\"נ) — \u0003חייב משום\u0004 מלאכת \u0003ממחק. אמר ר' חייא בר אבא: שלשה דברים סח לי רב אשי משמיה\u0004 \u0005[משמו]\u0006 של \u0003ר' יהושע בן לוי: המגרר ראשי כלונסות\u0004 (כלונסאות, עמודים) \u0003בשבת\u0004 ומיישרם — \u0003חייב משום\u0004 מלאכת \u0003מחתך,\u0004 כיון שהוא מקפיד שיהיו שווים זה לזה. \u0003הממרח רטיה\u0004 (תחבושת), שמחליק את התחבושת על המכה \u0003בשבת\u0004 — \u0003חייב משום\u0004 מלאכת \u0003ממחק. והמסתת את האבן בשבת\u0004 — \u0003חייב משום\u0004 מלאכת \u0003מכה בפטיש,\u0004 שהוא מסיים את מלאכת האבן. \u0003אמר ר' שמעון בן קיסמא\u0004 שכך \u0003אמר ר' שמעון בן לקיש: הצר צורה\u0004 של ציור או חקיקה \u0003בכלי\u0004 חרס, \u0003והמנפח בכלי זכוכית\u0004 — \u0003חייב משום\u0004 מלאכת \u0003מכה בפטיש. אמר ר' יהודה: האי מאן דשקיל אקופי מגלימי\u0004 \u0005[מי שמסיר את החוטים\u0006 העודפים והפגמים \u0005מגלימה]\u0006 — \u0003חייב משום מכה בפטיש. והני מילי דקפיד עלייהו\u0004 \u0005[ודברים אלה\u0006 דווקא \u0005כשמקפיד עליהם],\u0006 שאם מקפיד שלא ללבוש את הבגד עד שהוריד ממנו שיירי אריגתו הרי שגמר מלאכת הבגד נעשה עם הסרת החוטים.","במשנה נמנתה גם מלאכת \u0003הכותב\u0004 והיא מוגדרת בכותב \u0003שתי אותיות. תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003כתב אות אחת גדולה ויש במקומה\u0004 די מקום כדי \u0003לכתוב שתים\u0004 — \u0003פטור,\u0004 כיון שלא כתב אלא אות אחת. ואולם אם \u0003מחק אות גדולה\u0004 אחת על מנת לכתוב, \u0003ויש במקומה\u0004 די מקום כדי \u0003לכתוב שתים\u0004 — \u0003חייב. אמר ר' מנחם בר' יוסי: וזה חומר\u0004 שיש \u0003במוחק מבכותב,\u0004 שאף שכרגיל מחמירים יותר במלאכה שיש עמה יצירה, כאן יש מקרה של חומרה במלאכת הריסה, כיון שמפנה מקום לשתי אותיות, והיא עיקר המלאכה.","עוד נמנו במשנה מלאכות \u0003הבונה, והסותר, המכבה, והמבעיר, והמכה בפטיש.\u0004 במלאכת המכה בפטיש \u0003רבה ור' זירא דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]\u0006 כלל: \u0003כל מידי דאית ביה\u0004 \u0005[דבר שיש בו]\u0006 משום \u0003גמר מלאכה חייב\u0004 העושה אותו בשבת \u0003משום\u0004 מלאכת \u0003מכה בפטיש.\u0004","המשנה מסתיימת בהדגשה \u0003\"אלו אבות מלאכות\".\u0004 ומסבירים: כי ההדגשה \u0003\"אלו \"\u0004שמשמעה אלו ולא אחרות באה \u0003לאפוקי\u0004 \u0005[להוציא,\u0006 למעט\u0005]\u0006 \u0003מ\u0004דעתו של \u0003ר' אליעזר,\u0004 שהיה \u0003מחייב על\u0004 עשיית \u0003תולדה\u0004 של מלאכה \u0003במקום\u0004 שעשה גם את \u0003אב\u0004 אותה מלאכה, שאם עשה אב ותולדתו לדעת ר' אליעזר הריהו חייב שתי חטאות, ולשיטתו אם כן מצויות מלאכות מרובות יותר. ומשום כך באה ההדגשה במשנה שרק אלו הן אבות מלאכות, ולעולם לא יתכן שיתחייב על יותר ממנין זה. ומה שחזרו ואמרו שמניינן ארבעים \u0003חסר אחת,\u0004 בא \u0003לאפוקי\u0004 \u0005[להוציא,\u0006 למעט\u0005]\u0006 \u0003מ\u0004דעתו של \u0003ר' יהודה. דתניא\u0004 \u0005[ששנינו\u0006 בברייתא\u0005]\u0006 ש\u0003ר' יהודה מוסיף\u0004 למנין אבות המלאכות את \u0003השובט\u0004 (מיישר את חוטי השתי) \u0003ו\u0004את \u0003המדקדק\u0004 (המיישר את חוט הערב). \u0003אמרו לו: שובט הריהו\u0004 פרט \u0003בכלל\u0004 מלאכת \u0003מיסך\u0004 (מותח את חוטי השתי בתוך הנול), ששניהן מלאכות לסידור חוטי השתי\u0003,\u0004 וה\u0003מדקדק הרי הוא בכלל אורג\u0004 ואין איפוא אלא ארבעים מלאכות חסר אחת.","\u0003ועוד כלל אחר אמרו\u0004 בדיני שבת: \u0003כל\u0004 דבר \u0003הכשר\u0004 והראוי \u0003להצניע\u0004 (לשמור) לצורך שימוש האדם, \u0003ו\u0004גודלו כזה שאפשר ונהוג ש\u0003מצניעין כמוהו, והוציאו בשבת\u0004 למקום האסור בהוצאה \u0003חייב חטאת עליו. וכל שאינו כשר להצניע ואין מצניעין כמוהו,\u0004 שהוא קטן מכדי שיקפידו על הצנעתו, \u0003והוציאו בשבת\u0004 — \u0003אינו חייב אלא המצניעו,\u0004 שאדם המקפיד ושומר דבר זה רק הוא בלבד חייב על הוצאתו, משום שלגביו הרי זה דבר חשוב, וחיוב ההוצאה לפי חשיבות הדבר למי שהוציאו.","על הכלל ששנינו במשנה \u0003\"כל הכשר להצניע\",\u0004 שואלים: \u0003לאפוקי מאי\u0004 \u0005[להוציא,\u0006 למעט \u0005את מה]\u0006 הוא בא, ומה לדעתו אינו כשר וראוי להצנעה? \u0003רב פפא אמר: לאפוקי\u0004 \u0005[להוציא]\u0006 \u0003דם נדה. מר עוקבא אמר: לאפוקי\u0004 \u0005[להוציא]\u0006 \u0003עצי אשרה,\u0004 שעץ שעשו ממנו עבודה זרה אסור בכל הנאה. ומפרטים: \u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 ש\u0003דם נדה\u0004 אינו כשר להצניע \u0003כל שכן עצי אשרה,\u0004 כיון שמן התורה חייב להשמידם ודאי אינם בכלל הדברים הנשמרים. ואולם \u0003מאן דאמר\u0004 \u0005[מי שאמר]\u0006 שרק \u0003עצי אשרה\u0004 הוא דבר שאין מצניעים, \u0003אבל דם נדה מצנע ליה לשונרא\u0004 \u0005[שומר אותו בשביל\u0006 מאכל \u0005החתול],\u0006 שאף שכרגיל אין רגילים לשומרה מכל מקום אפשר למצוא בו שימוש. \u0003ואידך\u0004 \u0005[והאחר]\u0006 הסבור שדם נידה אינו ראוי לכל שימוש מה אומר הוא על כך? — לדעתו \u0003כיון דחלשא לא מצנע ליה\u0004 \u0005[ש\u0006הוא \u0005מחליש אינו שומר אותו]\u0006 שחששו — כדרך סגולה — שינזק אדם שנתנו מדמו לבעל חיים.","\u0003אמר ר' יוסי בר חנינא האי\u0004 \u0005[זה]\u0006 כל הגדרות שבמשנתנו ש\u0003לא כ\u0004שיטת \u0003ר' שמעון\u0004 הן. \u0003דאי\u0004 \u0005[שאם]\u0006 תאמר שהן \u0003כ\u0004שיטת \u0003ר' שמעון\u0004 — \u0003האמר\u0004 \u0005[הלא הוא אומר]\u0006 ש\u0003לא אמרו\u0004 את \u0003כל השיעורין הללו\u0004 הקבועים במשנה להוצאת כל דבר ודבר \u0003אלא למצניעיהן,\u0004 שהמצניעים כשיעור זה חייבים עליו. אבל מי שדבר מסויים אינו חשוב בעיניו אף כשהוא בשיעור האמור במשנה — אינו חייב על הוצאתו.","שנינו במשנה ש\u0003כל שאינו כשר להצניע,\u0004 שהוא פחות מכשיעור הראוי להצנעה אין חייב על הוצאתו אלא מי שהצניעו."],["\u0003אמר ר' אלעזר: הא\u0004 \u0005[\u0006דבר \u0005זה]\u0006 הוא ש\u0003לא כ\u0004שיטת \u0003ר' שמעון בן אלעזר, דתניא\u0004 \u0005[ששנוייה\u0006 ברייתא\u0005],\u0006 \u0003כלל אמר ר' שמעון בן אלעזר: כל\u0004 דבר \u0003שאינו כשר להצניע, ואין מצניעין כמוהו, והוכשר לזה\u0004 (לאדם מסויים) \u0003והצניעו, ובא אחר והוציאו\u0004 לאותו חפץ שהוצנע \u0003נתחייב זה\u0004 המוציא \u0003במחשבה של זה\u0004 המצניע, שמאחר שלגבי אדם מסויים יש בדבר חשיבות, נחשב הוא כמו כן לכל אדם. ואילו למשנתנו רק המצניע עצמו הוא שמתחייב על הוצאת החפץ.","ומעתה לפירוט שיעורי דברים שכרגיל נחשבים הם בעיני בני אדם, ומצניעים כמותם: \u0003המוציא תבן\u0004 הרי זה מתחייב אם הוציא בשיעור \u0003כמלא פי פרה. עצה\u0004 שהיא מאכל גס יותר יש בו צורך בשיעור גדול יותר וכדי להתחייב על הוצאתו צריך הוא להוציא שיעור \u0003כמלא פי גמל,\u0004 שכן פרה כרגיל אינה אוכלת מאכל זה. \u0003עמיר,\u0004 שהוא קש דק — \u0003כמלא פי טלה. עשבים\u0004 — \u0003כמלא פי גדי\u0004 הקטן יותר מפי טלה. \u0003עלי שום ועלי בצלים,\u0004 אם היו \u0003לחים\u0004 וראויים למאכל אדם, שיעורם כשיעור סתם מאכלי אדם והוא \u0003כגרוגרת.\u0004 ו\u0003יבשים\u0004 שיעורם \u0003כמלא פי גדי, ו\u0004כל אלה \u0003אין מצטרפין זה עם זה\u0004 לכדי שיעור בו יתחייב המוציא \u0003מפני שלא שוו\u0004 זה לזה \u0003בשיעוריהן.\u0004","מתחילה שואלים: \u0003מאי\u0004 \u0005[מהו]\u0006 \u0003עצה\u0004 זו ששנינו במשנה? \u0003אמר רב יהודה:\u0004 הוא \u0003תבן של מיני קטנית. כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל לבבל \u0003אמר\u0004 שהתעוררה השאלה: \u0003המוציא תבן\u0004 בשיעור \u0003כמלא פי פרה,\u0004 אלא שנתן את התבן הזה \u0003לגמל,\u0004 ולגבי הגמל הלוא אין זה כשיעור הראוי לאכילתו. והבעיה: האם יש לחייבו על פי השיעור שהוא מוציא, או על פי המטרה שלשמה הוא מוציא. ונחלקו בכך, \u0003ר' יוחנן אמר: חייב,\u0004 ו\u0003ר' שמעון בן לקיש אמר: פטור. באורתא\u0004 \u0005[בערב]\u0006 \u0003אמר ר' יוחנן הכי\u0004 \u0005[כך],\u0006 ואילו \u0003לצפרא הדר ביה\u0004 \u0005[בבוקר חזר בו]\u0006 והודה לריש לקיש. \u0003אמר רב יוסף: שפיר עבד דהדר, דהא לא חזי\u0004 \u0005[יפה עשה שחזר\u0006 בו, \u0005שכן אינו ראוי]\u0006 \u0003לגמל!\u0004 שבהוצאה לצורך גמל בפחות משיעור פי הגמל אין חיוב. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי\u0004 לרב יוסף: \u0003אדרבא, כדמעיקרא מסתברא, דהא חזי\u0004 \u0005[להיפך, כמו שמתחילה מסתבר\u0006 לומר שיהא חייב, \u0005שהרי ראוי]\u0006 \u0003לפרה,\u0004 שהרי הוציא שיעור חשוב הראוי להשתמש בו, ומתחייב משום הוצאתו אף שאינו מספיק לגמל.","\u0003אלא כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רבין\u0004 לאחר זמן מארץ ישראל לבבל \u0003אמר\u0004 ומסר גירסה מתוקנת של המחלוקת, שבדין \u0003המוציא תבן כמלא פי פרה לגמל, דכולי עלמא לא פליגי\u0004 \u0005[הכל אינם חלוקים]\u0006 ש\u0003חייב, כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 היה זה \u0003ב\u0004מקרה של ה\u0003מוציא עצה\u0004 שכרגיל אינו מאכל פרה בשיעור \u0003כמלא פי פרה ל\u0004צורך \u0003אכילת פרה.\u0004 וכאן השאלה קשה יותר, ברור שאם יוציא כשיעור זה עבור גמל, או בסתם — יהא פטור. ואולם, כיון שהועיד את המאכל לפרה, ועבור הפרה שיעור זה מספיק שמא יש בכך משום הוצאה.","\u0003ואיפכא איתמר\u0004 \u0005[וההיפך נאמר]\u0006 בדברי ר' יוחנן וריש לקיש להקל ולהחמיר. ש\u0003ר' יוחנן אמר: פטור,\u0004 ו\u0003ריש לקיש אמר: חייב.\u0004 וטעמם: \u0003ר' יוחנן אמר\u0004 שהוא \u0003פטור,\u0004 משום שהוא סבור ש\u0003אכילה על ידי הדחק\u0004 שאין רגילים לאכול כיוצא בכך, אבל בדוחק אפשר לאכלו, כגון עצה לפרה — \u0003לא שמה\u0004 (אינה נחשבת) \u0003אכילה.\u0004 ו\u0003ריש לקיש אמר\u0004 ש\u0003חייב,\u0004 משום שהוא סבור ש\u0003אכילה על ידי\u0004 הדחק שמה אכילה.","שנינו במשנה ש\u0003עמיר\u0004 שיעורו \u0003כמלא פי טלה.\u0004 ומקשים: \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 ששיעורו \u0003כגרוגרת!\u0004 ומסבירים: \u0003אידי ואידי חד שיעורא\u0004 \u0005[זה וזה שיעור אחד]\u0006 \u0003הוא.\u0004","עוד שנינו במשנה \u0003עלי שום ועלי בצלים\u0004 כאשר הם \u0003לחים\u0004 שיעורם לענין הוצאה הוא ב\u0003כגרוגרת ו\u0004כאשר הם \u0003יבשים\u0004 שיעורם \u0003כמלא פי הגדי.\u0004 ושנינו עוד שכל החומרים הנמנים במשנה \u0003אין מצטרפין זה עם זה\u0004 לכדי שיעור הוצאה \u0003מפני שלא שוו בשיעוריהן. אמר ר' יוסי בר חנינא:\u0004 דברים שחשיבותם פחותה ולכך דינם קל יותר ושיעורם לחיוב גדול יותר \u0003אין מצטרפין לחמור שבהן,\u0004 לדבר שיש בו חשיבות, ששיעורו להתחייב קטן יותר ודינו חמור יותר. שאין להשוות אותה כמות של חומר חשוב (חמור) למין הקל. \u0003אבל מצטרפין לקל שבהן,\u0004 שאם משלימים לכדי שיעור גדול בחומרים חשובים שחייבים בהם אף על שיעורם הקטן — חייב.","על עיקרון זה מקשים: \u0003וכל\u0004 אלה \u0003דלא שוו בשיעורייהו מי\u0004 \u0005[שאינם שווים בשיעורם האם]\u0006 \u0003מצטרפין?\u0004 האם אפשר בכלל להביא לידי צירוף דברים שניתנו בהם שיעורים שונים? הלא נחשבים הם כשונים בתכלית זה מזה במהותם, ואינם ניתנים לכאורה לצירוף. שכן \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 שיעור \u0003הבגד\u0004 שיהא בו כדי לקבל טומאה על ידי שהזב יושב עליו, ב\u0003שלשה על שלשה\u0004 טפחים לפחות. \u0003והשק\u0004 העשוי משער עיזים שיעורו לקבלת טומאה \u0003ארבעה על ארבעה, והעור\u0004 — ב\u0003חמשה על חמשה,\u0004 וה\u0003מפץ\u0004 (מחצלת) — \u0003ששה על ששה. ותני עלה\u0004 \u0005[ושנויה\u0006 ברייתא לתוספת \u0005עליה]\u0006 \u0003הבגד והשק, השק והעור,\u0004 ו\u0003העור והמפץ\u0004 — \u0003מצטרפין זה עם זה. ואמר ר' שמעון: מה טעם\u0004 אמרו שמצטרפים — \u0003מפני שראויין\u0004 החלקים המצורפים \u0003ליטמא\u0004 בטומאת \u0003מושב,\u0004 שאפשר להשתמש בהם כטלאי לאוכף או מרדעת שרוכבים עליה. וכיון שבפועל ראויים הם לשימוש משותף — הריהם מצטרפים זה לזה גם לדיני טומאה. ומכאן נדייק: \u0003טעמא\u0004 \u0005[הטעם,\u0006 רק\u0005]\u0006 מפני ש\u0003ראויין ליטמא מושב, אבל\u0004 כאשר \u0003אין ראוי\u0004 בצירוף כמה מהם \u0003כדי ליטמא מושב\u0004 — \u0003לא\u0004 מצטרפים, ואפילו לשיעור הקל שבהם. ומכאן שכרגיל אין דברים בעלי שיעורים שונים ניתנים לצירוף!","\u0003אמר רבא:\u0004"],["\u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 יש לפנינו מקרה מיוחד, כיון שאף כאן כולם יחד \u0003חזיא\u0004 \u0005[ראויים]\u0006 לשמש כ\u0003דוגמא\u0004 שהמוכרם מצרף ערימה מכולם יחד ומשתמש בה.","\u0003המוציא\u0004 בשבת \u0003אוכלים\u0004 הראויים לאדם ששיעורם \u0003כגרוגרת\u0004 למקום האסור בהוצאה — \u0003חייב. ומצטרפין\u0004 כל האוכלים \u0003זה עם זה\u0004 לכדי שיעור \u0003מפני ששוו בשיעוריהן.\u0004 ושיעור זה נחשב \u0003חוץ מקליפתן וגרעיניהן ועוקציהן\u0004 (הענף הדק שבקצה הפרי שבו הוא תלוי בעץ), \u0003וסובן\u0004 (קליפת החיטה היורדת בכתישה), \u0003ומורסנן\u0004 (שרידי סובין ומוץ שבקמח). \u0003ר' יהודה אומר:\u0004 כל הקליפות אינן מצטרפות \u0003חוץ מקליפי עדשין\u0004 שהן כן מצטרפות לכדי שיעור \u0003עם העדשים עצמם כיון שמתבשלות עמהן\u0004 ונאכלות עמם. ושואלים: \u0003ו\u0004האם \u0003סובן ומורסנן\u0004 של מיני דגן \u0003לא מצטרפין? והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]\u0006 עיסות העשויות מ\u0003חמשת רבעים\u0004 הלוג \u0003קמח ועוד\u0004 משהו \u0003חייבין\u0004 בהפרשת \u0003חלה,\u0004 ובתוך שיעור זה מחשיבים את הקמח \u0003ו\u0004את \u0003סובן ומורסנן,\u0004 והרי שהסובין והמורסן מצטרפים! \u0003אמר אביי:\u0004 לענין חלה ועשיית לחם מצטרפים הסובין, \u0003שכן עני אוכל פתו בעיסה בלוסה\u0004 (מעורבת בסובין), אבל להוצאת שבת, כיון ששיעורה קטן ונמדד על פי חשיבות הדברים דרוש שיהא ראוי למאכל לכל אדם. שנינו במשנה שכל הקליפות אינן מצטרפות לכדי שיעור מאכל \u0003ר' יהודה אומר חוץ מקליפי עדשים\u0004 משום שהן \u0003המתבשלות עמהן.\u0004 ושואלים: האם רק \u0003עדשים אין\u0004 \u0005[כן]\u0006 מצטרפים ואילו \u0003פולין לא\u0004 מצטרפים? \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 ש\u0003ר' יהודה אומר\u0004 שכל הקליפות מצטרפות למאכל \u0003חוץ מקליפי פולין ועדשים!\u0004 ומשיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 הדבר \u0005קשה],\u0006 \u0003הא\u0004 \u0005[זה]\u0006 ששנינו שלדעת ר' יהודה קליפות פולים מצטרפות הרי זה \u0003בחדתי\u0004 \u0005[ב\u0006פולים \u0005חדשים,\u0006 טריים\u0005],\u0006 ואילו \u0003הא\u0004 \u0005[זה]\u0006 ששנינו שלדעתו אינן מצטרפות הרי זה \u0003בעתיקי\u0004 \u0005[בישנים].\u0006 ושואלים: \u0003עתיקי מאי טעמא\u0004 \u0005[ישנים מה טעם]\u0006 \u0003לא\u0004 יצטרפו? \u0003אמר ר' אבהו: מפני שנראין\u0004 חלקי קליפתם \u0003כזבובין בקערה,\u0004 ומאוסים לאוכלם, והכל משליכים אותם.","","","","\u0003המוציא\u0004 בשבת \u0003יין\u0004 חי (לא מזוג), שיעורו כדי להתחייב הוא \u0003כדי מזיגת הכוס.\u0004 שנהגו להוסיף מים ליין חי, והמוציא יין חייב בכדי שיעור היין בלבד הראוי לשתייה חשובה. \u0003חלב\u0004 — \u0003כדי גמיעה. דבש\u0004 — \u0003כדי ליתן על הכתית\u0004 (פצע הנעשה מחמת שיפשוף), \u0003שמן\u0004 — \u0003כדי לסוך\u0004 בו \u0003אבר קטן, מים\u0004 — \u0003כדי לשוף\u0004 (לשפשף ולמרוח) \u0003בהם את הקילור\u0004 (תחבושת לעין). \u0003ושאר כל המשקין\u0004 שיעורם \u0003ברביעית\u0004 הלוג, \u0003וכל השופכין ברביעית. ר' שמעון אומר:\u0004 כל המשקים \u0003כולן\u0004 שיעורם \u0003ברביעית\u0004 הלוג. ועוד אמר: \u0003ולא נאמרו כל השיעורין הללו אלא למצניעיהן,\u0004 לאדם המקפיד אשר שומר דבר זה, שרק הוא בלבד חייב על הוצאתו, משום שלגביו הרי זה דבר חשוב, וחיוב ההוצאה הוא לפי חשיבות הדבר למי שהוציאו. ואולם אדם אשר שיעורים אלה קטנים ואינם חשובים בעיניו אינו חייב על הוצאתם.","\u0003תנא\u0004 \u0005[שנינו\u0006 בתוספתא\u0005]:\u0006 שיעור הוצאה ביין הוא \u0003כדי מזיגת כוס יפה.\u0004 ומסבירים: \u0003ומאי\u0004 \u0005[ומהו]\u0006 \u0003כוס יפה\u0004 שאמרו — \u0003כוס של ברכה.\u0004 ו\u0003אמר רב נחמן אמר רבה בר אבוה: כוס של ברכה צריך שיהא בו\u0004 יין \u0003רובע\u0004 (רבע) של \u0003רביעית\u0004 הלוג, \u0003כדי שימזגנו\u0004 במים \u0003ויעמוד\u0004 שיעור היין המזוג \u0003על רביעית\u0004 הלוג. ששיעור המזיגה הוא שלושה חלקים מים לכל חלק יין.","\u0003אמר רבא: אף אנן נמי\u0004 \u0005[אנחנו גם כן]\u0006"],["\u0003תנינא\u0004 \u0005[שנינו]\u0006 במשנה מעין זה: \u0003המוציא יין\u0004 אינו מתחייב אלא אם כן הוציא בשיעור \u0003כדי מזיגת כוס, ותני עלה\u0004 \u0005[ושנינו עליה,\u0006 על הלכה זו\u0005]:\u0006 שיעור זה הוא \u0003כדי מזיגת כוס יפה. וקתני סיפא\u0004 \u0005[ושנינו בסופה\u0006 של המשנה\u0005]:\u0006 \u0003\"ושאר כל המשקין ברביעית\".\u0004 והרי ששיעור חשוב של משקה הוא ברביעית, ומן הסתם גם יין מזוג זהו שיעורו. \u0003ורבא לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005],\u0006 ש\u0003אמר רבא: כל חמרא דלא דרי על חד תלת מיא לאו חמרא\u0004 \u0005[יין שאינו מושך,\u0006 מספיק, \u0005לשלושה\u0006 חלקים \u0005מים לא יין]\u0006 \u0003הוא.\u0004 שצריך היין להיות חזק עד כדי כך שיוכל למוזגו בכמות גדולה פי שלושה על מים.","\u0003אמר אביי: שתי תשובות\u0004 לסתור יש \u0003בדבר; חדא, דתנן\u0004 \u0005[אחת, ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]\u0006 שהיין \u0003המזוג\u0004 שעל פיו קובעים מה הוא בדיוק הצבע האדום הריהו \u0003שני חלקי מים ואחד יין, מן היין השירוני\u0004 (שבשרון). הרי שמזיגה היא בשליש יין. \u0003ועוד:\u0004 משמע שדי בהוצאת שיעור היין עצמו הנמזג לכדי רביעית, ששיעורו אינו אלא כדי רבע רביעית, כדי להתחייב, אף שעדיין לא נמזגו בו המים בפועל, וכי יתכן שיהיו ה\u0003מים בכד ומצטרפין?!\u0004 והלא יין זה לא יהא ראוי לשתיה עד שיוסיפו לו את המים שבכד?","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא: הא דקאמרת\u0004 \u0005[זה שאמרת]\u0006 שיעור זה ששנינו לענין צבע אדום שהוא \u0003שני חלקי מים ואחד יין מן היין השירוני\u0004 — אין זו הוכחה, כי \u0003יין השירוני לחוד, דרפי\u0004 \u0005[\u0006שהוא \u0005רפה],\u0006 ודי במזיגתו בשני חלקים מים. \u0003אי נמי\u0004 \u0005[או גם כן]\u0006 אפשר לומר כי \u0003התם\u0004 \u0005[שם]\u0006 נקבע השיעור \u0003משום חזותא\u0004 \u0005[מראה],\u0006 \u0003אבל לטעמא בעי טפי\u0004 \u0005[ל\u0006צורך \u0005טעם\u0006 טוב \u0005דרוש יותר\u0006 מים\u0005]\u0006 \u0003ודקאמרת\u0004 \u0005[ומה שאמרת]\u0006 ושאלת: וכי יתכן שיהיו ה\u0003מים בכד ומצטרפין\u0004 — יש לומר כי \u0003לענין\u0004 חיוב הוצתאה ב\u0003שבת מידי דחשיב בעינן\u0004 \u0005[דבר\u0006 \u0003חשוב אנו צריכים], והא נמי הא חשיב\u0004 \u0005[וזה גם כן\u0006 רובע רביעית יין \u0005הריהו חשוב].\u0006","\u0003תנא\u0004 \u0005[שנינו\u0006 בתוספתא\u0005]\u0006 שנינו: יין \u0003יבש\u0004 (קרוש) שיעורו לענין \u0003הוצאה בכזית,\u0004 אלו \u0003דברי ר' נתן. אמר רב יוסף: ר' נתן ור' יוסי בר' יהודה אמרו דבר אחד. ר' נתן\u0004 — \u0003הא דאמרן\u0004 \u0005[זו שאמרנו],\u0006 \u0003ור' יוסי בר' יהודה, דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' יהודה אומר: ששה דברים מקולי\u0004 (הדברים שהקלו בדינם) \u0003בית שמאי ומחומרי\u0004 (הדברים שהחמירו בדינם) \u0003בית הלל,\u0004 וביניהם \u0003דם נבלה.\u0004 ש\u0003בית שמאי מטהרין,\u0004 שלדעתם נבלה מטמאה רק בבשרה, \u0003ובית הלל מטמאין. אמר ר' יוסי בר' יהודה: אף כשטמאו בית הלל, לא טמאו אלא בדם שיש בו רביעית, הואיל ויכול לקרוש\u0004 (להתייבש) \u0003ו\u0004עדיין \u0003לעמוד על\u0004 שיעור \u0003כזית,\u0004 וצירף רב יוסף את שתי השיטות, שלדעתו שני החכמים סבורים כי נוזל שהיתה בו רביעית כאשר הוא מתייבש שיעורו בכזית.","\u0003אמר אביי: דילמא לא היא\u0004 \u0005[שמא אין זו\u0006 השוואה\u0005];\u0006 שכן \u0003עד כאן לא\u0004 שמענו כי \u0003קאמר\u0004 \u0005[אמר]\u0006 \u0003ר' נתן הכא דבעי רביעית\u0004 \u0005[כאן\u0006 ביין, \u0005שדרושה רביעית]\u0006 \u0003אלא ביין דקליש\u0004 \u0005[שהוא קלוש,\u0006 שאיננו סמיך\u0005],\u0006 \u0003אבל בדם דסמיך\u0004 \u0005[ש\u0006הוא \u0005סמיך]\u0006 — כדי שכאשר יתייבש יהיה שיעורו \u0003כזית לא בעי\u0004 \u0005[אינו צריך]\u0006 \u0003רביעית,\u0004 כי כזית דם יבש הריהו יותר מאשר רביעית דם נוזל. \u0003אי נמי\u0004 \u0005[או גם כן]\u0006 נאמר טעם אחר, \u0003עד כאן לא\u0004 שמענו כי \u0003קאמר\u0004 \u0005[אמר]\u0006 \u0003ר' יוסי בר' יהודה התם\u0004 \u0005[שם]\u0006 בדין נבילות ש\u0003כזית סגי ליה\u0004 \u0005[די לו]\u0006 \u0003ברביעית אלא בדם דסמיך\u0004 \u0005[ש\u0006הוא \u0005סמיך],\u0006 \u0003אבל יין דקליש\u0004 \u0005[שהוא קלוש,\u0006 שאיננו סמיך\u0005]\u0006 הרי כדי שיהיה לכשיתייבש בשיעור \u0003כזית הוי\u0004 \u0005[הריהו]\u0006 צריך להיות בהיותו לח \u0003יותר מ\u0004כדי שיעור \u0003רביעית, ו\u0004אפילו \u0003כי מפיק\u0004 \u0005[כאשר מוציא]\u0006 בשבת שיעור \u0003פחות מכזית ליחייב\u0004 \u0005[שיתחייב],\u0006 ואם כן אין הוכחה גמורה לשוויון הדעות בין התנאים.","במשנה נאמר ששיעור הוצאה ב\u0003חלב\u0004 הריהו \u0003כדי גמיעה. איבעיא להו\u0004 \u0005[נשאלה להם\u0006 לחכמים השאלה\u0005]\u0006 האם יש לגרוס \u0003\"כדי גמיאה\"\u0004 ב־א', \u0003או \"כדי גמיעה\"\u0004 ב־ע'. \u0003אמר רב נחמן בר יצחק:\u0004 יש לכתוב בא', שבמקרא מצינו \u0003\"\u0004ויאמר \u0003הגמיאיני נא מעט מים מכדך\"\u0004 (בראשית כד, יז).","\u0003אבעיא להו\u0004 \u0005[נשאלה להם]\u0006 לבני הישיבה שאלה דומה ביחס לכתיב הנכון:"],["\u0003\"גראינין\"\u0004 ב־א', \u0003או \"גרעינין\"\u0004 ב־ע'? \u0003אמר רבא בר עולא:\u0004 יש לכתוב ב־ע', והמלה היא מאותו שורש כמו \u0003\"ונגרע מערכך\"\u0004 (ויקרא כז, יח).","\u0003אבעיא להו\u0004 \u0005[נשאלה להם]\u0006 לבני הישיבה שאלה דומה: האם אומרים על גחלים שאינן בוערות היטב \u0003\"אוממות\" או \"עוממות\"? אמר רב יצחק בר אבדימי:\u0004 יש לכתוב ב־ע', כאמור: \u0003\"ארזים לא עממהו בגן אלהים\"\u0004 (יחזקאל לא, ח).","ועוד \u0003אבעיא להו\u0004 \u0005[נשאלה להם]:\u0006 האם אומרים \u0003\"מאמצין\" או \"מעמצין\"\u0004 לגבי עצימת עיניו של מת. \u0003אמר ר' חייא בר אבא\u0004 שכך \u0003אמר ר' יוחנן:\u0004 צריך לכתוב ב־ע', וראייה לדבר מן הכתוב: \u0003\"ועצם עיניו מראות ברע\"\u0004 (ישעיהו לג, טו).","לגופו של שיעור הוצאה החלב \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003המוציא\u0004 בשבת \u0003חלב של בהמה\u0004 שיעורו \u0003כדי גמיאה\u0004 (גמיעה). \u0003חלב של אשה, ולובן\u0004 (חלבון) \u0003של ביצה\u0004 — \u0003כדי\u0004 השיעור הדרוש \u0003ליתן במשיפא\u0004 (החלק הנוגע במקום הכאב) \u0003של קילור\u0004 שהוא תחבושת ששמים על העינים. וגודלו של \u0003קילור\u0004 שאמרו הריהו \u0003כדי\u0004 שאפשר יהא \u0003לשוף\u0004 (לשפשף ולמרוח) \u0003במים,\u0004 את שתי עיניו בידיו. ושאל \u0003רב אשי:\u0004 האם הכוונה היא רק \u0003כדי שיפה\u0004 בלבד \u0003או כדי אחיזה ושיפה,\u0004 שיש להביא בחשבון גם את החלק המשמש לאחיזת הקילור? לשאלה זו לא נמצא פתרון, ועל כן \u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה.","שנינו במשנה כי שיעור \u0003דבש\u0004 הריהו \u0003כדי ליתן על הכתית. תנא\u0004 \u0005[שנינו\u0006 בתוספתא\u0005],\u0006 השיעור המדוייק הוא: \u0003כדי ליתן על פי כתית,\u0004 כלומר, על הפצע בלבד. \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב אשי:\u0004 האם הכוונה \u0003\"על\u0004 ה\u0003כתית\"\u0004 הריהי — \u0003אפומא דכולה כתית\u0004 \u0005[על פי,\u0006 על מקום הפצע, \u0005של כל]\u0006 ה\u0003כתית, או דילמא\u0004 \u0005[שמא]\u0006 הכוונה היא \u0003אמורשא קמא\u0004 \u0005[הפצע הראשון\u0006 של ה\u0003כתית, לאפוקי הודרנא\u0004 \u0005[להוציא את מה שמסביב]\u0006 ש\u0003לא\u0004 ימשח אותו בדבש? אף לשאלה זו לא נמצא פתרון, ועל כן \u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה.","כיון שדובר בכתית הביאו מאמר המזכיר אחת מן הרפואות לכתית. \u0003אמר רב יהודה אמר רב:\u0004 מ\u0003כל מה שברא הקדוש ברוך הוא בעולמו לא ברא דבר אחד לבטלה\u0004 מבחינת האדם; \u0003ברא שבלול\u0004 — כדי \u0003ל\u0004שים אותו על ה\u0003כתית\u0004 לרפואה. \u0003ברא זבוב\u0004 — כדי \u0003ל\u0004שים זבוב כתוש על מקום שעקצה \u0003צירעה, יתוש\u0004 — \u0003לנחש. ונחש\u0004 עצמו — \u0003לחפפית\u0004 (מין גירוי בעור). \u0003וסממית\u0004 (שממית) — \u0003לעקרב.\u0004 ומסבירים: \u0003היכי עביד לה\u0004 \u0005[כיצד עושה הוא אותו,\u0006 את הריפוי\u0005]\u0006 — \u0003מייתי חדא אוכמא וחדא חיורא, ושלקי להו ושייפי לה\u0004 \u0005[מביא\u0006 מבעלי חיים אלה \u0005אחד שחור ואחד לבן, ומבשל אותם ומורח בהם].\u0006","ואגב הזכרת יצורים אלו, מביאים את מה ש\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003חמשה אימות הן\u0004 שמטיל \u0003חלש על\u0004 ה\u0003גבור: אימת מפגיע\u0004 (חיה קטנה) \u0003על ארי, אימת יתוש על הפיל, אימת סממית על העקרב, אימת סנונית על הנשר, אימת כילבית\u0004 (דג קטן) \u0003על לויתן.\u0004 ו\u0003אמר רב יהודה אמר רב: מאי קרא\u0004 \u0005[מהו הפסוק\u0006 הרומז לדברים אלה\u0005]\u0006 — \u0003\"המבליג שד על עז,\u0004 ושוד על מבצר יבוא\u0003\"\u0004 (עמוס ה, ט) שהוא מפרשו: המגביר שדוד על העז, הגיבור.","כיון שדובר בהסברת דברים בטבעו של עולם, מסופר: \u0003ר' זירא אשכח\u0004 \u0005[מצא]\u0006 את \u0003רב יהודה דהוה קאי אפיתחא דבי חמוה\u0004 \u0005[שהיה עומד על פתח בית חמיו],\u0006 \u0003וחזייה דהוה בדיחא דעתיה\u0004 \u0005[וראהו שהיתה דעתו בדוחה],\u0006 \u0003ואי בעי מיניה\u0004 \u0005[ואם היה שואל ממנו]\u0006 \u0003כל חללי עלמא\u0004 \u0005[העולם]\u0006 \u0003הוה אמר ליה\u0004 \u0005[היה אומר,\u0006 עונה \u0005לו]\u0006 תשובות על הכל. ולכן שאל ממנו שאלות בתחומים שונים, שאינם שייכים להלכה. ושאל: \u0003מאי טעמא עיזי מסגן ברישא והדר אימרי\u0004 \u0005[מה טעם\u0006 בעדר \u0005העיזים הולכות בראש, ואחר כך הכבשים]?\u0006 אמר לו: מנהג הדבר הוא \u0003כברייתו של עולם, דברישא חשוכא והדר נהורא\u0004 \u0005[שבתחילה חושך ואחר כך אור]\u0006 והעיזים שרובן שחורות קודמות לכבשים שרובן לבנות. ועוד שאל: \u0003מאי טעמא הני מכסיין והני מגליין\u0004 \u0005[מה טעם אלו\u0006 הרחלים \u0005מכוסות\u0006 ערוותיהן באליה, \u0005ואלו\u0006 העזים \u0005מגולות]?\u0006 ענה לו: \u0003הני דמכסינן מינייהו\u0004 \u0005[אלה,\u0006 הכבשים, \u0005שאנו מתכסים מהן,\u0006 מצמרן\u0005]\u0006 — שכרן שהן \u0003מכסיין\u0004 \u0005[מכוסות],\u0006 \u0003והני דלא מכסינן מינייהו\u0004 \u0005[ואלה,\u0006 העיזים, \u0005שאין אנו מתכסים מהן\u0006 משערן\u0005]\u0006 — הריהן \u0003מגליין\u0004 \u0005[מגולות].\u0006 ועוד שאל: \u0003מאי טעמא גמלא זוטר גנובתיה\u0004 \u0005[מה טעם הגמל קצר זנבו]?\u0006 ענה לו: \u0003משום דאכל כיסי\u0004 \u0005[ש\u0006הוא \u0005אוכל קוצים]\u0006 וזנב ארוך היה מסתבך בקוצים. ושאל עוד: \u0003מאי טעמא תורא אריכא גנובתיה\u0004 \u0005[מה טעם השור זנבו ארוך]?\u0006 והסביר לו: \u0003משום דדייר באגמי, ובעי לכרכושי בקי\u0004 \u0005[ש\u0006הוא \u0005דר באחו וצריך לגרש זבובים עוקצים].\u0006","והוסיף ושאל: \u0003מאי טעמא קרנא דקמצא רכיכא\u0004 \u0005[מה טעם קרן\u0006 המישוש \u0005של החגב רכה]?\u0006 אמר לו: \u0003משום דדיירא בחילפי, ואי קשיא נדיא ומתעוורא\u0004 \u0005[ש\u0006הוא \u0005דר בין העשבים ואם היתה\u0006 הקרן \u0005קשה,\u0006 היתה \u0005נשברת ומתעוור\u0006 החגב\u0005],\u0006 שמשמאבד החגב את כלי המישוש הריהו מאבד את כושר התנועה. שכן \u0003אמר שמואל\u0004: \u0003האי מאן דבעי דליסמיה לקמצא לשלופינהו לקרניה\u0004 \u0005[מי שרוצה לעוור את החגב, שישלוף,\u0006 יחתוך \u0005את קרנו].\u0006 ועוד שאל: \u0003מאי טעמא האי תימרא דתרנגולתא מדלי לעילא\u0004 \u0005[מה טעם העפעף\u0006 התחתון של התרנגולת \u0005מכסה את העליון]?\u0006 אמר לו: \u0003דדיירי אדפי, ואי עייל קטרא מתעוורא\u0004 \u0005[משום\u0006 שהתרנגולים \u0005חיים על קורות\u0006 בבית, \u0005ואם יכנס העשן\u0006 מן הבית לעיניהם ללא כיסוי העפעף היו \u0005מתעוורים],\u0006 ועוד שאל: מדוע קוראים לדלת בארמית \u0003\"דשא\"?\u0004 אמר לו: הוא קיצור של \u0003\"דרך שם\".\u0004 מדוע קוראים למדרגות: \u0003\"דרגא\"?\u0004 אמר לו: הוא קיצור של \u0003\"דרך גג\".\u0004 מדוע קוראים לתבלין \u0003\"מתכוליתא\"?\u0004 אמר לו: הוא קיצור של \u0003\"מתי תכלה דא\"\u0004 \u0005[זו],\u0006 שהתבלין אינם כלים מהר, שמשתמשים בהם בכמויות קטנות. מדוע קוראים לבית \u0003\"ביתא\"?\u0004 אמר לו: הוא קיצור של \u0003\"בא ואיתיב\u0004 \u0005[ואשב]\u0006 \u0003בה\".\u0004 ומדוע קוראים לבית קטן \u0003\"ביקתא\"?\u0004 הסביר לו: הוא קיצור של \u0003\"בי עקתא\"\u0004 \u0005[בית צר].\u0006","לגיגית קוראים \u0003\"כופתא\"\u0004 משום שאומרים עליה \u0003\"כוף ותיב\"\u0004 \u0005[הפוך ושב\u0006 עליה\u0005].\u0006 לבנים הן \u0003\"לבני\"\u0004 והם מרמזים שבית כזה הוא \u0003לבני בני\u0004 \u0005[לבני בנים].\u0006 לגדר העשויה קוצים קוראים \u0003\"הוצא\",\u0004 ואמר רב יהודה שהיא מרמזת שאינה אלא \u0003חציצה\u0004 ולא גדר ממש. לכד ששואבים בו מים קוראים \u0003\"חצבא\",\u0004 והטעם: \u0003שחוצב מים מן הנהר.\u0004 לכד הקטן קוראים \u0003\"כוזה\",\u0004 והוא מרמז על \u0003כזה\u0004 תן לי. להדס שהיו רוקדים בו בחתונה, קראו \u0003\"שוטיתא\",\u0004 מפני שהריקוד נראה כ\u0003שטותא\u0004 \u0005[שטות].\u0006 לכלי גדול שרוחצים בו קוראים \u0003\"משיכלא\",\u0004 והוא מרמז לכך שהוא \u0003מאשי כולה\u0004 \u0005[רוחץ הכל].\u0006 לכלי רחיצה קטן היו קוראים \u0003\"משכילתא\"\u0004 ופירש רב יהודה שנקרא כך משום שהוא \u0003משיא כלתא\u0004 \u0005[רוחץ\u0006 את ה\u0005כלה].\u0006 למכתשת קוראים \u0003\"אסיתא\",\u0004 ונתפרש שהוא כמו \u0003\"חסירתא\"\u0004 \u0005[חסרה],\u0006 שיש בה חלל גדול. לעלי הנכנס ומכה בתוך המכתשת קוראים \u0003\"בוכנה\",\u0004 וטעמו — שהוא כאילו אומר \u0003\"בוא ואכנה\".\u0004","לבגד עליון קוראים \u0003\"לבושה\"\u0004 מפני שהוא גורם לכך ש\u0003לא\u0004 תהיה \u0003בושה,\u0004 כלומר, המתלבש שוב אינו מתבייש. לבגד עליון רחב קוראים \u0003\"גלימא\"\u0004 מפני \u0003שנעשה בו\u0004 הלובש \u0003כגלם,\u0004 שהבגד מכסה הכל ואין רואים את אבריו, אלא צורה גולמית שלו. למעיל יפה קוראים \u0003\"גולתא\"\u0004 מפני שאומרים \u0003\"גלי ואיתיב\"\u0004 \u0005[גלה,\u0006 פשוט את הגולתא, \u0005ואשב]\u0006 כדי לא ללכלך אותה. למיטה קוראים \u0003\"פוריא\"\u0004 מפני \u0003שפרין ורבין עליה.\u0004 לבור ריק קוראים \u0003\"בור זינקא\"\u0004 לפי שהוא נוטריקון: \u0003\"בור זה נקי\"\u0004 ממים. לעטיפה של תלמידי החכמים קוראים \u0003\"סודרא\"\u0004 לפי שהוא נוטריקון של \u0003\"סוד ה' ליראיו\"\u0004 (תהלים כה, יד) (=\"סוד־ירא\"). לארמון קוראים \u0003\"אפדנא\"\u0004 לפי שהוא נוטריקון של \u0003\"אפיתחא דין\"\u0004 \u0005[לפתח זה]\u0006 באים הכל. ואגב דברים אלה, בטבעו של עולם, הביאו מברייתא: \u0003תנו רבנן, שלשה\u0004 בעלי חיים \u0003כל זמן ש\u0004הם \u0003מזקינין\u0004 הריהם \u0003מוסיפין גבורה, ואלו הן: דג, ונחש וחזיר.\u0004","שנינו במשנה ש\u0003שמן\u0004 שיעורו לענין הוצאה בשבת \u0003כדי לסוך\u0004 בו \u0003אבר קטן. אמרי דבי\u0004 \u0005[אמרו\u0006 חכמי \u0005בית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ינאי\u0004 \u0005[אמרו\u0006 חכמי \u0005בית\u0006 מדרשו של \u0005ר' ינאי],\u0006 יש לפרש: \u0003שמן כדי לסוך אבר קטן של קטן בן יומו. מיתיבי\u0004 \u0005[מקשים]\u0006 על כך ממה ששנינו בברייתא: \u0003שמן כדי לסוך אבר קטן, וקטן בן יומו. מאי לאו\u0004 \u0005[האם לא]\u0006 יש לפרש: \u0003אבר קטן\u0004 של \u0003גדול,\u0004 או \u0003אבר גדול של קטן בן יומו!\u0004 ודוחים \u0003אמרי\u0004 \u0005[אומרים]\u0006 \u0003לך דבי\u0004 \u0005[\u0006חכמי \u0005בית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ינאי, הכי קאמר\u0004 \u0005[כך אמר,\u0006 נתכוון לומר\u0005]:\u0006 \u0003שמן כדי לסוך אבר קטן\u0004 ובאבר קטן של איזה קטן אמרו — \u0003של קטן בן יומו.\u0004","ומציעים: \u0003לימא כתנאי\u0004 \u0005[\u0006האם \u0005נאמר\u0006 שיש בכך מחלוקת \u0005תנאים]?\u0006 ששנינו בברייתא: \u0003שמן כדי לסוך\u0004 בו \u0003אבר קטן, וקטן בן יומו,\u0004 אלו \u0003דברי ר' שמעון בן אלעזר. ר' נתן אומר: כדי לסוך אבר קטן. מאי לאו בהא קמיפלגי\u0004 \u0005[האם לא בדבר זה נחלקו]\u0006 ש\u0003ר' שמעון בן אלעזר סבר\u0004 \u0005[סבור]\u0006 כי הכוונה היא ל\u0003אבר קטן של\u0004 תינוק \u0003קטן, ו\u0004אילו \u0003ר' נתן סבר\u0004 \u0005[סבור]\u0006 כי הכוונה היא ל\u0003אבר קטן\u0004 של \u0003גדול, או אבר גדול\u0004 של \u0003קטן. אבל אבר קטן של קטן בן יומו\u0004 — \u0003לא.\u0004 ודוחים: \u0003לא, דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 שמן כדי סיכת \u0003אבר קטן\u0004 של \u0003קטן בן יומו לא\u0004 מגיע לשיעור הדרוש,"],["\u0003ו\u0004אולם \u0003ליתא\u0004 \u0005[אין\u0006 מקבלים\u0005]\u0006 את שיטת \u0003ר' ינאי\u0004 \u0005[אין\u0006 מקבלים דעת \u0005ר' ינאי].\u0006 \u0003והכא בהא קמיפלגי\u0004 \u0005[וכאן,\u0006 בברייתא זו \u0005בזה נחלקו]\u0006 ש\u0003ר' שמעון בן אלעזר סבר:\u0004 כי \u0003אבר\u0004 קטן של \u0003גדול ואבר גדול\u0004 של \u0003קטן בן יומו כי הדדי נינהו\u0004 \u0005[שווים זה לזה]\u0006 \u0003ור' נתן סבר: אבר קטן\u0004 של \u0003גדול אין\u0004 \u0005[כן],\u0006 ו\u0003אבר גדול\u0004 של \u0003קטן בן יומו\u0004 — \u0003לא,\u0004 שהוא גדול יותר. ושואלים \u0003מאי הוי עלה\u0004 \u0005[מה היה עליה]\u0006 על שאלה זו? \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראייה לדבר ממה ששנינו בברייתא אחרת. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 ש\u0003ר' שמעון בן אלעזר אומר\u0004 במפורש: שיעור הוצאה המחייב ב\u0003שמן\u0004 הוא \u0003כדי לסוך אבר קטן של קטן בן יומו.\u0004","במשנה נקבע שיעור להוצאת \u0003מים כדי לשוף\u0004 (לשפשף ולמרוח) \u0003בהן את הקילור\u0004 (תחבושת לעין). \u0003אמר אביי: מכדי כל מילתא דשכיחא ולא שכיחא, אזול רבנן בתר דשכיחא לקולא\u0004 \u0005[והרי\u0006 לענין שבת \u0005כל דבר ש\u0006שימושו \u0005מצוי\u0006 \u0005ואינו מצוי הלכו חכמים אחרי\u0006 השימוש \u0005המצוי\u0006 ואף \u0005להקל].\u0006 שאף שלדבר אחד שתי אפשרויות שימוש, כאשר אחת \u0003מהן מצויה יותר, אף שלצורכה דרוש שיעור גדול יותר, מכל מקום התייחסו חכמים אל הדבר כאילו זהו שימושו היחיד, ונמצא שלהקל באו. וכאשר יש בו שני שימושים, שכיחא ושכיחא\u0004 \u0005[\u0006שימוש \u0005מצוי\u0006 ושימוש \u0005מצוי\u0006 אחר\u0005]\u0006 — \u0003אזול רבנן בתר דשכיחא לחומרא\u0004 \u0005[\u0006\u0005הלכו חכמים אחרי המצוי להחמיר],\u0006 ושיערו בשיעור הקטן יותר.","וראייה לדבר — \u0003יין שתייתו שכיחא\u0004 \u0005[מצויה]\u0006 ואילו \u0003רפואתו\u0004 (להתרפא בו) \u0003לא שכיחא\u0004 \u0005[אינה\u0006 \u0003מצויה], אזול רבנן בתר שתייתו דשכיחא לקולא\u0004 \u0005[הלכו חכמים אחרי שתייתו ש\u0006היא \u0005מצויה להקל],\u0006 ואמרו ששיעור הוצאת יין כשיעור שתייתו שהוא גדול מכדי שיעורו לרפואה. \u0003חלב, אכילתו שכיחא\u0004 \u0005[מצויה]\u0006 ואילו \u0003רפואתו לא שכיחא\u0004 \u0005[אינה מצויה],\u0006 \u0003אזול רבנן בתר\u0004 \u0005[\u0006ו\u0005הלכו חכמים אחרי]\u0006 שיעור הראוי ל\u0003אכילתו\u0004 שהוא גדול מן השיעור הראוי לרפואתו אף שהוא \u0003לקולא\u0004 \u0005[להקל].\u0006 ואילו \u0003דבש\u0004 ש\u0003גם אכילתו שכיחא\u0004 \u0005[מצויה]\u0006 וגם \u0003רפואתו שכיחא\u0004 \u0005[מצויה]\u0006 — \u0003אזול רבנן בתר\u0004 \u0005[הלכו חכמים אחרי]\u0006 השיעור הקטן שהוא די ל\u0003רפואתו לחומרא\u0004 \u0005[להחמיר].\u0006","\u0003אלא מים מכדי\u0004 \u0005[הרי]\u0006 \u0003שתייתו שכיחא\u0004 \u0005[מצויה]\u0006 ואילו \u0003רפואתו לא שכיחא\u0004 \u0005[אינה מצויה],\u0006 \u0003מאי טעמא אזול רבנן בתר\u0004 \u0005[מה טעם הלכו חכמים אחרי]\u0006 \u0003רפואתו לחומרא\u0004 \u0005[להחמיר]?\u0006 והלא לפי הכלל האמור היה \u0005צריך ללכת אחרק שיעור שתייתם להקל!\u0006 \u0003אמר אביי: בגלילא\u0004 \u0005[בגליל]\u0006 \u0003שנו\u0004 הלכה זו, שרגילים שם בשתיית יין עד ששתיית מים אינה מצויה יותר מרפואה במים (תוספות). \u0003רבא אמר: אפילו תימא\u0004 \u0005[תאמר]\u0006 שההלכה נקבעה כך לא רק בגליל אלא אף \u0003בשאר מקומות,\u0004 ואולם השימוש במים לצורכי קילור שכיח, ו\u0003כ\u0004דברי \u0003שמואל,\u0004 ש\u0003אמר שמואל: כל שקייני מסו ומטללי לבר ממיא דמסו ולא מטללי\u0004 \u0005[כל המשקים\u0006 ששמים על העינים \u0005מרפאים, ו\u0006אולם \u0005מחשיכים\u0006 את העין, \u0005חוץ ממים שמרפאים ואינם מחשיכים].\u0006","שנינו במשנה ששיעור \u0003שאר כל המשקין ברביעית. תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בתוספתא: \u0003דם וכל מיני משקין\u0004 שיעורם לענין הוצאה בשבת הוא \u0003ברביעית. ר' שמעון בן אלעזר אומר: דם\u0004 שיעורו קטן יותר, והוא \u0003כדי לכחול\u0004 בו \u0003עין אחת, שכן כוחלין\u0004 בדם \u0003ל\u0004רפא \u0003ברקית\u0004 (יבלת שבעין). ושואלים: \u0003ומאי נינהו\u0004 \u0005[ומה הוא]\u0006 הדם המועיל לכך? \u0003— דמא דתרנגולת ברא\u0004 \u0005[דם של תרנגולת בר].\u0006 \u0003רבן שמעון בן גמליאל אומר:\u0004 שיעור ה\u0003דם\u0004 הוא \u0003כדי לכחול בו\u0004 בתוך \u0003עין אחת שכן כוחלין ליארוד\u0004 (תבלול שבעין) \u0003ומאי ניהו\u0004 \u0005[ומה הוא]\u0006 הדם המועיל לכך? \u0003— דמא דכרושתינא\u0004 \u0005[דם של עטלף].\u0006 \u0003וסימניך\u0004 \u0005[וסימן\u0006 יהא \u0005לך]\u0006 שלא תחליף בין רפואות אלו שבדם: \u0003גוא לגוא\u0004 \u0005[פנימי לפנימי]\u0006 שליארוד שהוא בתוך העין משתמשים בדם עטלף המצוי בתוך היישוב. \u0003ברא לברא\u0004 \u0005[חיצוני לחיצוני],\u0006 שלרפא ברקית שהיא מחוץ לעין משתמשים בדם תרנגולת בר, החיה מחוץ לישוב.","ומעירים: \u0003במה דברים אמורים\u0004 שזהו השיעור לחומרים אלה — \u0003במוציא\u0004 אותם מרשות לרשות סתם, ואין לו בהם חשיבות מיוחדת, \u0003אבל במצניע\u0004 אותם שבכך הוא מראה שהוא מחשיב אותם במאד — בכל שיעור \u0003חייב.\u0004 ואילו \u0003ר' שמעון אומר: במה דברים אמורים\u0004 שיעורים אלה — \u0003במצניע\u0004 כמותם, \u0003אבל במוציא\u0004 סתם — \u0003אינו חייב אלא ב\u0004כדי שיעור \u0003רביעית. ומודים חכמים לר' שמעון במוציא שופכין לרשות הרבים ששיעורן ברביעית\u0004 אפילו כשמוציא סתם.","\u0003אמר מר\u0004 \u0005[החכם]\u0006 בתוספתא: \u0003במה דברים אמורים\u0004 שיעורים הללו — \u0003במוציא, אבל במצניע\u0004 — שיעורם ב\u0003כל שהוא.\u0004 ותוהים: \u0003אטו\u0004 \u0005[האם]\u0006 ה\u0003מצניע לאו\u0004 \u0005[לא]\u0006 בכלל \u0003מוציא הוא?\u0004 שהרי על הצנעה בלבד אין אדם מתחייב, אלא על הוצאת המוצנע! \u0003אמר אביי: הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — כגון \u0003בתלמיד שאמר לו רבו: לך ופנה לי המקום לסעודה.\u0004 ו\u0003הלך ופנה לו\u0004 והוציא את הדברים לרשות אחרת. ואז אם פינה \u0003דבר\u0004 ה\u0003חשוב לכל\u0004 — \u0003חייב עילויה\u0004 \u0005[עליו],\u0006 \u0003דבר שאינו חשוב לכל, אי אצנעיה רביה\u0004 \u0005[אם הצניעו רבו]\u0006 — \u0003מיחייב עילויה\u0004 \u0005[חייב עליו],\u0006 \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא\u0004 הצניעו רבו — \u0003לא מיחייב\u0004 \u0005[אינו חייב\u0006 עליו\u0005],\u0006 שהתלמיד עושה דברים כפי שרבו מעונין בהם.","עוד \u0003אמר מר\u0004 \u0005החכם\u0006 בתוספתא: \u0003מודים חכמים לר' שמעון במוציא שופכין לרשות הרבים ששיעורן ברביעית.\u0004 ושואלים: \u0003שופכין למאי חזו.\u0004 \u0005[למה\u0006 הם \u0005ראויים]?\u0006 \u0003אמר ר' ירמיה:\u0004 משתמשים בהם כדי \u0003לגבל\u0004 (ללוש) \u0003בהן את הטיט.\u0004 ומקשים: אם לצורך זה, מה צורך יש בשיעור גדול כל כך? \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003טיט\u0004 שיעורו להוצאת שבת \u0003כדי לעשות בהן פי כור\u0004 (מכסה לכור קטן) ושיעור זה פחות בהרבה! ומשיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 \u0003הא\u0004 \u0005[זה ששנינו]\u0006 ששיעורו כדי לעשות בו פי כור הרי זה באופן \u0003דמיגבל\u0004 \u0005[ש\u0006הוא כבר \u0005מגובל],\u0006 ואילו \u0003הא\u0004 \u0005[זה]\u0006 ששנינו ששיעור ההוצאה במים הוא כדי שיעור רביעית כשהשימוש בהן הוא לגיבול הטיט — הרי זה באופן \u0003דלא מיגבל\u0004 \u0005[שאינו מגובל]\u0006 \u0003לפי שאין אדם טורח לגבל טיט\u0004 כדי \u0003לעשות פי כור\u0004 בלבד. ולכן במים שמוציאים כדי לגבל את הטיט מתחילה יש צורך בשיעור גדול, אבל טיט הראוי כבר לשימוש עושים בו אף חפצים קטנים.","\u0003המוציא חבל\u0004 שיעורו \u0003כדי לעשות אוזן לקופה\u0004 (סל). \u0003גמי\u0004 (חלק מקנה סוף, גומא), שיעורו לענין הוצאה — \u0003כדי לעשות תלאי\u0004 (אוזן שתולים בה) \u0003לנפה ולכברה. ור' יהודה אומר:\u0004 שיעורו \u0003כדי ליטול ממנו מדת מנעל ל\u0004צורך ילד \u0003קטן,\u0004 שבגמי מודדים את גודל רגלו. \u0003נייר\u0004 שיעורו לענין הוצאה הוא \u0003כדי לכתוב עליו קשר מוכסין\u0004 (מעין קבלה עבור המכס). \u0003והמוציא קשר מוכסין\u0004 עצמו בשבת — \u0003חייב.\u0004"],["\u0003נייר מחוק\u0004 שאי אפשר לכתוב עוד עליו, שיעורו \u0003כדי לכרוך\u0004 ולעטוף בו \u0003צלוחית קטנה של פלייטון\u0004 (בושם). \u0003עור\u0004 — \u0003כדי לעשות\u0004 ממנו \u0003קמיע. דוכסוסטוס\u0004 (סוג עור מיוחד) — \u0003כדי לכתוב\u0004 עליו \u0003מזוזה. קלף\u0004 — \u0003כדי לכתוב עליו\u0004 את ה\u0003פרשה\u0004 ה\u0003קטנה\u0004 בפרשיות \u0003שבתפילין, שהיא \"שמע ישראל\".\u0004 המוציא \u0003דיו\u0004 שיעורו \u0003כדי לכתוב\u0004 בו \u0003שתי אותיות.\u0004","ו\u0003כחול\u0004 לעיניים שיעורו \u0003כדי לכחול עין אחת. דבק כדי ליתן בראש השפשף\u0004 (שלוכדים בו צפורים). \u0003זפת וגפרית\u0004 — \u0003כדי לעשות נקב,\u0004 שיספיק שיעור הזפת לסתום חור בכלי, ושאפשר יהיה לעשות באותה סתימה נקב קטן. \u0003שעוה\u0004 — \u0003כדי ליתן על פי נקב קטן. חרסית\u0004 (חרס כתוש) שיעורה לענין הוצאה בשבת — \u0003כדי לעשות\u0004 ולגבל ממנה \u0003פי כור של צורפי זהב. ר' יהודה אומר: כדי לעשות\u0004 ממנה \u0003פיטפוט\u0004 (רגל קטנה). \u0003סובין\u0004 — \u0003כדי ליתן על פי כור של צורפי זהב. סיד כדי לסוד\u0004 כדי להוריד את השיער מה \u0003קטנה שבבנות. ר' יהודה אומר:\u0004 ששיעור סיד הוא \u0003כדי לעשות כלכל\u0004 (חלק מן הפנים). ו\u0003ר' נחמיה אומר\u0004 ששיעורו \u0003כדי לסוד אונדפי\u0004 (רקה).","שנינו במשנה ששיעור חבל לענין הוצאה הוא שיהיה בו כדי לעשות בו אוזן לסל. ומקשים: \u0003חבל נמי ליחייב\u0004 \u0005[גם כן יהא חייב]\u0006 כגמי בשיעור \u0003לעשות תלאי לנפה ולכברה!\u0004 ומשיבים: \u0003כיון דחריק במנא לא עבדי אינשי\u0004 \u0005[ש\u0006הוא קשה ו\u0005חותך את הכלי אין עושים\u0006 ממנו אנשים תלאי\u0005].\u0006 \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 שיעור \u0003הוצין\u0004 (העלים הקשים של התמר) \u0003כדי לעשות אוזן לסל\u0004 של \u0003כפיפה מצרית\u0004 (סל העשוי מנצרי תמר קלועים). \u0003סיב\u0004 — \u0003אחרים אומרים:\u0004 ששיעורו \u0003כדי ליתן על פי משפך קטן לסנן\u0004 בו \u0003את היין. רבב\u0004 (שומן) — \u0003כדי לסוך תחת אספגין\u0004 (עוגה) \u0003קטנה. וכמה שיעורה\u0004 של זו? — \u0003כ\u0004גודלו של \u0003סלע.\u0004 ומקשים: \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 ששיעורה \u0003כגרוגרת!\u0004 ומשיבים: \u0003אידי ואידי חד שיעורא\u0004 \u0005[זה וזה שיעור אחד]\u0006 \u0003הוא,\u0004 אלא שכסלע הוא שיעור רוחב, וכגרוגרת הוא מידת נפח. ו\u0003מוכין\u0004 שיעורם \u0003כדי לעשות\u0004 מהם \u0003כדור קטנה, וכמה שיעורו\u0004 של הכדור? — \u0003כאגוז.\u0004","שנינו ששיעור \u0003נייר\u0004 לענין הוצאה הריהו כשיש בגודלו \u0003כדי לכתוב עליו קשר מוכסין.\u0004 ובתוספתא \u0003תנא\u0004 \u0005[שנה]\u0006 החכם: \u0003כמה\u0004 גודלו \u0003של קשר מוכסין\u0004 — כדי לכתוב עליו \u0003שתי אותיות של קשר מוכסין\u0004 שהן גדולות יותר מאותיות רגילות. \u0003ורמינהו\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 לכך ממה ששנינו: \u0003המוציא נייר חלק, אם יש בו כדי לכתוב שתי אותיות\u0004 — \u0003חייב, ואם לאו\u0004 \u0005[לא]\u0006 — \u0003פטור.\u0004 ושיעור זה הוא פחות מקשר מוכסין! \u0003אמר רב ששת: מאי\u0004 \u0005[מה\u0006 הן\u0005]\u0006 \u0003שתי אותיות\u0004 שאמרנו בנייר, לא שתי אותיות רגילות אלא \u0003שתי אותיות של קשר מוכסין. רבא אמר:\u0004 אפשר לומר שהמדובר ב\u0003שתי אותיות דידן\u0004 \u0005[שלנו,\u0006 רגילות\u0005]\u0006 \u0003ו\u0004גם \u0003בית אחיזה\u0004 להחזיק את החלק הכתוב \u0003דהיינו\u0004 אותו גודל כמו \u0003קשר מוכסין.\u0004","ומקשים ממה ששנינו: \u0003המוציא נייר מחוק\u0004 או \u0003שטר פרוע, אם יש בלובן שלו\u0004 שלא נכתב עליו \u0003כדי לכתוב שתי אותיות, או ב\u0004כל הנייר \u0003כולו כדי לכרוך על פי צלוחית קטנה של פלייטון\u0004 (בושם) — \u0003חייב, ואם לאו\u0004 \u0005[לא],\u0006 שאין בו כשיעור זה — \u0003פטור.\u0004 ומסבירים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004שיטת \u0003רב ששת\u0004 ש\u0003אמר\u0004 כי \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"שתי אותיות\"\u0004 שאמרו בכל מקום, \u0003שתי אותיות של קשר מוכסין\u0004 — \u0003שפיר\u0004 \u0005[יפה,\u0006 מובן הדבר\u0005].\u0006 \u0003אלא לרבא\u0004 ש\u0003אמר\u0004 שמדובר ב\u0003שתי אותיות דידן\u0004 \u0005[שלנו]\u0006 \u0003ובית אחיזה, דהיינו\u0004 \u0005[שזהו]\u0006 \u0003קשר מוכסין,\u0004 והלא \u0003הכא\u0004 \u0005[כאן,\u0006 בתוך הנייר או השטר\u0005]\u0006 \u0003בית אחיזה לא צריך\u0004 ובכל זאת אין קובעים שיעור קטן יותר לנייר החלק! ואומרים: אכן \u0003קשיא\u0004 \u0005[קשה].\u0006","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בתוספתא: \u0003המוציא\u0004 בשבת \u0003קשר מוכסין, עד שלא הראהו למוכס\u0004 ועדיין זקוק לו — \u0003חייב\u0004 על הוצאתו בשבת. \u0003משהראהו\u0004 כבר \u0003למוכס\u0004 — \u0003פטור,\u0004 ששוב אינו בעל ערך. \u0003ר' יהודה אומר: אף משהראהו למוכס חייב מפני ש\u0004יש זמן שיהא \u0003צריך לו.\u0004 ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה\u0006 יש \u0005ביניהם]?\u0006 כלומר, מהו יסוד מחלוקתם? \u0003אמר אביי: איכא בינייהו רהיטי מוכסא\u0004 \u0005[יש ביניהם\u0006 הבדל \u0005בענין הרצים של המוכס],\u0006 שלעתים שולח המוכס רצים אחר אלה שעברו את מקום המכס כדי לבדוק אם אמנם שילמו, ויתכן שאף שהראהו כבר יצטרך להראותו בשנית. \u0003רבא אמר: מוכס גדול ומוכס קטן איכא בינייהו\u0004 \u0005[יש ביניהם],\u0006 שלעתים במקום המוכס הראשי הממונה יש מוכס קטן בדרגה, וצריך להשאיר את הקשר בידו להראותו למוכס הגדול. \u0003רב אשי אמר:\u0004 אפשר לומר שאפילו \u0003חד מוכס איכא בינייהו\u0004 \u0005[\u0006ב\u0005מוכס אחד יש ביניהם\u0006 הבדל\u0005],\u0006 \u0003מפני שצריך לו להראות\u0004 אותו \u0003למוכס שני\u0004 שאינו קשור במקום זה, אלא \u0003דאמר ליה\u0004 \u0005[שאומר לו]\u0006 לשני: \u0003חזי, גברא דמוכס אנא\u0004 \u0005[ראה, איש\u0006 הנאמן \u0005למוכס אני]\u0006 ומראה לו תעודה זו שבידו, לומר שיש לו קשרים טובים עם המוכסים.","עוד \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003המוציא\u0004 בשבת \u0003שטר חוב, עד שלא פרעו\u0004 — \u0003חייב, משפרעו\u0004 — \u0003פטור. ר' יהודה אומר: אף משפרעו\u0004 אם הוציאו — \u0003חייב, מפני שצריך לו.\u0004 ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה\u0006 טעם ההבדל \u0005ביניהם]?\u0006 \u0003אמר רב יוסף:\u0004 בהלכה אם \u0003אסור\u0004 לבעל חוב \u0003לשהות\u0004 (להשהות) אצלו \u0003שטר פרוע איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל\u0005].\u0006 ש\u0003רבנן סברי\u0004 \u0005[חכמים סבורים]:\u0006 \u0003אסור לשהות שטר פרוע,\u0004 שמא יביא הדבר למכשול שיבואו לגבות בו שנית, ולכן שטר פרוע אין לו ערך, שאסור אף בשהיה. \u0003ור' יהודה סבר\u0004 \u0005[סבור]:\u0006 \u0003מותר לשהות שטר פרוע\u0004 ויכול להשתמש בנייר.","\u0003אביי אמר: דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003אסור לשהות שטר פרוע, והכא\u0004 \u0005[וכאן]\u0006 \u0003ב\u0004שאלה אם \u0003מודה בשטר שכתבו שצריך לקיימו, קמיפלגי\u0004 \u0005[חלוקים הם],\u0006 שה\u0003תנא קמא סבר\u0004 \u0005[הראשון סבור]\u0006 אפילו \u0003מודה\u0004 אדם \u0003בשטר שכתבו\u0004 — \u0003צריך\u0004 להביאו לבית דין ו\u0003לקיימו\u0004 על פי חקירה אם אין השטר מזוייף. ואם אי אפשר לקיימו, יכול הלווה לומר — כבר פרעתי את השטר. \u0003ור' יהודה סבר\u0004 \u0005סבור\u0006 כי \u0003מודה בשטר שכתבו אין צריך לקיימו.\u0004 וגובה בו, ונאמן השטר יותר מטענת הלווה. \u0003ומאי\u0004 \u0005[ומה\u0006 פירוש\u0005]\u0006 זה ששנינו \u0003\"עד שלא פרעו\" ו\"משפרעו\"\u0004 —"],["\u0003עד שיאמר\u0004 ה\u0003לוה \"פרעתי \"\u0004או \u0003\"לא פרעתי\".\u0004 ולכן, שטר שאמר הלווה \"פרעתי\" (\"משפרעו\") ואין עליו עדים לקיימו, לשיטת חכמים שהשטר עצמו אינו הוכחה מספקת — אין ערך עוד לשטר. ולשיטת ר' יהודה שאין צריך לקיימו, אף שטען הלווה \"פרעתי\" — אינו נאמן והשטר ראוי לשימוש.","\u0003רבא אמר: דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003מודה בשטר שכתבו\u0004 — \u0003שצריך לקיימו, והכא\u0004 \u0005[וכאן]\u0006 \u0003ב\u0004שאלה אם \u0003כותבין שובר קמיפלגי\u0004 \u0005[חלוקים הם];\u0006 ה\u0003תנא קמא סבר\u0004 \u0005[הראשון סבור]:\u0006 \u0003כותבין שובר\u0004 (קבלה) על שטר שנפרע. וכיון שמחזיק הלווה את השובר יכול המלווה להחזיק בשטר. ויש לו ערך, לפחות לצורך הנייר שבו. \u0003ור' יהודה סבר\u0004 \u0005[סבור]:\u0006 \u0003אין כותבין שובר,\u0004 וצריך המלווה להחזיר את השטר מיד ללווה, ואף הלווה מעונין להשמידו ואין לו אם כן כל סיבה להחזיקו. \u0003רב אשי אמר: מפני שצריך\u0004 הלווה לשטר הפרוע \u0003להראותו לבעל חוב שני, דאמר ליה\u0004 \u0005[שאומר לו]:\u0006 \u0003חזי, גברא דפרע אנא\u0004 \u0005[ראה, אדם שפורע\u0006 חובותיו \u0005אני].\u0006","שנינו במשנה: שיעור ה\u0003עור\u0004 לענין איסור הוצאה בשבת הוא \u0003כדי\u0004 שניתן \u0003לעשות\u0004 ממנו קמיע. \u0003בעא מיניה\u0004 \u0005[שאל ממנו]\u0006 \u0003רבא מרב נחמן: המוציא עור\u0004 בשבת, שיעורו כדי להתחייב \u0003בכמה? אמר ליה\u0004 \u0005[לו]:\u0006 \u0003כדתנן\u0004 \u0005[כפי ששנינו\u0006 במשנה\u0005]:\u0006 \u0003עור כדי לעשות קמיע,\u0004 ועוד שאל: \u0003המעבדו\u0004 לעור בשבת, שיעורו של העור להתחייב בכך, \u0003בכמה?\u0004 אמר לו: \u0003לא שנא\u0004 \u0005[אינו שונה]\u0006 והוא אותו שיעור. ועוד שאל: והמוציא עור בלתי מעובד על מנת \u0003לעבדו,\u0004 שיעורו כדי להתחייב בהוצאה זו, \u0003בכמה? אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לא שנא\u0004 \u0005[אינו שונה],\u0006 והוא אותו שיעור.","\u0003ומנא תימרא\u0004 \u0005[ומנין תאמר,\u0006 תסיק\u0005]\u0006 שאין הבדל אם מוציא עור מעובד או בלתי מעובד — \u0003כדתנן\u0004 \u0005[כפי ששנינו\u0006 במשנה\u0005]:\u0006 \u0003המלבן והמנפץ והצובע והטווה, שיעורו\u0004 שמתחייב אם עשהו בשבת — \u0003כמלא רוחב הסיט\u0004 (המרחק בין האצבע לאמה) \u0003כפול, והאורג שני חוטין, שיעורו\u0004 כדי להתחייב באריגה זו הוא \u0003כמלא רוחב הסיט כפול. אלמא\u0004 \u0005[מכאן]:\u0006 \u0003כיון\u0004 ש\u0003לטוייה קאי\u0004 \u0005[עומד]\u0006 הצמר — \u0003שיעורו\u0004 גם כשעושה מלאכות ליבון וניפוץ הריהו \u0003כטווי. הכי נמי\u0004 \u0005[כך גם כן\u0006 \u0003כיון\u0004 ש\u0003לעבדו קאי\u0004 \u0005[\u0006הוא \u0005עומד]\u0006 \u0003שיעורו כמעובד.\u0004 ועוד שאל רבא: המוציא עור בלתי מעובד \u0003ו\u0004על מנת \u0003שלא לעבדו, בכמה\u0004 שיעורו כדי להתחיייב בהוצאה זו? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לא שנא\u0004 \u0005[אינו שונה].\u0006","והקשה רבא: \u0003ולא שני\u0004 \u0005[ו\u0006כי \u0005אין\u0006 הדין \u0005שונה]\u0006 לענין שיעור העור לענין הוצאה \u0003בין מעובד לשאינו מעובד? איתיביה\u0004 \u0005[הקשה לו]\u0006 על הנחה זו ממה ששנינו: \u0003המוציא סמנין\u0004 של צבע ה\u0003שרוין\u0004 כבר במים וראויים מיד לצביעה, שיעורם להתחייב בהוצאה זו הוא שיהא בהן \u0003כדי לצבוע בהן דוגמא\u0004 וגודלה כדי \u0003אירא\u0004 (לסתום את פי הבוכייר). \u0003ואילו בסמנין שאינן שרוין תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 \u0003קליפי אגוזים וקליפי רמונין\u0004 המשמשים לצבע, וכן חומרי הצבע \u0003סטיס ופואה,\u0004 שיעורם להוצאה הוא \u0003כדי לצבוע בהן בגד קטן לפי סבכה\u0004 המכסה ראש אשה, הרי שהשיעור להוצאת חומרי גלם גדול בהרבה משיעור הצבעים המוכנים! ומשיבים: \u0003הא איתמר עלה\u0004 \u0005[הרי\u0006 כבר \u0005נאמר עליה,\u0006 על משנה זו\u0005]\u0006 ש\u0003אמר רב נחמן אמר רבה בר אבוה: לפי שאין אדם טורח לשרות סמנין\u0004 כדי \u0003לצבוע בהן\u0004 רק \u0003דוגמא לאירא.\u0004 אבל בדרך כלל אין לחלק בין דבר מוגמר ושאינו מוגמר. וכאן הוא מקרה מיוחד, שבכגון זה אין דרכם של בני אדם לטרוח ולהוציא כשאין צריכים אלא לשיעור קטן כל כך, אף שהוא חשוב כשלעצמו.","ועוד הקשה: \u0003והרי זרעוני גינה\u0004 (זרעים של צמחי גן) \u0003דמקמי דזרעינהו\u0004 \u0005[שלפני שזרעם]\u0006 \u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 המוציא בשבת \u0003זרעוני גינה\u0004 שיעורם כדי להתחייב בהוצאה זו הוא \u0003פחות מכגרוגרת. ר' יהודה בן בתירא אומר: חמשה\u0004 זרעונים. \u0003ואילו בתר דזרעינהו תנן\u0004 [אחרי שזרען שנינו במשנה\u0005]:\u0006 המוציא \u0003זבל\u0004 או \u0003חול הדק\u0004 שיעורו \u0003כדי לזבל בו קלח\u0004 אחד \u0003של כרוב,\u0004 אלו \u0003דברי ר' עקיבא. וחכמים אומרים: כדי לזבל כרישא\u0004 (כרתי). הרי שלאחר שנזרע — השיעור החשוב הוא של צמח אחד ולפני זריעה בחמישה לפחות! ומשיבים: \u0003הא איתמר עלה\u0004 \u0005[הרי\u0006 כבר \u0005נאמר עליה]\u0006 על הלכה זו, שיש לחלק בין הדברים; \u0003אמר רב פפא, הא\u0004 \u0005[זה]\u0006 ששנינו שדי בהוצאת אחד הרי זה באופן \u0003דזריע\u0004 \u0005[ש\u0006הוא \u0005זרוע]\u0006 כבר, \u0003הא\u0004 \u0005[זה]\u0006 ששנינו שצריך להוציא לפחות חמישה הרי זה באופן \u0003דלא זריע\u0004 \u0005[שאינו זרוע],\u0006 \u0003לפי שאין אדם טורח להוציא נימא אחת\u0004 (גרעין אחד) \u0003לזריעה.\u0004 אבל בכלל אין הבדל בין דבר מעובד לשאינו מעובד.","ועוד הקשה: \u0003והרי טיט, דמקמי דליגבליה תניא\u0004 \u0005[ש\u0006על \u0005לפני שהוא מגבל אותו שנינו\u0006 בברייתא\u0005]:\u0006 \u0003מודים חכמים לר' שמעון במוציא\u0004 בשבת \u0003שופכין לרשות הרבים ששיעורן\u0004 כדי להתחייב בהוצאתן הוא \u0003ברביעית, והוינן\u0004 \u0005[והיינו עוסקים]\u0006 \u0003בה,\u0004 בשאלה זו: \u0003שופכין למאי חזו\u0004 \u0005[למה\u0006 הם \u0005ראויים]?\u0006 \u0003ואמר ר' ירמיה: לגבל בהן את הטיט,\u0004 הרי ששיעור חומר הגלם הוא בכמות טיט הצריכה לרביעית מים לגבלה, \u0003ואילו בתר דגבליה תניא\u0004 \u0005[\u0006על \u0005אחר שגיבלו שנינו\u0006 בברייתא\u0005]:\u0006 \u0003טיט\u0004 שיעורו לענין איסור הוצאה בשבת הוא \u0003כדי\u0004 שיוכלו \u0003לעשות בהן פי כור,\u0004 והוא שיעור קטן בהרבה! ומשיבים: \u0003התם נמי כדאמרן\u0004 \u0005[שם גם כן כמו שאמרנו]:\u0006 \u0003לפי שאין אדם טורח לגבל את הטיט\u0004 כדי \u0003לעשות בו\u0004 דבר קטן כמו \u0003פי כור\u0004 בלבד.","כדי לפתור את הבעיה ביחס לשיעור העור לענין איסור הוצאה בשבת אומרים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 הלכה ש\u0003אמר ר' חייא בר אמי משמיה\u0004 \u0005[משמו]\u0006 של \u0003עולא: שלשה עורות הן,\u0004 כלומר שלושה שלבים יש בעיבוד העור, ובכל שלב הריהו נקרא בשם שונה; \u0003מצה, וחיפה, ודיפתרא. מצה\u0004 — \u0003כמשמעו\u0004 במלת מצה, והוא עור \u0003דלא מליח\u0004 \u0005[שאינו מלוח],\u0006 \u0003ודלא\u0004 \u0005[ושאינו]\u0006 \u0003קמיח\u0004 (מעובד בקמח), \u0003ודלא\u0004 \u0005[ושאינו]\u0006 \u0003עפיץ\u0004 (מעובד בעפצים). \u0003וכמה שיעורו\u0004 להוצאת שבת? \u0003תני\u0004 \u0005[שנה]\u0006 \u0003רב שמואל בר רב יהודה:\u0004 שיהא בגודלו \u0003כדי\u0004 שיוכלו \u0003לצור בו משקולת קטנה. וכמה\u0004 גודלה של משקולת קטנה זו? \u0003אמר אביי: ריבעא דריבעא\u0004 \u0005[רבע של רביעית]\u0006 הנהוגה ב\u0003פומבדיתא.\u0004","\u0003חיפה,\u0004 משמעו — \u0003דמליח\u0004 \u0005[שהוא מלוח]\u0006 \u0003ולא\u0004 \u0005[ואינו]\u0006 \u0003קמיח ולא\u0004 \u0005[ואינו]\u0006 \u0003עפיץ. וכמה שיעורו\u0004 להוצאת שבת? \u0003כדתנן\u0004 \u0005[כפי ששנינו\u0006 במשנה\u0005]:\u0006 \u0003עור\u0004 שיעורו להוצאת שבת — \u0003כדי לעשות\u0004 בו \u0003קמיע. דיפתרא\u0004 הוא עור \u0003דמליח וקמיח ולא עפיץ\u0004 \u0005[שנמלח,\u0006 שעובד \u0005בקמח, ולא בעפצים]\u0006 \u0003וכמה שיעורו?\u0004 — \u0003כדי לכתוב עליו את הגט. קתני מיהת\u0004 \u0005[מכל מקום למדנו]\u0006 שעור לפני עיבודו שיעורו \u0003כדי לצור בו משקולת קטנה, ואמר אביי: ריבעא דריבעא\u0004 \u0005[רבע של רביעית]\u0006 הנהוגה ב\u0003פומבדיתא,\u0004 ואין זה כמידת העור המעובד שעושים ממנו קמיע! ומתרצים: \u0003התם\u0004 \u0005[שם],\u0006 בדברי הלכה זו מדובר \u0003בבישולא,\u0004 בעור שלא עובד כדרכו אלא הונח להתייבש בחמה ואינו ראוי אלא לצור משקולת (ר\"ח). אבל עור המעובד כדרכו שיעורו להוצאת שבת כדי לעשות בו קמיע.","ועוד מקשים: \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003הבגד\u0004 שיעורו \u0003שלשה על שלשה\u0004 טפחים כדי \u0003ל\u0004טמא טומאת \u0003מדרס,\u0004 אם נשען או יושב (דורס) עליו הזב. \u0003השק\u0004 שיעורו \u0003ארבעה על ארבעה\u0004 טפחים, \u0003העור\u0004 — \u0003חמשה על חמשה. מפץ\u0004 (מחצלת) — \u0003ששה על ששה, בין למדרס ובין\u0004 לטומת \u0003מת. ותאני עלה\u0004 \u0005[ושנו עליה\u0006 בתוספתא\u0005]\u0006 כי \u0003הבגד והשק והעור\u0004 — \u0003כשיעור\u0004 שלו \u0003ל\u0004ענין \u0003טומאה כך שיעור\u0004 שלו \u0003ל\u0004ענין \u0003הוצאה\u0004 בשבת. והרי שיעור זה שונה בהרבה מן השיעור הכתוב במשנה! ומתרצים: מדובר שם \u0003בקורטובלא\u0004 שהוא עור שעובד באופן שאינו ראוי עוד לכתיבה ולצרור בו, ומשתמשים בו לכיסוי כלים וכיוצא בזה (רמב\"ם)."],["שנינו במשנה ש\u0003קלף\u0004 שיעורו להוצאת שבת הוא \u0003כדי לכתוב עליו פרשה קטנה\u0004 שבתפילין. \u0003ורמינהו\u0004 \u0005ומשליכים,\u0006 מראים סתירה\u0005]\u0006 ממה ששנינו ששיעור \u0003קלף ודוכסוסטוס\u0004 הוא \u0003כדי לכתוב עליו מזוזה!\u0004 ומשיבים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"מזוזה\"\u0004 כאן — \u0003מזוזה שבתפילין,\u0004 כלומר, הכתב שבתוך התפילין. ושואלים: \u0003וקרי להו\u0004 \u0005[ו\u0006כי נוהגים \u0005לקרוא\u0006 \u0003להם] לתפילין \"מזוזה\"?\u0004 ומשיבים: \u0003אין\u0004 \u0005[כן],\u0006 \u0003והתניא\u0004 \u0005[ו\u0006אכן כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003רצועות תפילין\u0004 כשהן \u0003עם התפילין מטמאות\u0004 הן \u0003את הידים\u0004 כדין כל הנוגע בכתבי הקודש, ואילו \u0003בפני עצמן\u0004 — \u0003אין מטמאות את הידים. ר' שמעון בן יהודה אומר משום\u0004 (בשם) \u0003ר' שמעון: הנוגע ברצועה\u0004 של תפילין אפילו כשהיא מחוברת לתפילין — \u0003טהור, עד שיגע בקציצה\u0004 (בית התפילין). ו\u0003ר' זכאי משמו\u0004 של ר' שמעון \u0003אומר: טהור עד שיגע במזוזה עצמה.\u0004 הרי שלפרשיות שבתפילין קוראים \"מזוזה\".","ומקשים: \u0003והא מדקתני סיפא\u0004 \u0005[והרי ממה ששנינו בסופה\u0006 של המשנה\u0005]\u0006 \u0003קלף\u0004 — \u0003כדי לכתוב עליו פרשה קטנה שבתפילין, שהיא \"שמע ישראל\", מכלל\u0004 הדברים אתה למד \u0003דרישא\u0004 \u0005[שבראש\u0006 המשנה\u0005]\u0006 \u0003במזוזה עצמה עסקינן\u0004 \u0005[עוסקים אנו]!\u0006 אלא \u0003הכי קתני\u0004 \u0005[כך שנה]:\u0006 \u0003קלף ודוכסוסטוס שיעורן בכמה? דוכסוסטוס\u0004 — \u0003כדי לכתוב עליו מזוזה. קלף\u0004 — \u0003כדי לכתוב עליו פרשה קטנה שבתפילין שהיא \"שמע ישראל\".\u0004","\u0003אמר רב: דוכסוסטוס הרי היא כקלף, מה קלף כותבים עליו תפילין, אף דוכסוסטוס כותבים עליו תפילין.\u0004 ומקשים: במשנה שנינו כי \u0003קלף\u0004 שיעורו להוצאת שבת \u0003כדי לכתוב\u0004 עליו \u0003פרשה קטנה שבתפילין שהיא \"שמע ישראל\",\u0004 והאם אין ללמוד מזה כי \u0003קלף\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 כשר לתפילין \u0003דוכסוסטוס לא?!\u0004 ומשיבים: אין מכאן ראייה, כי במשנה מדובר \u0003ל\u0004הידור \u0003מצוה,\u0004 ומצווה מן המובחר לכתוב תפילין על הקלף, אבל מן הדין גם דוכסוסטוס כשר לתפילין. \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו בברייתא: \u0003הלכה למשה מסיני\u0004 היא שיהיו ה\u0003תפילין\u0004 כתובים \u0003על הקלף ומזוזה על דוכסוסטוס. קלף,\u0004 כותבים עליו \u0003במקום\u0004 (בצד) הפונה אל ה\u0003בשר, דוכסוסטוס במקום\u0004 הפונה אל ה\u0003שיער.\u0004 וקשה איפוא לדברי רב האומר כי התפילין נכתבות על הדוכסוסטוס! ומשיבים: אף שם לא נאמרו הדברים כחובה אלא \u0003למצוה\u0004 בלבד.","ומקשים: \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 שאם \u0003שינה\u0004 וכתב על דבר אחר \u0003פסול,\u0004 ומשמע שאין התפילין נכתבות בשום אופן על גבי הדוססוסטוס\u0003!\u0004 ודוחים: דבר זה נאמר על ה\u0003מזוזה,\u0004 שאם כתבה על קלף פסולה. ומקשים עוד: \u0003והתניא\u0004 \u0005[והרי שנינו]\u0006 בברייתא אחרת: \u0003שינה בזה ובזה פסול!\u0004 ודוחים: \u0003אידי ואידי\u0004 \u0005[זה וזה]\u0006 מדובר בענין ה\u0003מזוזה, והא דכתבינהו\u0004 \u0005[וזה,\u0006 פסול אחד\u0005]\u0006 בששינה וכתב על ה\u0003קלף במקום שיער, אי נמי\u0004 \u0005[או גם כן]\u0006 כאשר שינה וכתב \u0003דוכסוסטוס במקום בשר. ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 תירוץ אחר: \u0003שינה בזה ובזה\u0004 אם נפסל או לא \u0003תנאי\u0004 \u0005[\u0006מחלוקת \u0005תנאים]\u0006 \u0003היא.\u0004 ששנינו: \u0003שינה בזה ובזה\u0004 — \u0003פסול. ר' אחא מכשיר משום\u0004 (בשם) \u0003ר' אחי בר חנינא, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 \u0003משום ר' יעקב בר' חנינא.\u0004 ו\u0003רב פפא אמר: רב\u0004 ש\u0003אמר\u0004 דברים אלו הלך לשיטת \u0003תנא דבי\u0004 \u0005[החכם מבית\u0006 מדרשו\u0005]\u0006 של \u0003מנשה. דתנא דבי\u0004 \u0005[ששנה\u0006 החכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003מנשה: כתבה על הנייר,\u0004 או \u0003על המטלית\u0004 — \u0003פסולה.\u0004 ואם כתבה \u0003על הקלף\u0004 או \u0003על הגויל\u0004 (עור מעובד שלם) או \u0003על\u0004 ה\u0003דוכסוסטוס\u0004 — \u0003כשרה.\u0004","ומתחילה מבררים: \u0003כתבה מאי\u0004 \u0005[מה],\u0006 במה נאמרו הלכות אלה? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שכתבה ל\u0003מזוזה\u0004 — \u0003מזוזה\u0004 על \u0003קלף מי כתבינן\u0004 \u0005[האם כותבים אנו]?\u0006 \u0003אלא לאו\u0004 \u0005[האם לא]\u0006 הכוונה היא ל\u0003תפילין,\u0004 ונמצא שיש חכמים הסבורים שתפילין נכתבים על דוכסוסטוס כדברי רב. ודוחים: \u0003וליטעמיך\u0004 \u0005[ולטעמך,\u0006 לשיטתך\u0005]\u0006 \u0003תפילין\u0004 על \u0003גויל מי כתבינן\u0004 \u0005[האם כותבים אנו]?!\u0006 \u0003אלא, כי תניא\u0004 \u0005[כאשר נשנתה\u0006 הברייתא\u0005]\u0006 \u0003ההיא\u0004 הריהי \u0003בספר תורה.\u0004 ואומרים: \u0003לימא מסייע ליה\u0004 \u0005[האם נאמר\u0006 שאפשר \u0005לסייע לו\u0006 לרב\u0005]\u0006 ממה ששנינו: \u0003כיוצא בו תפילין שבלו וספר תורה שבלה, אין עושין מהן מזוזה.\u0004 אף שאפשר לחתוך מתוכם את הפרשה הנכתבת במזוזה. וטעמו של דבר — \u0003לפי שאין מורידין מקדושה חמורה\u0004 של תפילין וספר תורה, \u0003לקדושה קלה\u0004 של מזוזה.","ומדייקים: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 ש\u0003אין מורידין, הא\u0004 \u0005[הרי]\u0006 אם היו \u0003מורידין\u0004 היו \u0003עושין\u0004 מתפילין מזוזה. ומעתה נברר: \u0003דכתיבא אמאי\u0004 \u0005[שכתובה,\u0006 פרשת התפילין, \u0005על מה]\u0006 \u0003לאו דכתיבא\u0004 \u0005[האם לא שנכתבה]\u0006 פרשת התפילין על \u0003דוכסוסטוס\u0004 וכדברי רב! ומשיבים: \u0003לא, דכתיבא\u0004 \u0005[שכתובה]\u0006 פרשת התפילין \u0003על הקלף.\u0004 ומקשים: אם כן כיצד אפשר לעשות מתפילין אלו מזוזה? \u0003מזוזה\u0004 על \u0003קלף מי כתבינן\u0004 \u0005[האם אנו כותבין]?\u0006 ומשיבים: \u0003אין\u0004 \u0005[כן],\u0006 \u0003והתניא\u0004 \u0005[ו\u0006אכן כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003כתבה\u0004 את המזוזה \u0003על הקלף\u0004 או \u0003על הנייר\u0004 או \u0003על המטלית\u0004 — \u0003פסולה. אמר ר' שמעון בן אלעזר: ר' מאיר היה כותבה על הקלף, מפני שמשתמרת.\u0004 הרי שאף מזוזה נכתבת על הקלף, ואין להוכיח מן הברייתא הקודמת דבר. ואולם עם שמיעת השיטה האחרונה אומרים: \u0003השתא דאתית להכי\u0004 \u0005[עכשיו שהגעת לכך]\u0006 ללמוד שהמזוזה נכתבת גם על דוכסוסטוס וגם על קלף, \u0003ל\u0004דברי \u0003רב נמי לא תימא\u0004 \u0005[לא תאמר,\u0006 תבין\u0005]\u0006 שרצה לומר ש\u0003דוכסוסטוס הרי הוא כקלף\u0004 לענין תפילין, \u0003אלא אימא\u0004 \u0005[אמור]:\u0006 \u0003קלף הרי הוא כדוכסוסטוס, מה דוכסוסטוס כותבין עליו מזוזה אף קלף כותבין עליו מזוזה.\u0004 וכשיטת ר' מאיר.","שנינו במשנה ששיעור ה\u0003דיו\u0004 להוצאת שבת הוא \u0003כדי לכתוב\u0004 שתי אותיות."],["ובתוספתא \u0003תנא\u0004 \u0005[שנינו]:\u0006 \u0003שתי אותיות\u0004 כשמוליך \u0003בדיו\u0004 יבש, \u0003שתי אותיות\u0004 כשהן \u0003בקולמוס,\u0004 ו\u0003שתי אותיות בקלמרין\u0004 (קסת). \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רבא:\u0004 הוציא \u0003אות אחת בדיו, אות אחת בקולמוס, אות אחת בקלמרין, מהו?\u0004 האם נאמר שמצטרפים כל אלה לשיעור אחד, או שמא כל אחד לעצמו? לשאלה זו לא נמצאה תשובה, ועל כן \u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה.","\u0003אמר רבא: הוציא\u0004 בשבת דיו כדי כתיבת \u0003שתי אותיות, וכתבן כשהוא מהלך,\u0004 ולא הניח את הדבר הכתוב במקום מסויים — \u0003חייב\u0004 בכל זאת על הוצאת הדיו, כי \u0003כתיבתן זו היא הנחתן,\u0004 ואין צורך להניח את הדיו על גבי קרקע. \u0003ואמר רבא: הוציא\u0004 דיו כדי כתיבת \u0003אות אחת, וכתבה, וחזר והוציא\u0004 דיו כדי כתיבת \u0003אות אחת, וכתבה\u0004 — \u0003פטור. מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? \u0003בעידנא דאפקא לבתרייתא\u0004 \u0005[בזמן שהוציא את\u0006 הטיפה \u0005האחרונה],\u0006 \u0003חסר ליה לשיעורא דקמייתא\u0004 \u0005[לו השיעור של הראשונה]\u0006 שהתייבשה קצת בינתים, ואין בה כדי כתיבת אות, ונמצא שלא הוציא כשיעור שתי אותיות.","\u0003ו\u0004בענין דומה \u0003אמר רבא: הוציא\u0004 בשבת \u0003חצי גרוגרת אחת, והניחה\u0004 ברשות אחרת, \u0003וחזר והוציא חצי גרוגרת אחת והניחה,\u0004 ה\u0003ראשונה נעשה כמי\u0004 (כאילו) \u0003שקלטה\u0004 (תפסה) \u0003כלב. או שנשרפה, ופטור,\u0004 שלא הוציא כשיעור גרוגרת שחייבים עליו. ותוהים: \u0003ואמאי\u0004 \u0005[ומדוע]?\u0006 \u0003הא מנחה\u0004 \u0005[הרי מונחת]\u0006 הגרוגרת כולה כאחת, ומדוע לא יתחייב על הוצאתה? ומסבירים: \u0003הכי קאמר\u0004 \u0005[כך אמר,\u0006 נתכוון לומר\u0005]:\u0006 \u0003ואם קדם והגביה\u0004 את ה\u0003ראשונה\u0004 מהמקום שהניחה \u0003קודם הנחת\u0004 ה\u0003שנייה,\u0004 ולא היו שני חצאי הגרוגרת מונחים יחד — \u0003נעשית\u0004 ה\u0003ראשונה כמי שנקלטה או שנשרפה, ופטור. ואמר רבא: הוציא חצי גרוגרת והניחה, וחזר והוציא חצי גרוגרת והעבירה דרך עליה,\u0004 שהעביר את החצי השני מעל לחצי הראשון המונח — \u0003חייב,\u0004 ואפילו אינם מונחים יחד. ומקשים: \u0003ואמאי\u0004 \u0005[ומדוע]?\u0006 \u0003הא\u0004 \u0005[הרי]\u0006 \u0003לא נח\u0004 החצי השני! ומשיבים: \u0003כגון שהעבירה תוך שלשה\u0004 טפחים, וכלל בידינו שדברים המצויים במרחק של פחות משלושה טפחים זה מזה נחשבים כצמודים.","ומקשים: אפילו כך אין זה מספיק, \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רבא\u0004 עצמו שדבר העובר \u0003תוך שלשה\u0004 טפחים \u0003ל\u0004שיטת \u0003רבנן צריך\u0004 שתהא בו \u0003הנחה על גבי משהו,\u0004 ואם לא נח כלל אינו נחשב כנוגע! ומשיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 \u0003כאן\u0004 שאמר רבא שדרושה הנחה ממש הרי זה \u0003בזורק,\u0004 ו\u0003כאן\u0004 שעצם הקירבה מספקת הרי זה \u0003במעביר\u0004 ביד, כיון שיכול להניח את החפץ בכל עת.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003הוציא חצי גרוגרת וחזר והוציא חצי גרוגרת,\u0004 אם היה זה \u0003בהעלם אחד\u0004 — \u0003חייב, בשתי העלמות\u0004 — \u0003פטור,\u0004 לפי שלא הוציא בכל פעם כשיעור המחייב. \u0003ר' יוסי אומר:\u0004 אם הוציא \u0003בהעלם אחד לרשות אחד\u0004 — \u0003חייב, לשתי רשויות\u0004 — \u0003פטור.\u0004 שאם הוציא לשני חלקים ברשות הרבים, המופרדים זה מזה — פטור, כיון שאין דרך היתר לקרב את שני החצאים זה לזה. \u0003אמר רבה:\u0004 בדברי ר' יוסי יש להדגיש: \u0003והוא\u0004 דווקא כ\u0003שיש חיוב חטאת ביניהם,\u0004 שבין חלק אחד ברשות הרבים ומשנהו יש איזור של רשות היחיד שמן התורה אסור לטלטל בו. \u0003אבל\u0004 היתה ביניהם \u0003כרמלית\u0004 — \u0003לא,\u0004 שהרי אין איסור מן התורה להעביר בה, ואין שתי רשויות הרבים נחשבות כמופרדות.","\u0003אביי אמר : אפילו\u0004 היתה \u0003כרמלית\u0004 מפרידה ביניהם, אין זו נחשבת כרשות אחת. \u0003אבל\u0004 אם היתה ביניהם \u0003פיסלא\u0004 \u0005[קורה גדולה]\u0006 — \u0003לא\u0004 תיחשב זו כהפרדה בין שתיהן\u0003. ורבא אמר: אפילו פיסלא\u0004 \u0005[קורה גדולה]\u0006 מפרידה לדעת ר' יוסי בין חלק לחלק שברשות הרבים ועושה אותו כשתים. ומעירים: \u0003ואזדא\u0004 \u0005[והולך]\u0006 \u0003רבא לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005],\u0006 ש\u0003אמר רבא: רשות שבת כרשות גיטין דמיא\u0004 \u0005[נחשבת].\u0006 וכשם שבדיני גיטין שני מקומות הנבדלים זה מזה בקורה אינם נחשבים כרשות אחת לגט, כך נבדלים הם לדיני שבת.","שנינו במשנה, ששיעור \u0003כחול\u0004 להוצאת שבת הוא \u0003כדי\u0004 שיוכלו \u0003לכחול\u0004 בו \u0003עין אחת.\u0004 ושואלים: \u0003עין אחת הא לא כחלי\u0004 \u0005[הרי אין כוחלין]\u0006 אלא שתיים! \u0003אמר רב הונא: שכן\u0004 נשים \u0003צנועות\u0004 המכסות את פניהן ברעלה \u0003כוחלות עין אחת\u0004 בלבד, שאותה הן מגלות. \u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך ממה ששנינו בברייתא, \u0003ר' שמעון בן אלעזר אומר: כחול, אם\u0004 משתמשים בו \u0003לרפואה\u0004 — שיעורו \u0003כדי לכחול עין אחת, אם לקשט\u0004 — \u0003בשתי עינים. תרגמא\u0004 \u0005[פירש אותה]\u0006 \u0003הילל בריה\u0004 \u0005[בנו]\u0006 של \u0003ר' שמואל בר נחמני: כי תניא ההוא\u0004 \u0005[כשנשנתה\u0006 ברייתא \u0005זו]\u0006 הרי היא \u0003בעירניות\u0004 (בנות כפר) שאינן נוהגות לכסות פניהן.","שנינו במשנה ששיעור הוצאת \u0003שעוה\u0004 הוא שיש בה \u0003כדי ליתן על פי נקב\u0004 קטן. \u0003תנא\u0004 \u0005[שנינו]\u0006 בתוספתא: \u0003כדי ליתן על פי נקב קטן של יין,\u0004 שדי בנקב קטן ביותר עבור יין, ולא בנקב כלי המכיל חומרים אחרים הסמיכים יותר ובהם יש צורך בנקב גדול יותר.","שנינו במשנה ששיעור ה\u0003דבק\u0004 להוצאת שבת הוא שיהא בו \u0003כדי ליתן בראש השפשף. תנא\u0004 \u0005[שנו]\u0006 חכמים: משמעו — \u0003כדי ליתן בראש שפשף שבראש קנה של ציידין,\u0004 שהם שמים עליו דבק כדי שילכד בו העוף.","עוד שנינו במשנה ששיעור ה\u0003זפת וגפרית\u0004 להוצאת שבת הוא כדי שיהא בו \u0003כדי לעשות נקב.\u0004 והכוונה היא שסותמים בזפת ובגפרית חור גדול שבכד, ואותה סתימה עשויה שיעשו בה נקב. \u0003תנא\u0004 \u0005[שנה]\u0006 החכם בתוספתא: המדובר כאן ב\u0003נקב קטן.\u0004","שנינו במשנה ששיעור \u0003חרסית\u0004 להוצאת שבת הוא \u0003כדי לעשות\u0004 בו \u0003פי כור,\u0004 ולדעת ר' יהודה כדי לעשות פטפוט (רגל) לכירה. ותמהים: \u0003למימרא דשיעורא\u0004 \u0005[האם נאמר כי השיעור]\u0006 של \u0003ר' יהודה נפיש\u0004 \u0005[גדול\u0006 יותר\u0005]?\u0006 \u0003הא קיימא לן דשיעורא דרבנן נפיש\u0004 \u0005[\u0006\u0005הלא מוחזק בידינו ששיעורם של חכמים גדול],\u0006 \u0003דתנן\u0004 [\u0005ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]\u0006 בדין גמי, ש\u0003ר' יהודה אומר:\u0004 שיעורו להוצאת שבת הוא שיהא בו \u0003כדי ליטול הימנו מדת מנעל לקטן.\u0004 והיא פחות מן השיעור שקבעו חכמים. ומתרצים: אף כאן אין הכוונה כדי לעשות את הרגל כולה, אלא כדי \u0003לסוד פיטפוט כירה קטנה\u0004 ושיעור הטיח קטן ביותר.","שנינו במשנה ששיעור \u0003סובין\u0004 להוצאת שבת הוא כדי שיהא בו \u0003כדי ליתן על פי כור של צורפי זהב.\u0004"],["\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 \u0003המוציא שיער\u0004 שיעורו \u0003כדי לגבל בו את הטיט,\u0004 שנוהגים לערב שיער בטיט כדי לחזקו. ו\u0003טיט\u0004 שיעורו כדי \u0003לעשות\u0004 בו \u0003פי כור של צורפי זהב.\u0004","שנינו במשנה ששיעור ה\u0003סיד\u0004 להוצאת שבת הוא שיהא בו \u0003כדי לסוד\u0004 קטנה שבבנות. \u0003תנא\u0004 \u0005[שנה]\u0006 החכם בתוספתא: \u0003כדי לסוד אצבע\u0004 של \u0003קטנה שבבנות,\u0004 שבעזרת הסיד היו מרככים ומעדנים את העור. \u0003אמר רב יהודה\u0004 שכך \u0003אמר רב,\u0004 מלפנים היה לסיד שימוש אחר: \u0003בנות ישראל שהגיעו לפירקן\u0004 בסימני התבגרות \u0003ולא הגיעו\u0004 עדיין \u0003לשנים\u0004 של בגרות ורוצות להשיר את השערות, וכן נשים הרוצות להשיר שערותיהן לנוי, \u0003אם היו בנות עניים\u0004 — \u0003טופלות\u0004 (מורחות) \u0003אותן\u0004 (את עצמן) \u0003בסיד. בנות עשירים\u0004 — \u0003טופלות אותן בסולת. בנות מלכים\u0004 — \u0003טופלות אותן בשמן המור,\u0004 וכפי \u0003שנאמר: \"\u0004כי כן ימלאו ימי מרוקיהן \u0003ששה חדשים בשמן המור\"\u0004 (אסתר ב, יג). ואגב שואלים: \u0003מאי\u0004 \u0005[מהו]\u0006 \u0003שמן המור? רב הונא בר חייא אמר: סטכת\u0004 (מין שמן מבושם). ו\u0003רב ירמיה בר אבא אמר: שמן זית\u0004 שממצים מזית \u0003ש\u0004עדיין לא \u0003הביאה שליש\u0004 בישולו, והשמן חריף ומסייע להשרת השיער. \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' יהודה אומר: אנפיקנון\u0004 הוא \u0003שמן זית שלא הביאה שליש. ולמה סכין אותו\u0004 — לפי \u0003שמשיר את השיער ומעדן\u0004 את \u0003הבשר.\u0004","ולענין הסיד מסופר: \u0003רב ביבי הויא ליה ברתא\u0004 \u0005[היתה לו בת],\u0006 \u0003טפלה\u0004 בסיד \u0003אבר אבר\u0004 ונתייפתה עד שכתוצאה מכך \u0003שקל בה\u0004 \u0005[נטל בשבילה]\u0006 \u0003ארבע מאות זוזי\u0004 \u0005[זוז]\u0006 כמתנות נוסף לנדונייתה. \u0003הוה ההוא גוי בשבבותיה\u0004 \u0005[היה גוי אחד בשכנותו]\u0006 של רב ביבי. \u0003הויא ליה ברתא\u0004 \u0005[היתה לו\u0006 לאותו גוי \u0005בת]\u0006 ורצה לעשות כמוהו, \u0003טפלה בחד זימנא\u0004 \u0005[בפעם אחת]\u0006 \u0003ומתה. אמר: קטל\u0004 \u0005[הרג]\u0006 \u0003רב ביבי לברתי\u0004 \u0005[את בתי].\u0006 \u0003אמר רב נחמן: רב ביבי דשתי שיכרא\u0004 \u0005[ש\u0006נוהג \u0005לשתות שכר]\u0006 — \u0003בעיין בנתיה טפלא\u0004 \u0005[צריכות בנותיו טפילא\u0006 בסיד\u0005],\u0006 שהשיכר מגדל את השיער, \u0003אנן דלא שתינן שיכרא\u0004 \u0005[אנחנו שאיננו שותים שיכר]\u0006 — \u0003לא בעיין בנתן טפלא\u0004 \u0005[אין בנותינו צריכות מריחה\u0006 בסיד\u0005].\u0006","שנינו במשנה ש\u0003ר' יהודה אומר\u0004 ששיעור הטפילה הוא \u0003כדי לסוד כלכול,\u0004 ור' נחמיה אומר לסוד אנדיפי. ושואלים: \u0003מאי\u0004 \u0005[מהו]\u0006 \u0003כלכול ומאי\u0004 \u0005[ומהו]\u0006 \u0003אנדיפי? אמר רב\u0004 הסבר הדברים הוא: \u0003צידעא ובת צידעא\u0004 \u0005[הרקה, והמקום שתחת הרקה].\u0006 ומקשים: \u0003למימרא דשיעורא\u0004 \u0005[שהשיעור]\u0006 של \u0003ר' יהודה נפיש\u0004 \u0005[\u0006הוא ה\u0005גדול]?\u0006 \u0003הא קיימא לן דשיעורא דרבנן נפיש\u0004 \u0005[\u0006ו\u0005הרי מוחזק בידינו ששיעורם של חכמים הוא הגדול]!\u0006 ומשיבים: שיעורו של ר' יהודה הוא \u0003זוטא מדרבנן\u0004 \u0005[קטן מ\u0006זה \u0005של חכמים],\u0006 \u0003ונפיש\u0004 \u0005[וגדול]\u0006 \u0003מ\u0004שיעורו של \u0003ר' נחמיה. מיתיבי\u0004 \u0005[מקשים]\u0006 על הסבר זה ממה ששנינו בברייתא, ש\u0003אמר רבי: נראין דברי ר' יהודה\u0004 ושיעורו \u0003ב\u0004סיד \u0003חבוט\u0004 (שהומס במים), \u0003ודברי ר' נחמיה בביצת הסיד\u0004 (גושי סיד). \u0003ואי סלקא דעתך צידעא ובת צידעא, אידי ואידי\u0004 \u0005[ואם עולה על דעתך\u0006 שאלה הם \u0005הרקה ומה שתחת לרקה, אלה ואלה]\u0006 בסיד \u0003חבוט הוא\u0004 הוא שמשתמשים! \u0003אלא אמר ר' יצחק, אמרי דבי\u0004 \u0005[אומרים\u0006 בני \u0005בית\u0006 המדרש\u0005]\u0006 של \u0003ר' אמי:\u0004 מה שאמר ר' נחמיה \"אנדיפי\" פירושו — \u0003אאנדיפא,\u0004 שמורחים בסיד את תוכו של כלי חרס המכיל יין.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב כהנא: וכי אדם עושה מעותיו אנפרות\u0004 \u0005[הפסד,\u0006 בזבוז\u0005]?!\u0006 שהרי בכך הוא מקלקל את גם את הסיד וגם את היין! \u0003אלא אמר רב כהנא:\u0004 סיד זה אין שמים בכלי אלא מסמנים בו מבחוץ \u0003שנתות,\u0004 שמסמנים על ידן שיעורים שונים בכלי. ו\u0003כדתנן\u0004 \u0005[כפי ששנינו\u0006 במשנה\u0005]:\u0006 בבית המקדש \u0003שנתות היו ב\u0004מידה של \u0003הין\u0004 למדידת היין, שבה היו מסמנים \u0003עד כאן ל\u0004קרבן \u0003פר\u0004 (חצי ההין), \u0003עד כאן ל\u0004קרבן \u0003איל\u0004 (שליש הין). \u0003עד כאן ל\u0004קרבן \u0003כבש\u0004 (רבע הין). \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 הסבר אחר: \u0003מאי\u0004 \u0005[מהו]\u0006 \u0003\"אנדיפא\"\u0004 — \u0003אפותא\u0004 \u0005[המצח],\u0006 ועליו היו טופלים סיד לא להשרת השערות, אלא רק להעדין ולרכך את העור, ולשם זה אפשר להשתמש בסיד סמיך. וראיה לשימוש לשון זה \u0003כי הא דההוא בר גלילא דאיקלע\u0004 \u0005[כמו בן גליל אחד שהזדמן]\u0006 \u0003לבבל,\u0004 ו\u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003קום\u0004 \u0005[עמוד]\u0006 ו\u0003דרוש לנו ב\u0004תורת הסוד הנקראת \u0003\"מעשה מרכבה\". אמר להו\u0004 \u0005[להם]:\u0006 \u0003אדרוש לכו\u0004 \u0005[לכם]\u0006 \u0003כ\u0004פי ש\u0003דרש ר' נחמיה לחבריה\u0004 \u0005[לחבירו].\u0006 \u0003ונפקא ערעיתא מן כותלא ומחתיה באנדיפי ומית\u0004 \u0005[ויצאה צירעה מן הכותל ועקצה אותו במצחו ומת].\u0006 ומכאן שלשון \"אנדיפי\" משמעו — מצח. \u0003ו\u0004לגוף הדבר \u0003אמרו ליה\u0004 \u0005[לו]\u0006 על אותו גלילי במשחק מילים: \u0003מן דיליה דא ליה\u0004 \u0005[משלו זו לו],\u0006 שנענש בשל גאוותו שרצה לדרוש ברבים במעשה מרכבה.","\u0003אדמה\u0004 שיעורה לענין איסור הוצאה בשבת \u0003כחותם המרצופין\u0004 (השקים הגדולים) שמשתמשים באדמה כדי לחתום את פי השק שיהיה ניכר אם נפתח, אלו \u0003דברי ר' עקיבא. וחכמים אומרים:\u0004 אין צורך בשיעור מרובה זה ודי בכדי \u0003חותם האיגרות. זבל וחול הדק\u0004 שיעורם \u0003כדי לזבל קלח של כרוב,\u0004 אלו \u0003דברי ר' עקיבא. וחכמים אומרים:\u0004 בפחות מזה, \u0003כדי לזבל\u0004 צמח של \u0003כרישא\u0004 (כרתי, חציר). \u0003חול הגס,\u0004 שיעורו — \u0003כדי ליתן על מלא כף סיד. קנה\u0004 שיעורו — \u0003כדי לעשות\u0004 ממנו \u0003קולמוס. ואם היה\u0004 הקנה \u0003עבה\u0004 ואינו ראוי לכתוב בו, \u0003או\u0004 שהיה \u0003מרוסס\u0004 (שבור לרסיסים), שיעורו \u0003כדי לבשל בו ביצה\u0004 ה\u0003קלה\u0004 לבישול שבביצים, כשהיא כבר \u0003טרופה\u0004 (מעורבת ובחושה) \u0003ונתונה באילפס.\u0004","שנינו במשנה ששיעור חול הגס הוא כדי ליתן \u0003על מלא כף סיד.\u0004 ו\u0003תנא\u0004 \u0005[שנה]\u0006 החכם בתוספתא שהכוונה היא \u0003כדי ליתן על פי כף של סיידין\u0004 ולא כף אכילה. ושואלים: \u0003מאן\u0004 \u0005[מיהו]\u0006 ה\u0003תנא\u0004 הסבור ש\u0003חול מעלי ליה\u0004 \u0005[מועיל לו]\u0006 \u0003לסיד,\u0004 ולכן נותנים אותו בסיד? \u0003אמר רב חסדא:\u0004 שיטת \u0003ר' יהודה היא, דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 מפני האבילות על חורבן בית המקדש \u0003לא יסוד אדם את ביתו בסיד\u0004 שכולו לבן, \u0003אלא אם כן עירב בו תבן או חול,\u0004 שכגון זה אין מראהו נאה כל כך. \u0003ר' יהודה אומר: תבן מותר, חול אסור, מפני שהוא,\u0004 החול, בהיותו מעורב בסיד יוצר \u0003טרכסיד\u0004 (מעין מלט לבן). והרי שר' יהודה הוא הסבור שנוהגים לשים חול בתוך הסיד. \u0003רבא אמר: אפילו תימא\u0004 \u0005[יכול אתה לומר]\u0006 שמשנתנו כשיטת חכמים החולקים על ר' יהודה, ואולם יש לומר כי \u0003קילקולו זהו תיקונו.\u0004 שאמנם סבורים חכמים שהחול מקלקל, אך כיון שלאחר חורבן מותר להשתמש רק בסיד מקולקל קצת, יש בעירוב החול משום תיקון.","שנינו במשנה ששיעור \u0003קנה\u0004 להוצאת שבת הוא \u0003כדי\u0004 שאפשר \u0003לעשות\u0004 ממנו \u0003קולמוס,\u0004 ולא נתפרש גודלו. \u0003תנא\u0004 \u0005[שנה]\u0006 החכם בתוספתא: הוא \u0003קולמוס המגיע לקשרי\u0004 (פרקי) \u0003אצבעותיו. בעי\u0004 \u0005[שאל]\u0006 \u0003רב אשי:\u0004 האם מדובר כאן ב\u0003קשר\u0004 (פרק) \u0003העליון\u0004 של האצבעות \u0003או\u0004 ה\u0003קשר התחתון?\u0004 לשאלה זו לא נמצא פתרון ועל כן \u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה.","שנינו ש\u0003אם היה\u0004 הקנה \u0003עבה,\u0004 שאינו ראוי לכתוב בו דנים אותו כעץ הסקה, אם די בו כדי לבשל ביצה טרופה. \u0003תנא\u0004 \u0005[שנה]\u0006 החכם בתוספתא: טרופה משמעו — \u0003טרופה בשמן ונתונה באילפס. אמר ליה\u0004 \u0005[\u0006לו] \u0003מר בריה\u0004 \u0005[בנו]\u0006 של \u0003רב הונא לבריה\u0004 \u0005[לבנו]:\u0006 \u0003מי שמיע לך\u0004 \u0005[האם שמעת]?\u0006 \u0003ביצה קלה\u0004 הכתובה במשנה זו \u0003מאי היא\u0004 \u0005[מהי]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003ביעתא דצילצלא\u0004 \u0005[ביצה של תור]\u0006 אמר לו: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 אומר אתה כך? \u0003משום דזוטרא\u0004 \u0005[ש\u0006היא \u0005קטנה]?\u0006 אם כן \u0003אימא\u0004 \u0005[אמור]:\u0006 ביצה \u0003דציפרתא\u0004 \u0005[ציפור\u0006 דרור\u0005]!\u0006 \u0003אישתיק\u0004 \u0005[שתק]\u0006 ולא ידע להסביר. ואחר כך שאל: \u0003מידי שמיע\u0004 \u0005[וכי נשמע]\u0006 \u0003לך,\u0004 ידוע לך, \u0003בהא\u0004 \u0005[ב\u0006ענין \u0005זה]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר רב ששת:\u0004 מדובר כאן ב\u0003ביצת תרנגולת. ומאי קרו\u0004 \u0005[ומה\u0006 הסיבה ש\u0005קוראים]\u0006 \u0003לה \"ביצה קלה\"\u0004 — כי \u0003שיערו חכמים\u0004 ש\u0003אין לך ביצה קלה לבשל יותר מביצת תרנגולת.\u0004 והקשה לו: \u0003ומאי שנא\u0004 \u0005[ומה שונה]\u0006 ש\u0003כל שיעורי שבת\u0004 האמורים במאכלי אדם הם \u0003כגרוגרת והכא\u0004 \u0005[וכאן]\u0006 \u0003כביצה? אמר ליה\u0004 \u0005[לו],\u0006 כך \u0003אמר רב נחמן: כגרוגרת\u0004 בלבד \u0003מביצה קלה,\u0004 ואין משערים בכל הביצה."],["\u0003עצם\u0004 שיעורו להוצאה \u0003כדי לעשות\u0004 ממנו \u0003תרווד\u0004 (כף). \u0003ר' יהודה אומר: כדי לעשות ממנו חף\u0004 (מפתח). \u0003זכוכית\u0004 — \u0003כדי לגרור\u0004 (לגרד, להחליק) \u0003בו\u0004 את \u0003ראש הכרכר\u0004 (מקל מחודד שבידי האורגים). \u0003צרור או אבן\u0004 — \u0003כדי לזרוק בעוף\u0004 להבריחו. \u0003ר' אלעזר בן יעקב אומר: כדי לזרוק בבהמה,\u0004 שדרושה לכך אבן גדולה יותר.","שואלים: \u0003למימרא דשיעורא\u0004 \u0005[האם נאמר שהשיעור]\u0006 של \u0003ר' יהודה\u0004 בענין עצם \u0003נפיש\u0004 \u0005[גדול\u0006 יותר\u0005]?\u0006 שמפתחות שבאותם הימים גדולים היו, ו\u0003הא קיימא לן דשיעורא דרבנן נפיש\u0004 \u0005[והרי מוחזק בידינו שהשיעור של חכמים גדול\u0006 יותר\u0005]!\u0006 \u0003אמר עולא:\u0004 אין המדובר כאן בכל המפתח, אלא \u0003חפי פותחת\u0004 (השיניים שבמפתח). וכיון שהוזכרו אלה מביאים את מה ש\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003חפי פותחת\u0004 כשהם לעצמם שאינם ראויים לכל שימוש הריהם \u0003טהורין,\u0004 אינם מקבלים טומאה. ואולם אם \u0003קבען בפותחת\u0004 — טמאים מפני שהם חלק מכלי. \u0003ו\u0004חפין \u0003של גל\u0004 (שיניים שבמנעול דלת) \u0003אף על פי שחיברן בדלת וקבען במסמרים\u0004 — \u0003טהורין, שכל המחובר לקרקע הרי הוא כקרקע\u0004 עצמה, וקרקע אינה מקבלת טומאה.","שנינו במשנה ששיעור ה\u0003זכוכית\u0004 הוא \u0003כדי לגרור בו\u0004 את ראש הכרכר. \u0003תנא\u0004 \u0005[שנה]\u0006 החכם בתוספתא דברים אלו בשינוי: שיעור ה\u0003סכוכית\u0004 כדי להתחייב בהוצאתה בשבת הוא, כשיש בה \u0003כדי לפצוע\u0004 (לחתוך) \u0003בה שני נימין\u0004 (חוטים) \u0003כאחת,\u0004 שמשתמשים בשבר זכוכית כבסכין.","עוד שנינו במשנה כי שיעור \u0003צרור או אבן הוא כדי לזרוק בעוף.\u0004 ו\u0003ר' אליעזר\u0004 בן יעקב אומר: כדי לזרוק בבהמה. \u0003אמר ר' יעקב\u0004 שכך \u0003אמר ר' יוחנן: והוא\u0004 דווקא אם אבן זו גדולה עד \u0003שמרגשת בה\u0004 הבהמה. \u0003וכמה שיעורו? תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' אלעזר בן יעקב אומר: משקל עשרה זוז.\u0004","מסופר: \u0003זונין על לבי מדרשא\u0004 \u0005[נכנס לבית המדרש]\u0006 ו\u0003אמר להו\u0004 \u0005[להם]\u0006 לחכמים: \u0003רבותי, אבנים של בית הכסא\u0004 שהיו משתמשים בהם אז לקינוח \u0003שיעורן\u0004 לענין הוצאה בשבת \u0003בכמה?\u0004 כמה מהן מותר לטלטל לצורך זה בשבת? \u0003אמרו לו:\u0004 לוקחים שלוש אבנים בלבד, אחת \u0003כזית\u0004 אחת \u0003כאגוז\u0004 ואחת \u0003כביצה. אמר להו\u0004 \u0005[להם]:\u0006 \u0003וכי טורטני\u0004 \u0005[מאזניים]\u0006 \u0003יכניס\u0004 וישקול כל אבן שהוא לוקח? \u0003נמנו וגמרו\u0004 שאין בודקים באבנים אלא לוקח \u0003מלא היד. תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]:\u0006 \u0003ר' יוסי אומר:\u0004 שיעור אבני בית הכסא: \u0003כזית כאגוז וכביצה. ר' שמעון בר' יוסי אומר משום\u0004 (בשם) \u0003אביו\u0004 ר' יוסי: אין בודקים באבנים אלא נוטלים מהם \u0003מלא היד.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא \u0003(בשבת): שלוש אבנים מקורזלות\u0004 (מחודדות) \u0003מותר להכניס לבית הכסא. וכמה שיעורן? ר' מאיר אומר: כאגוז. ר' יהודה אומר: כביצה. אמר רפרם בר פפא\u0004 שכך \u0003אמר רב חסדא: כמחלוקת כאן כך מחלוקת\u0004 בין חכמים אלה \u0003ב\u0004שיעור גודלו המינימלי של \u0003אתרוג.\u0004 ותוהים: מדוע תולה הוא לסימן את המחלוקת באתרוג במחלוקת זו? והרי \u0003התם מתניתין\u0004 \u0005[שם\u0006 באתרוג \u0005משנה\u0006 היא\u0005]\u0006 והיא ידועה לכל, וכאן היא רק \u0003ברייתא\u0004 שאינה ידועה וצריך לתת בה סימן. \u0003אלא\u0004 יש להפוך את הגירסה ולומר: \u0003כמחלוקת באתרוג כך מחלוקת כאן.\u0004","\u0003אמר רב יהודה: אבל לא\u0004 לוקחים לצורך בית הכסא \u0003את הפאייס.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 הפירוש\u0005]\u0006 \u0003\"פאייס\"? אמר ר' זירא:\u0004 אלה הם \u0003כרשיני בבלייתא\u0004 \u0005[גושי רגבים שבבבל]\u0006 שהם רכים ונפרכים. \u0003אמר רבא: אסור למשמש\u0004 בפי הטבעת \u0003בצרור בשבת\u0004 לסייע בעשיית צרכיו \u0003כדרך שממשמש בחול. מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003מר זוטרא:\u0004 והאם לדעת רבא \u0003ליסתכן\u0004 \u0005[שיסתכן]\u0006 במניעת צרכיו? ומסבירים: הכוונה היא שיעשה זאת \u0003כלאחר יד,\u0004 ולא כדרך שעושים זאת כרגיל. בשיעור האבנים \u0003אמר ר' ינאי: אם יש מקום קבוע\u0004 עבורו \u0003לבית הכסא\u0004 — יכול להכניס אבנים \u0003מלא היד,\u0004 שאם אינו נצרך להם עתה ישתמש בהם בשעה אחרת. \u0003אם לאו\u0004 \u0005[לא]\u0006 — יכניס \u0003כהכרע\u0004 (כגודל רגל) \u0003מדוכה קטנה של בשמים. אמר רב ששת: אם יש עליה\u0004 (על האבן) \u0003עד,\u0004 כלומר, סימן שהשתמשו בה כבר לצורך בית הכסא — \u0003מותר\u0004 לטלטלה לצורך זה בשבת, ואין מקפידים בגודל.","\u0003מיתיבי\u0004 \u0005[מקשים על כך]:\u0006 וכי הקינוח באבן כזו מותר? והרי אמרו חכמים: \u0003עשרה דברים מביאין את האדם לידי תחתוניות\u0004 (טחורים), \u0003ואלו הן: האוכל עלי קנים, ועלי גפנים, ולולבי\u0004 (ענפים דקים, קנוקנות) \u0003גפנים, ומוריגי בהמה\u0004 (בשר מחוספס שבבהמה) \u0003בלא מלח, ו\u0004האוכל \u0003שדרו של דג, ו\u0004כן האוכל \u0003דג מליח שלא בישל\u0004 אותו \u0003כל צורכו, והשותה שמרי יין, והמקנח בסיד ובחרסית\u0004 או \u0003בצרור שקינח בו חברו. ויש אומרים: אף התולה עצמו\u0004 (מתאמץ מדי) \u0003בבית הכסא.\u0004 למדנו מכאן שסכנה לבריאות להשתמש בצרור שקינח בו חבירו! ומתרצים: \u0003לא קשיא\u0004 \u0005[אין זה קשה],\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שאסרו הרי זה כשעדיין הרושם הוא \u0003לח,\u0004 ואילו \u0003הא\u0004 \u0005[זה]\u0006 שהתירו — \u0003הרי זה ביבש. ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003כאן\u0004 שאסרו — הרי זה \u0003מצד אחד,\u0004 שחושב להשתמש באותו צד עצמו. \u0003וכאן\u0004 שהתירו — משני \u0003צדדים,\u0004 שחושב להשתמש בצד האחר של אותו צרור. \u0003ואיבעית אימא: הא\u0004 \u0005[זה]\u0006 שהתירו הרי זה בצרור \u0003דידיה\u0004 \u0005[שלו],\u0006 שקינח בו הוא עצמו, \u0003הא\u0004 \u0005[זה]\u0006 שאסרו הרי זה בצרור \u0003דחבריה\u0004 \u0005[של חבירו],\u0006 שהשתמש בו חבירו ורק בו יש חשש סכנה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי לרב יוסף:\u0004 אם \u0003ירדו עליה\u0004 על אבן זאת \u0003גשמים ונטשטשו\u0004 הסימנים שעליה \u0003מהו\u0004 הדין בכגון זה, האם מותר להוציאה בשבת כדין אבן העשוייה לקינוח, או מאחר שנטשטשו הסימנים יתכן וראויה היא לדבר אחר, ואסור אם כן להוציאה? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אם היה רישומן ניכר\u0004 — \u0003מותר,\u0004 שניכר בה שהיא מיועדת אך לקינוח.","\u0003בעא מיניה\u0004 \u0005[שאל ממנו]\u0006 \u0003רבה בר רב שילא מרב\u0004"],["\u0003חסדא: מהו\u0004 הדין, האם מותר \u0003להעלותם\u0004 לאבנים אלו \u0003אחריו לגג\u0004 אם שם בית הכסא שלו, ושמא יש לאסור משום טירחה יתירה? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 מותר, שכן \u0003גדול כבוד הבריות שדוחה\u0004 אף \u0003את\u0004 מצוות \u0003\"לא תעשה\" שבתורה,\u0004 ומשום כבוד הבריות התירו לו לטלטל את האבנים. ומסופר: \u0003יתיב\u0004 \u0005[ישב]\u0006 \u0003מרימר וקאמר לה להא שמעתא\u0004 \u0005[ואמר אותה, את ההלכה הזאת]\u0006 \u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רבינא למרימר\u0004 ממה ששנינו בברייתא, ש\u0003ר' אליעזר אומר: נוטל אדם קיסם, מ\u0004מה \u0003ש\u0004מונח \u0003לפניו\u0004 על הקרקע \u0003לחצות\u0004 (לחצוץ) ולנקות \u0003בו שיניו. וחכמים אומרים: לא יטול\u0004 מן הקרקע שהוא מוקצה, \u0003אלא מן האבוס של בהמה,\u0004 שהוא עומד ומוכן לשימוש הבהמה בשבת. הרי שאת חציצת שיניו, אף שיש בה משום כבוד הבריות, לא התירו בשל איסור מוקצה! ודוחים: \u0003הכי השתא\u0004 \u0005[כיצד אתה משווה]?!\u0006 \u0003התם\u0004 \u0005[שם]\u0006 — \u0003אדם קובע מקום לסעודה\u0004 ויודע היכן יסעד, והיה עליו להכין את הקיסמים מבעוד יום. \u0003הכא\u0004 \u0005[כאן]\u0006 — וכי \u0003אדם קובע מקום לבית הכסא?\u0004 אלא נפנה לצרכיו בכל מקום שמוצא.","\u0003אמר רב הונא: אסור לפנות\u0004 (להיפנות) לצרכיו \u0003בשדה ניר\u0004 (חרוש) \u0003בשבת,\u0004 ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003משום דוושא\u0004 \u0005[דריסה],\u0006 שהנפנה בשדה דורך על התלמים ומקלקל אותם — אם כן \u0003אפילו בחול נמי\u0004 \u0005[גם כן]\u0006 יהא אסור! \u0003ואלא\u0004 תאמר שהוא \u0003משום\u0004 שיש לחשוש שיקנח ברגב אדמה שיש עליו \u0003עשבים, והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ריש לקיש: צרור שעלו בו עשבים\u0004 — \u0003מותר לקנח בה\u0004 בשבת, אף שבתוך כך נתלשים ממנו העשבים שגדלו בו. \u0003ו\u0004אף ש\u0003התולש ממנה בשבת\u0004 עשבים בכוונה — \u0003חייב חטאת,\u0004 כיון שאינו מתכוון לתלישה — מותר. \u0003אלא\u0004 החשש הוא \u0003דילמא נקיט מעילאי ושדא לתתאי, ומיחייב\u0004 \u0005[שמא יקח\u0006 צרור \u0005מ\u0006מקום \u0005גבוה ויזרקנו ל\u0006מקום \u0005נמוך, ויתחייב]\u0006 \u0003משום\u0004 דברי \u0003רבה.\u0004 ש\u0003אמר רבה:\u0004 מי ש\u0003היתה לו גומא וטממה\u0004 \u0005[וסתמה]\u0006 אם היה זה \u0003בבית\u0004 — \u0003חייב משום\u0004 מלאכת \u0003בונה,\u0004 ואם היה זה \u0003בשדה\u0004 — \u0003חייב משום\u0004 מלאכת \u0003חורש.\u0004","\u0003גופא\u0004 \u0005[לגוף]\u0006 הדברים, שנינו ש\u0003אמר ריש לקיש: צרור שעלו בו עשבים\u0004 — \u0003מותר לקנח בה\u0004 בשבת. \u0003והתולש ממנה בשבת\u0004 בכוונה תחילה — \u0003חייב חטאת. אמר רב פפי: שמע מינה\u0004 \u0005[למד ממנה]\u0006 \u0003מ\u0004דברי \u0003ריש לקיש\u0004 כי \u0003האי פרפיסא\u0004 \u0005[עציץ נקוב זה]\u0006 — \u0003שרי לטלטולי\u0004 \u0005[מותר לטלטלו]\u0006 בשבת. \u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב כהנא: אם אמרו\u0004 שמותר לטלטל צרור שעליו עשבים \u0003לצורך,\u0004 וכי \u0003יאמרו\u0004 שמותר לטלטל אף \u0003שלא לצורך?! אמר אביי: פרפיסא\u0004 \u0005[עציץ נקוב],\u0006 \u0003הואיל ואתא לידן\u0004 \u0005[ובא לידינו]\u0006 לדון בו \u0003לימא ביה מילתא\u0004 \u0005[אומר בו דבר]:\u0006 אם \u0003היה מונח על גבי קרקע, והניחו\u0004 בשבת \u0003על גבי יתדות\u0004 — \u0003מיחייב\u0004 \u0005[חייב]\u0006 \u0003משום\u0004 מלאכת \u0003תולש,\u0004 שהרי יכול השורש של הצמח בעציץ לחדור דרך הנקב אל הקרקע, וכשהוא מגביהו הרי זה כתולשו מן הקרקע. וכן אם \u0003היה מונח על גבי יתידות והניחו על גבי קרקע\u0004 — \u0003חייב משום\u0004 מלאכת \u0003נוטע.\u0004","\u0003אמר ר' יוחנן: אסור לקנח בחרס בשבת.\u0004 ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003משום סכנה\u0004 שמא ייפצע בקצותיו החדים של החרס — אם כן \u0003אפילו ב\u0004ימות ה\u0003חול נמי\u0004 \u0005[גם כן]\u0006 ייאסר. \u0003ואלא משום\u0004 שמביא הדבר עליו \u0003כשפים\u0004 — אם כן לטעם זה \u0003אפילו בחול נמי\u0004 \u0005[גם כן]\u0006 \u0003לא\u0004 יותר הדבר! \u0003ואלא משום\u0004 שיש לחשוש בשבת ל\u0003השרת נימין\u0004 (שערות) הנחתכות אגב קינוח בחרס — הרי \u0003דבר שאין מתכוין הוא,\u0004 ודבר שאין מתכוין — מותר. \u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003רב נתן בר אושעיא\u0004 לשואלים: \u0003גברא רבה\u0004 \u0005[אדם גדול]\u0006 \u0003אמר מילתא\u0004 \u0005[דבר],\u0006 הבה \u0003נימא בה טעמא\u0004 \u0005[נאמר בו טעם].\u0006 וכך נסביר את דברי ר' יוחנן: \u0003לא מיבעיא\u0004 \u0005[נצרכה]\u0006 להודיענו \u0003בחול\u0004 שהוא \u0003אסור\u0004 מן הטעמים שלעיל, \u0003אבל בשבת\u0004 היינו אומרים \u0003הואיל ואיכא\u0004 \u0005[ויש]\u0006 \u0003תורת כלי עליו,\u0004 ואינו מוקצה, ואם כן \u0003שפיר דמי\u0004 \u0005[יפה\u0006 הדבר, מותר\u0005],\u0006 ועדיף להשתמש בו מאשר בצרור שיש בו דין מוקצה, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 הלכה זו לאסור.","\u0003רבא מתני לה\u0004 \u0005[שונה אותה,\u0006 מסביר\u0005]\u0006 את דברי ר' יוחנן \u0003משום השרת נימין, וקשיא ליה\u0004 \u0005[והוקשה לו]\u0006 ומקשה מדברי \u0003ר' יוחנן\u0004 על דברי \u0003ר' יוחנן: מי\u0004 \u0005[האם]\u0006 \u0003אמר ר' יוחנן\u0004 כי \u0003אסור לקנח בחרס בשבת? אלמא\u0004 \u0005[מכאן]\u0006 \u0003דבר שאין מתכוין\u0004 — \u0003אסור. והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' יוחנן\u0004 כלל: \u0003הלכה כסתם משנה. ותנן\u0004 \u0005[ושנויה\u0006 ברייתא\u0005]:\u0006 \u0003נזיר\u0004 שאסור לו לספר את שערותיו \u0003חופף\u0004 את השיער \u0003ומפספס\u0004 (מפריד את השערות בידים), \u0003אבל לא סורק,\u0004 שבודאי ישיר שערות בסריקה. ומכאן שאין חוששים להשרת שיער בתוך החפיפה, כיון שאינו מתכוון לכך! \u0003אלא מחוורתא\u0004 \u0005[מחוור,\u0006 ברור\u0005]\u0006 \u0003כ\u0004פי שהסביר זאת \u0003רב נתן בר אושעיא.\u0004","ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 הם\u0005]\u0006 \u0003כשפים\u0004 שאמרנו שקינוח בחרס גורם להם? ומסבירים: \u0003כי הא\u0004 \u0005[כמו\u0006 מעשה \u0005זה]\u0006 ש\u0003רב חסדא ורבה בר רב הונא הוו קא אזלי בארבא\u0004 \u0005[היו הולכים\u0006 לדרכם \u0005בסירה],\u0006 \u0003אמרה להו ההיא מטרוניתא\u0004 \u0005[להם גבירה אחת]:\u0006 \u0003אותבן בהדייכו\u0004 \u0005[הושיבו אותי לידכם]!\u0006 \u0003ולא אותבוה\u0004 \u0005[הושיבוה].\u0006 \u0003אמרה איהי מילתא\u0004 \u0005[היא דבר\u0006 של כשפים\u0005]\u0006 — \u0003אסרתה לארבא\u0004 \u0005[\u0006ו\u0005אסרה,\u0006 קשרה \u0005את הספינה]\u0006 שלא תזוז. \u0003אמרו אינהו מילתא\u0004 \u0005[הם דבר,\u0006 שם טהרה\u0005]\u0006 — \u0003שריוהא\u0004 \u0005[\u0006ו\u0005התירוה].\u0006 \u0003אמרה להו\u0004 \u0005[להם]:\u0006 \u0003מאי איעביד לכו\u0004 \u0005[מה אעשה לכם]\u0006 שאוכל להזיקכם בכשפים?"],["\u0003דלא מקנח לכו בחספא\u0004 \u0005[\u0006והלא \u0005אין אתם מקנחים בחרס]\u0006 \u0003ולא קטיל לכו\u0004 \u0005[ואין אתם הורגים]\u0006 \u0003כינא\u0004 (כינה) \u0003אמנייכו\u0004 \u0005[על בגדיכם],\u0006 \u0003ולא שליף לכו ירקא ואכיל לכו מכישא דאסיר גינאה\u0004 \u0005[ואין אתם מוציאים ירק ואוכלים\u0006 לפני שאתם מתירים \u0005את האגודה שקשר הגנן],\u0006 ומכאן שכל אלה מביאים סכנת כשפים.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב הונא לרבה בריה\u0004 \u0005[בנו]:\u0006 \u0003מאי טעמא לא שכיחת קמיה\u0004 \u0005[מה טעם אינך מצוי]\u0006 לפני \u0003רב חסדא דמחדדן שמעתיה\u0004 \u0005[שמחודדות שמועותיו,\u0006 הלכותיו\u0005]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבה: \u0003מאי איזיל לגביה\u0004 \u0005[מה אלך אליו]?\u0006 \u0003דכי אזילנא לגביה מותיב לי במילי דעלמא\u0004 \u0005[שכאשר אני הולך אליו מושיב\u0006 הוא \u0005אותי\u0006 ומעסיקני \u0005בענייני עולם\u0006 שאינם דברי תורה\u0005].\u0006 ולמשל \u0003אמר לי: מאן דעייל\u0004 \u0005[מי שנכנס]\u0006 \u0003לבית הכסא לא ליתיב בהדיא\u0004 \u0005[יישב מיד],\u0006 \u0003ולא ליטרח טפי\u0004 \u0005[יטרח,\u0006 יתאמץ \u0005מידי],\u0006 משום \u0003דהאי כרכשתא אתלת שיני יתיב\u0004 \u0005[שכרכשתא זו,\u0006 סופו של המעי התחתון \u0005יושב,\u0006 תלוי, \u0005על שלוש שיניים],\u0006 שהם השרירים האוחזים אותו, ויש לחשוש \u0003דילמא\u0004 \u0005[שמא]\u0006 מתוך המאמץ \u0003משתמטא\u0004 \u0005[יישמטו]\u0006 \u0003שיני\u0004 ה\u0003כרכשתא ואתי\u0004 \u0005[ויבוא]\u0006 בתוך כך \u0003לידי סכנה. אמר ליה\u0004 \u0005[לו]\u0006 רב הונא לרבה בנו: \u0003הוא עסיק\u0004 \u0005[מתעסק]\u0006 \u0003בחיי דברייתא\u0004 \u0005[הבריות]\u0006 \u0003ואת\u0004 \u0005[ואתה]\u0006 \u0003אמרת\u0004 שעוסק הוא \u0003במילי דעלמא\u0004 \u0005[בסתם דברים]?!\u0006 עכשיו מששמעתי במה דברים אמורים אומר אני כי \u0003כל שכן זיל לגביה\u0004 \u0005[לך אצלו].\u0006","ועוד בהלכות אלה; מי שנפנה לצרכיו וצריך לקנח ו\u0003היו לפניו צרור\u0004 אבן \u0003וחרס, רב הונא אמר: מקנח בצרור ואין מקנח בחרס\u0004 משום שעלול להפצע בו. \u0003ורב חסדא אמר: מקנח בחרס ואין מקנח בצרור\u0004 משום מוקצה. \u0003מיתיבי\u0004 \u0005[מקשים\u0006 על כך ממה ששנינו בברייתא: \u0003היו לפניו צרור וחרס\u0004 — \u0003מקנח בחרס ואין מקנח בצרור,\u0004 והרי זו אם כן \u0003תיובתא\u0004 \u0005[קושיה\u0006 חמורה\u0005]\u0006 על שיטת \u0003רב הונא! תרגמא\u0004 \u0005[הסבירה]\u0006 \u0003רפרם בר פפא קמיה\u0004 \u0005[לפני]\u0006 \u0003רב חסדא אליבא\u0004 \u0005[על פי שיטת]\u0006 \u0003רב הונא:\u0004 לא בחרס סתם מדובר אלא \u0003באוגני כלים,\u0004 ששפת הכלי חלקה היא, ואין בקינוח בה משום סכנה. נפנה לצרכיו בשבת ו\u0003היו לפניו צרור ועשבים,\u0004 נחלקו בכך \u0003רב חסדא ורב המנונא, חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר: מקנח בצרור ואין מקנח בעשבים, וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר: מקנח בעשבים ואין מקנח בצרור. מיתיבי\u0004 \u0005[מקשים]\u0006 על כך ממה ששנינו: \u0003המקנח בדבר שהאור\u0004 \u0005[האש]\u0006 \u0003שולטת בו שיניו התחתונות\u0004 המחזיקות את המעי \u0003נושרות!\u0004 איך אם כן יקנח בעשבים? ומשיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 \u0003הא\u0004 \u0005[זה]\u0006 ששנינו שהותר הדבר הרי זה \u0003ב\u0004עשבים \u0003לחין, הא\u0004 \u0005[זה]\u0006 ששנינו שאסרו הרי זה \u0003ביבשין.\u0004","","ובנושאים אלה אמרו: \u0003הנצרך לפנות\u0004 (להיפנות) לצרכיו \u0003ואינו נפנה, רב חסדא ורבינא\u0004 נחלקו בכך; \u0003חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר: רוח רעה שולטת בו. וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר: רוח זוהמא שולטת בו. תניא כמאן דאמר\u0004 \u0005[שנויה\u0006 ברייתא \u0005כ\u0006דעת \u0005מי שאומר]\u0006 ש\u0003רוח זוהמא שולטת בו. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]\u0006 \u0003הנצרך לנקביו ואוכל\u0004 — דומה לתנור \u0003שהסיקוהו על גבי אפרו, וזו היא תחלת רוח זוהמא.\u0004","ועוד אמרו בענין זה, \u0003הוצרך ליפנות ואינו יכול ליפנות, אמר רב חסדא\u0004 עצה לדבר: \u0003יעמוד וישב, יעמוד וישב,\u0004 ויסייע לו הדבר. \u0003רב חנן מנהרדעא אמר: יסתלק לצדדין\u0004 וינסה להיפנות במקום אחר. \u0003רב המנונא אמר: ימשמש בצרור באותו מקום. ורבנן אמרי\u0004 \u0005[וחכמים אמרו]:\u0006 \u0003יסיח דעתו. אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא לרב אשי: כל שכן דכי מסח דעתיה לא מפני\u0004 \u0005[שכאשר יסיח דעתו לא ייפנה]!\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 רב אשי: יש להבין ש\u0003יסיח דעתו מדברים אחרים,\u0004 ויעסוק אך בנסיון להיפנות, ובכך יוושע. \u0003אמר רב ירמיה מדיפתי: לדידי חזי לי ההוא טייעא דקם ויתיב וקם ויתיב עד דשפך כקדרה\u0004 \u0005[אני ראיתי ערבי אחד שקם וישב, וקם וישב, עד ששפך כקדירה],\u0006 והרי שעצה זו מקובלת ומועילה. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003הנכנס לסעודת קבע\u0004 ורוצה להתכונן שלא יוכרח להפנות בשעת הסעודה, \u0003יהלך\u0004 לפני הסעודה \u0003עשר פעמים\u0004 מהלך \u0003של ארבע ארבע אמות, ואמרי לה\u0004 \u0005[ויש אומרים]:\u0006 \u0003ארבע פעמים של עשר עשר אמות\u0004 ויעזור הדבר להחיש את פעולת המעיים, \u0003ונפנה, ו\u0004אחר \u0003נכנס וישב\u0004 במקומו.","","שיעורו של \u0003חרס\u0004 להוצאת שבת — שיהיה בו \u0003כדי ליתן בין פצים לחברו\u0004 (בין עמוד לעמוד אחר להפריד ביניהם), אלו \u0003דברי ר' יהודה. ר' מאיר אומר:\u0004 צריך החרס להיות גדול עד \u0003כדי\u0004 שיוכל \u0003לחתות בו את האור\u0004 (האש). \u0003ר' יוסי אומר:\u0004 שבר חרס שיעורו \u0003כדי\u0004 שיוכל \u0003לקבל בו\u0004 (להחזיק) \u0003רביעית. אמר ר' מאיר: אף על פי שאין ראיה לדבר\u0004 לשיעור זה שקבעתי, מכל מקום יש \u0003זכר\u0004 (רמז) \u0003לדבר\u0004 בכתוב, שנאמר: \"ושברה כשבר נבל יוצרים כתות לא יחמול \u0003ולא ימצא במכתתו חרש לחתות אש מיקוד\"\u0004 (ישעיהו ל, יד). \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' יוסי: משם\u0004 אתה מביא \u0003ראיה?\u0004 והרי סופו של הפסוק הוא: \u0003\"ולחשף מים מגבא\",\u0004 הרי ששיעור חשוב של חרס הוא כדי לקבל בו מעט מים.","\u0003איבעיא להו\u0004 \u0005נשאלה להם\u0006 לבני הישיבה שאלה זו: האם \u0003שיעורא\u0004 \u0005השיעור\u0006 של \u0003ר' מאיר נפיש\u0004 \u0005[גדול\u0006 יותר\u0005],\u0006 \u0003או שיעורא\u0004 \u0005[השיעור]\u0006 של \u0003ר' יוסי נפיש\u0004 \u0005[גדול\u0006 יותר\u0005]?\u0006 ואומרים: \u0003מסתברא\u0004 \u0005[מסתבר]\u0006 לומר כי \u0003שיעורא\u0004 \u0005[השיעור]\u0006 של \u0003ר' יוסי נפיש\u0004 \u0005[גדול\u0006 יותר\u0005],\u0006 \u0003ו\u0004אולם לפי ה\u0003מקרא\u0004 נראה כי \u0003שיעורא\u0004 \u0005[השיעור]\u0006 של \u0003ר' מאיר נפיש\u0004 \u0005[גדול\u0006 יותר\u0005].\u0006 \u0003דאי סלקא דעתך\u0004 \u0005[שאם יעלה על דעתך]\u0006 לומר כי \u0003שיעורא\u0004 \u0005[השיעור]\u0006 של \u0003ר' יוסי\u0004 לגבי חרס \u0003נפיש\u0004 \u0005[גדול\u0006 יותר\u0005],\u0006 אם כן וכי תבין את הפסוק שבתחילה \u0003לייט לה במנא זוטרא\u0004 \u0005[\u0006\u0005מקלל אותו\u0006 הנביא שלא יימצא \u0005כלי קטן],\u0006 \u0003והדר לייט לה במנא רבה\u0004 \u0005[\u0006\u0005[ואחר כך מקלל אותו בכלי גדול\u0006 יותר\u0005]?!\u0006 \u0003אמר אביי: מתניתין נמי\u0004 \u0005[משנתנו גם כן]\u0006 מדברת בחרס גדול הנצרך \u0003לחתות אש מיקידה\u0004 (ממדורה) \u0003גדולה,\u0004 ואף במשנה שיעורו של ר' מאיר הוא הגדול. שנינו במשנה ש\u0003ר' יוסי אומר: משם ראיה?!\u0004 ולדעתו ההוכחה מסופו של אותו פסוק עצמו. ומעירים: \u0003שפיר קאמר ליה\u0004 \u0005[יפה אמר לו]\u0006 \u0003ר' יוסי לר' מאיר! ור' מאיר\u0004 מה הוא עונה על כך — הוא מסביר כי בסגנון \u0003\"לא מיבעיא\u0004 \u0005[נצרכה]\u0006 \u0003\"קאמר\u0004 \u0005[אמר].\u0006 וכך יש להבין: \u0003לא מיבעיא מידי דחשיב לאינשי\u0004 \u0005[נצרכה\u0006 לומר ש\u0005דבר שחשוב לאנשים]\u0006 כשבר חרס גדול \u0003לא לישתכח ליה\u0004 \u0005[יימצא לו],\u0006 \u0003אלא אפילו מידי דלא חשיב לאינשי\u0004 \u0005[דבר שאינו חשוב לאנשים]\u0006 \u0003לא לישתכח ליה\u0004 \u0005[יימצא לו],\u0006 ואין לשון הפסוק סותרת את דברי ר' מאיר. \u0003אמר ר' עקיבא: מניין לעבודה זרה\u0004 (פסל אליל, וכיוצא בו) \u0003שמטמאה במשא,\u0004 שאדם הנושא אותה בלא לנגוע בה — נטמא, \u0003כ\u0004שם שכך הדין בטומאת ה\u0003נדה\u0004 — \u0003שנאמר: \"\u0004וטמאתם את צפר פסילי כספך ואת אפודת מסכת זהבך \u0003תזרם כמו דוה צא תאמר לו\"\u0004 (ישעיהו ל, כב), \u0003מה נדה\u0004 הקרויה במקרא \"דווה\" — \u0003מטמאה במשא. אף עבודה זרה מטמאה במשא.\u0004","","","","כיון שדיני עבודה זרה וטומאתה אינם מענין מסכת שבת, מביאים מן המשנה במסכת עבודה זרה את עיקריה של הלכה זו. \u0003תנן התם\u0004 \u0005[שנינו\u0006 במשנה \u0005שם]:\u0006 \u0003מי שהיה ביתו סמוך לעבודה זרה,\u0004 שכותל ביתו הוא גם כותל בית פולחן עבודה זרה, \u0003ונפל\u0004 הכותל המפריד — \u0003אסור לבנותו,\u0004 שאם יבנהו נמצא שבנה עבור עבודה זרה. ו\u0003כיצד יעשה? כונס\u0004 את הכותל \u0003לתוך\u0004 הקרקע \u0003שלו ארבע אמות ובונה\u0004 שם את הקיר."],["\u0003היה\u0004 מקום הכותל \u0003שלו ושל עבודה זרה\u0004 בשותפות \u0003נידון\u0004 אותו מקום \u0003מחצה על מחצה\u0004 לדין הרחקה, שבונה במחצית המקום הקרוב אליו. \u0003אבניו ועציו ועפריו\u0004 של מקום עבודה זרה \u0003מטמאים כשרץ,\u0004 שהנוגע בהם נטמא, מדברי חכמים, כנוגע בשרץ. ורמז לדבר — ממה \u0003שנאמר:\u0004 \"ולא תביא תועבה אל ביתך והיית חרם כמוהו \u0003שקץ תשקצנו\u0004 ותעב תתעבנו כי חרם הוא\" (דברים ז, כו), ו\"שקץ\" הריהו לשון שרץ. \u0003ר' עקיבא אומר:\u0004 עבודה זרה מטמאה \u0003כנדה,\u0004 וכפי \u0003שנאמר: \"תזרם כמו דוה\"\u0004 (ישעיהו ל, כב), \u0003מה נדה\u0004 (דוה) \u0003מטמאה במשא\u0004 שהנושא את הנדה אף על פי שאינו נוגע בה נטמא, \u0003אף עבודה זרה מטמאה במשא.\u0004 והוסיף ו\u0003אמר רבה\u0004 להסביר את הכתוב: \u0003\"תזרם\"\u0004 ש\u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 משמעו — \u0003נכרינהו מינך\u0004 \u0005[עשה אותם נכרים ממך,\u0006 בשבילך\u0005]\u0006 \u0003כזר.\u0004 ומה שנאמר בסופו של אותו פסוק \u0003\"צא תאמר לו\",\u0004 הכוונה היא — \u0003\"הכנס\" אל תאמר לו\u0004 בשום פנים.","\u0003ו\u0004לגופה של המחלוקת \u0003אמר רבה: ב\u0004טומאת \u0003משא דכולי עלמא לא פליגי\u0004 \u0005[הכל אינם חלוקים]\u0006 שעבודה זרה \u0003מטמאה, דהא אתקש\u0004 \u0005[שהרי הוקשה,\u0006 הושוותה\u0005]\u0006 \u0003לנדה\u0004 בכתוב. \u0003כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 היה זה \u0003ב\u0004דין \u0003אבן מסמא.\u0004 שיש בדיני נדה הלכה מיוחדת שנדה או זב היושבים על חפץ, ואפילו אבן שאינה מקבלת טומאה, כל המצוי מתחתיו נטמא ואפילו לא נגע בו. \u0003ר' עקיבא סבר\u0004 \u0005[סבור]:\u0006 טומאת עבודה זרה היא \u0003כנדה\u0004 לכל דבר. \u0003מה נדה מטמאה באבן מסמא\u0004 — \u0003אף עבודה זרה מטמאה באבן מסמא. ורבנן\u0004 סבורים שלענין זה דינה \u0003כשרץ. מה שרץ לא מטמא באבן מסמא\u0004 — \u0003אף עבודה זרה לא מטמאה באבן מסמא.\u0004","\u0003ו\u0004שואלים: מאחר ש\u0003ל\u0004דעת \u0003ר' עקיבא\u0004 דין עבודה זרה כנדה לכל דבר, \u0003למאי הלכתא\u0004 \u0005[למה,\u0006 לאיזו \u0005הלכה]\u0006 \u0003איתקש\u0004 \u0005[הוקשה,\u0006 הושווה דינה\u0005]\u0006 \u0003לשרץ?\u0004 ומסבירים: לשיטתו, לא לענין עבודה זרה עצמה נאמר, אלא \u0003למשמשיה,\u0004 החפצים שמשתמשים בהם לצורכה. ועוד שואלים: ולשיטת חכמים \u0003למאי הלכתא איתקש\u0004 \u0005[הוקשה,\u0006 הושווה דינה\u0005]\u0006 \u0003לנדה\u0004 — \u0003ל\u0004למד שמטמאה ב\u0003משא.\u0004 ואולם אם ההיקש היה לצורך זה בלבד, \u0003ולוקשה רחמנא\u0004 \u0005[ושתקיש,\u0006 תשווה \u0005אותה התורה]\u0006 \u0003לנבלה\u0004 שיש בה טומאת מגע, שהרי לשיטת חכמים זה דינה של עבודה זרה! ועונים: אם לענין דרגת הטומאות \u0003אין הכי נמי\u0004 \u0005[כן, כך גם כן\u0006 הדבר\u0005],\u0006 \u0003אלא\u0004 ההשוואה לנדה באה ללמד: \u0003מה נדה אין\u0004 טומאתה \u0003לאברין,\u0004 שנדה הנשענת באבר אחד בלבד על חפץ אינה מטמאה במשא (ראב\"ד), \u0003אף עבודה זרה אינה לאברין,\u0004 שחלק מעבודה זרה שוב אינו מטמא. ותוהים, \u0003ואלא הא דבעי\u0004 \u0005[זו ששאל]\u0006 \u0003רב חמא בר גוריא: עבודה זרה ישנה\u0004 בה טומאה \u0003לאברין או אינה לאברין?\u0004 אם כן \u0003תיפשוט ליה מהא, דלרבנן\u0004 \u0005[תפתור לו מכאן\u0006 כי \u0005ל\u0006דעת \u0005חכמים]\u0006 \u0003אינה לאברין!\u0004 ומשיבים: אמנם כן, אלא \u0003רב חמא בר גוריא אליבא\u0004 \u0005[על פי שיטת]\u0006 \u0003ר' עקיבא בעי לה\u0004 \u0005[שאל אותה]\u0006 ודבר זה לא נתברר לנו.","שיטה אחרת בפירוש מחלוקת זו \u0003ר' אלעזר אמר : באבן מסמא דכולי עלמא לא פליגי דלא\u0004 \u0005[הכל אינם חלוקים שאינה]\u0006 \u0003מטמאה. כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 היה זה \u0003ב\u0004ענין טומאת \u0003משא,\u0004 ש\u0003ר' עקיבא סבר\u0004 \u0005[סבור]\u0006 שעבודה זרה \u0003כנדה, מה נדה מטמאה במשא\u0004 — \u0003אף עבודה זרה מטמאה במשא. ורבנן סברי\u0004 \u0005[וחכמים סבורים]\u0006 כי דין עבודה זרה \u0003כשרץ, מה שרץ לא מטמאה במשא\u0004 — \u0003אף עבודה זרה לא מטמאה במשא.\u0004 ושואלים: \u0003ו\u0004לשיטת \u0003ר' עקיבא, למאי הלכתא איתקש\u0004 \u0005[למה,\u0006 לאיזו \u0005הלכה הוקשה,\u0006 הושוותה\u0005]\u0006 עבודה זרה \u0003לשרץ?\u0004 ומשיבים: \u0003ל\u0004דין \u0003משמשיה\u0004 של עבודה זרה, שאינם מטמאים במשא, ושואלים: \u0003ורבנן\u0004 \u0005[ו\u0006לדעת \u0005חכמים]\u0006 \u0003למאי הלכתא איתקש\u0004 \u0005[למה,\u0006 לאיזו \u0005הלכה הוקשה,\u0006 הושוותה\u0005]\u0006 עבודה זרה \u0003לנדה?\u0004 ומשיבים: \u0003מה נדה אינה\u0004 מטמאה \u0003לאברים, אף עבודה זרה אינה\u0004 מטמאה \u0003לאברים.\u0004"],["\u0003ו\u0004לשיטת \u0003ר' עקיבא למאי הלכתא איתקש\u0004 \u0005[למה,\u0006 לאיזו \u0005הלכה הוקשה,\u0006 הושוותה\u0005]\u0006 עבודה זרה \u0003לנדה?\u0004 — \u0003ל\u0004ענין טומאת \u0003משא, לוקשיה\u0004 \u0005[שיקיש,\u0006 ישווה \u0005אותה]\u0006 \u0003לנבלה\u0004 ולא יצטרך להשוותה לנידה ולשרץ! ומשיבים: \u0003אין, הכי נמי\u0004 \u0005[כן, גם כן כך]\u0006 \u0003אלא\u0004 ההשוואה לנדה באה ללמדנו \u0003מה נדה אינה\u0004 מטמאה \u0003לאברין,\u0004 שנדה הנשענת באבר אחד בלבד על חפץ אינה מטמאה במשא (ראב\"ד), \u0003אף עבודה זרה אינה\u0004 מטמאה \u0003לאברין,\u0004 שחלק מעבודה זרה שוב אינו מטמא. ושואלים: \u0003אלא הא דבעי\u0004 \u0005[\u0006שאלה \u0005זו ששאל]\u0006 \u0003רב חמא בר גוריא\u0004 אם \u0003עבודה זרה ישנה\u0004 טומאתה \u0003לאברים או אינה\u0004 מטמאה \u0003לאברים, תיפשוט ליה מהא\u0004 \u0005[תפתור לו\u0006 שאלה \u0005זו\u0006 \u0005מכאן]\u0006 \u0003בין לרבנן\u0004 \u0005[ל\u0006שיטת \u0005חכמים]\u0006 \u0003בין ל\u0004שיטת \u0003ר' עקיבא\u0004 ש\u0003אינה לאברים,\u0004 שהרי לפי הסבר זה גם ר' עקיבא מודה בכך! ודוחים: \u0003רב חמא בר גוריא כרבה מתני\u0004 \u0005[שונה]\u0006 \u0003ובעי לה אליבא\u0004 \u0005[ו\u0006עדיין יש מקום \u0005לשאול\u0006 \u0005אותה לפי שיטת]\u0006 \u0003ר' עקיבא.\u0004","מעתה באים לברר את שני ההסברים על פי מקורות אחרים. \u0003מיתיבי\u0004 \u0005[מקשים על כך]\u0006 ממה ששנינו בברייתא: \u0003עבודה זרה\u0004 טמאה \u0003כשרץ, ומשמשיה\u0004 טמאים אף הם \u0003כשרץ. ר' עקיבא אומר: עבודה זרה\u0004 מטמאה \u0003כנדה ומשמשיה\u0004 מטמאים \u0003כשרץ. בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004שיטת \u0003ר' אלעזר\u0004 — \u0003ניחא\u0004 \u0005[נוח\u0006 הדבר\u0005]\u0006 \u0003אלא ל\u0004שיטת \u0003רבה קשיא\u0004 \u0005[קשה],\u0006 שהרי מכאן יוצא שהמחלוקת היא אם עבודה זרה כשרץ או כנידה, ולא באבן מסמא! \u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך רבה\u0004 כתשובה: \u0003מי אלימא ממתניתין\u0004 \u0005[האם חזקה\u0006 היא זו יותר \u0005ממשנתנו],\u0006 \u0003דקתני\u0004 \u0005[ש\u0006הרי אף במשנתנו \u0005שנינו]:\u0006 \u0003\"עציו ואבניו ועפריו מטמאין כשרץ\" ואוקימנא\u0004 \u0005[והעמדנו,\u0006 והסברנו\u0005]\u0006 \u0003מאי\u0004 \u0005[מהו]\u0006 \u0003כשרץ\u0004 — לא לכל דבר, אלא \u0003דלא\u0004 \u0005[שאינו]\u0006 \u0003מטמא ב\u0004טומאת \u0003אבן מסמא, הכא נמי\u0004 \u0005[כאן גם כן]\u0006 \u0003דלא\u0004 \u0005[שאינו]\u0006 \u0003מטמא באבן מסמא,\u0004 ואף ברייתא זו נבין באותה דרך.","ועוד \u0003מיתיבי\u0004 \u0005[מקשים]\u0006 ממה ששנינו: \u0003גוי וגויה\u0004 שגזרו חכמים עליהם שיהיו מטמאים כזבים, \u0003עבודה זרה ומשמשיה\u0004 — \u0003הן\u0004 מטמאים, \u0003ו\u0004אולם \u0003לא היסטן,\u0004 שהמסיטם (מזיזם, נושאם) אינו נטמא. \u0003ר' עקיבא אומר: הן והיסטן,\u0004 שאף אלה מטמאים במשא. \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004שיטת \u0003ר' אלעזר\u0004 — \u0003ניחא\u0004 \u0005[נוח,\u0006 מובן הדבר\u0005],\u0006 \u0003אלא לרבה קשיא\u0004 \u0005[קשה]\u0006 \u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך רבה: וליטעמיך\u0004 \u0005[ולטעמך,\u0006 לשיטתך\u0005]\u0006 \u0003גוי וגויה נמי\u0004 \u0005[גם כן]\u0006 \u0003הן\u0004 מטמאים \u0003ולא היסטן?! והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003\"דבר אל בני ישראל\u0004 ואמרתם אליהם איש איש כי יהיה זב מבשרו זובו טמא הוא\u0003\"\u0004 (ויקרא טו, ב). ומכאן למדנו שמדין תורה רק \u0003בני ישראל\u0004 הם \u0003מטמאין בזיבה ואין גוים מטמאין בזיבה, אבל גזרו עליהן\u0004 חכמים \u0003שיהו כזבין לכל דבריהן\u0004 (דיניהם) ומאחר שהגוים דינם כזבים — מטמאים הם גם במשא. ולפיכך אותה ברייתא שנאמר בה שאין הגוים מטמאים במשא, משובשת היא וצריכה תיקון.","\u0003אלא רבה מתרץ לטעמיה\u0004 \u0005[ מתרץ\u0006 ומוסיף על דברי הברייתא \u0005לשיטתו]\u0006 וכך הוא שונה: \u0003גוי וגויה\u0004 מטמאים \u0003הן והיסטן ואבן מסמא שלה,\u0004 ו\u0003עבודה זרה\u0004 מטמאים \u0003היא והיסטה, אבל לא אבן מסמא שלה. ר' עקיבא אומר:\u0004 אף \u0003עבודה זרה\u0004 מטמאים \u0003היא והסיטה ואבן מסמא שלה.\u0004 וכן \u0003ר' אלעזר מתרץ\u0004 \u0005[מיישב]\u0006 את הדברים ומוסיף על ברייתא זו, וכך הוא לומד: \u0003גוי וגויה\u0004 מטמאים \u0003הן והיסטן ואבן מסמא שלהן, עבודה זרה\u0004 מטמאה \u0003היא ו\u0004אולם \u0003לא היסטה. ור' עקיבא אומר: עבודה זרה\u0004 מטמאה \u0003היא והסיטה\u0004.","\u0003מתקיף לה\u0004 \u0005[מקשה עליו]\u0006 על הסבר זה \u0003רב אשי:\u0004 לפי הדרך שהסברנו אין להבין \u0003מאי\u0004 \u0005[מה]\u0006 נתחדש על המלה \u0003\"הן\"\u0004 שבברייתא זו? ודי היה לומר שמטמאים והיסטן מטמא, ואילו ההדגשה \"הן\" חייבים לראותה כבעלת משמעות מיוחדת! \u0003אלא אמר רב אשי, הכי קאמר\u0004 \u0005[כך אמר]:\u0006 \u0003גוי וגויה בין הן שהסיטו את אחרים ובין אחרים שהסיטו אותן\u0004 — \u0003טמאים,\u0004 שמיוחדת טומאת זיבה, שכל דבר שהזב מזיזו ממקומו אף אם לא נגע בו במישרין — נטמא. ואילו \u0003עבודה זרה שהסיטה אחרים\u0004 — \u0003טהורין,\u0004 ואילו \u0003אחרים שהסיטו אותה\u0004 (במשא) — \u0003טמאים. משמשיה\u0004 של עבודה זרה, \u0003בין הן שהסיטו את אחרים ובין אחרים שהסיטו אותן\u0004 — \u0003טהורים.\u0004 ו\u0003ר' עקיבא אומר: גוי וגויה ועבודה זרה, בין הן שהסיטו את אחרים ובין אחרים שהסיטו אותן\u0004 — \u0003טמאים. משמשיה, בין הן שהסיטו אחרים ובין אחרים שהסיטו אותן\u0004 — \u0003טהורין,\u0004 ועל ידי כך קבלה כל מלה במשפט המקורי את מובנה המדויק, גם לגבי המלה 'הן' וגם לגבי המונח 'היסט'.","הסברו של רב אשי מבאר את הברייתא, אך לגוף הדברים שואלים: לגבי \u0003עבודה זרה, בשלמא\u0004 \u0005[נניח]\u0006 \u0003אחרים שהסיטו אותה\u0004 — \u0003משכחת לה\u0004 \u0005[מוצא אתה\u0006 כעין זה\u0005].\u0006 \u0003אלא היא שהסיטה את אחרים היכי משכחת לה\u0004 \u0005[איך מוצא אתה אותה]?\u0006 וכיצד יתכן שעבודה זרה תוכל לפעול ולהסיט דברים? \u0003אמר רמי בריה\u0004 \u0005[בנו]\u0006 של \u0003רב ייבא\u0004 אפשר למצוא אפשרות כזאת, \u0003כדתנן\u0004 \u0005[כפי ששנינו\u0006 במשנה\u0005]:\u0006 היה \u0003הזב בכף מאזנים\u0004 אחת, \u0003ואוכלין ומשקין בכף\u0004 ה\u0003שנייה, כרע הזב,\u0004 שהכריעה, הכבידה, כף המאזנים של הזב — \u0003טמאין\u0004 המאכלים שבכף השניה משום שהזב הסיט אותם ממקומם."],["\u0003כרעו\u0004 \u0005[הכבידו]\u0006 \u0003הן טהורין.\u0004 ושואלים: \u0003כמאן אזלא הא דתניא\u0004 \u0005[כשיטת\u0006 מי הולכת, מכוונת, ברייתא \u0005זו ששנינו]\u0006 \u0003כל הטמאות המסיטות\u0004 אחרים \u0003טהורות.\u0004 כלומר: אין דבר נטמא משום שהטומאה הזיזה אותו \u0003חוץ מהיסטו של זב, שלא מצינו לו חבר בכל התורה כולה, לימא דלא כר' עקיבא, דאי כר' עקיבא\u0004 — \u0003איכא נמי עבודה זרה\u0004 \u0005[האם נאמר שאין זה\u0006 כשיטת \u0005ר' עקיבא, שאם כר' עקיבא\u0006 הרי \u0005יש גם כן\u0006 עבודה זרה] שלשיטתו אף היא מטמאה בהיסט! ומשיבים: \u0003אפילו תימא ר' עקיבא, תנא זב וכל דדמי ליה\u0004 \u0005[אפילו תאמר\u0006 שהברייתא כשיטת \u0005ר' עקיבא, אלא שנה\u0006 כאן \u0005זב וכל הדמים לו]\u0006 שכשם שנדה נכנסת באותה הגדרה, אף עבודה זרה דינה לר' עקיבא כדין הזב.","אותה שאלה שהובאה קודם לכן כבדרך אגב, מפורשת עתה בהרחבה. \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב חמא בר גוריא:\u0004 האם \u0003עבודה זרה ישנה לאברים,\u0004 שאם נגע חלק אחד שהתפרק ממנה בדבר טהור הריהו מטמאהו ואין צורך כדי לטמא שתהיה שלימה על כל איבריה, \u0003או אינה לאברים?\u0004 ומצמצמים את השאלה: \u0003היכא\u0004 \u0005[היכן\u0006 כאשר\u0005]\u0006 ש\u0003הדיוט\u0004 שאינו בקיא במלאכה זו \u0003יכול להחזירה\u0004 לכמו שהיתה — \u0003לא תיבעי\u0004 \u0005[תישאל]\u0006 \u0003לך\u0004 השאלה, שזאת ודאי \u0003דכמאן\u0004 \u0005[שכמי]\u0006 ש\u0003מחברת דמי\u0004 \u0005[היא נחשבת],\u0006 שאין זו נחשבת כשבירה. \u0003כי תיבעי\u0004 \u0005[כאשר\u0006 יש מקום ש\u0005תישאל]\u0006 \u0003לך\u0004 השאלה, הרי זה כאשר \u0003אין הדיוט יכול להחזירה, מאי\u0004 \u0005[מה]\u0006 יהא הדין בכגון זה? וצדדי השאלה: האם נאמר כי \u0003כיון\u0004 ש\u0003אין הדיוט יכול להחזירה, כמאן דמתברא דמי\u0004 \u0005[כשבורה היא נחשבת],\u0006 \u0003או דילמא\u0004 \u0005[שמא]\u0006 תאמר: \u0003הא לא מחסרה\u0004 \u0005[הרי אינה חסרה\u0006 דבר\u0005]\u0006 ועבודה זרה שנתבטלה בגלל שבירתה הריהי רק זו שנחסר בה דבר. \u0003ואיכא דבעי לה להך גיסא\u0004 \u0005[ויש ששאל\u0006 שאלה \u0005זו לצד זה]\u0006 באופן אחר, ומתוך הנחת יסוד שונה: \u0003היכא\u0004 \u0005[במקום]\u0006 ש\u0003אין הדיוט יכול להחזירה\u0004 — \u0003לא תיבעי\u0004 \u0005[תישאל]\u0006 \u0003לך\u0004 השאלה, שודאי \u0003דכמאן דמתברא דמי\u0004 \u0005[שכמי ששבורה היא נחשבת].\u0006 אלא \u0003כי תיבעי\u0004 \u0005[כאשר\u0006 יש מקום ש\u0005תישאל]\u0006 \u0003לך\u0004 השאלה, הרי זה \u0003היכא\u0004 \u0005[במקום]\u0006 ש\u0003הדיוט יכול להחזירה, מאי\u0004 \u0005[מה]\u0006 יהא הדין בכגון זה? האם נאמר כי \u0003כיון\u0004 ש\u0003הדיוט יכול להחזירה\u0004 — \u0003כמאן דמחברא דמי\u0004 \u0005[כמי שמחוברת היא נחשבת],\u0006 \u0003או דילמא השתא מיהא קשלפה ושריא\u0004 \u0005[שמא עכשיו לפחות מפורקת היא ומותרת].\u0006 לשאלה זו לא נמצאה תשובה בשתי הגירסות, ולכן \u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב אחדבוי בר אמי: עבודה זרה\u0004 שגודלה \u0003פחותה מכזית, מהו\u0004 דינה? \u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב יוסף: למאי\u0004 \u0005[למה,\u0006 לאיזה ענין\u0005]\u0006 השאלה? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003לענין איסורא\u0004 \u0005[איסור]\u0006 שבעבודה זרה, \u0003לא יהא אלא\u0004 כ\u0003זבוב בעל עקרון,\u0004 שהיה בתבנית ובגודל של זבוב. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]\u0006 על הכתוב \u0003\"וישימו להם בעל ברית לאלהים\"\u0004 (שופטים ח, לג) ואמרו ש\u0003זה זבוב בעל עקרון. מלמד שכל אחד ואחד עשה דמות יראתו\u0004 (אלילו) \u0003ו\u0004היה \u0003מניחה בתוך כיסו, כיון שזוכרה מוציאה מתוך כיסו ומחבקה ומנשקה.\u0004 ולמדנו מכאן שאף בגודל זה הנכנסת לכיס בגדו עבודה זרה היא. \u0003אלא\u0004 השאלה היתה \u0003לענין טומאה מאי\u0004 \u0005[מה\u0006 דינה\u0005]?\u0006 וצדדי השאלה: \u0003כיון דאיתקיש\u0004 \u0005[שהוקשה,\u0006 הושוותה\u0005]\u0006 עבודה זרה \u0003לשרץ,\u0004 יש לומר אם כן: \u0003מה שרץ\u0004 טומאתו אף בשיעור קטן \u0003בכעדשה, אף עבודה זרה נמי\u0004 \u0005[גם כן]\u0006 יהא שיעורה \u0003בכעדשה. או דילמא\u0004 \u0005[שמא]:\u0006 \u0003הא איתקיש\u0004 \u0005[הרי\u0006 \u0003הוקשה,\u0004 הושוותה\u0005]\u0006 עבודה זרה \u0003למת,\u0004 ו\u0003מה מת\u0004 אינו מטמא אלא \u0003ב\u0004שיש בו שיעור \u0003כזית, אף עבודה זרה\u0004 שיעורה \u0003בכזית.\u0004","\u0003אמר רב אויא ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003רבה בר עולא, תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לשאלה זו ממה \u0003דתניא\u0004 \u0005[ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003עבודה זרה פחותה מכזית אין בה טומאה כל עיקר, שנאמר: \"\u0004ויוצא את האשרה מבית ה' מחוץ לירושלים אל נחל קדרון וישרוף אותה בנחל קדרון וידק לעפר \u0003וישלך את עפרה על קבר בני העם\"\u0004 (מלכים ב' כג, ו). ואנו למדים מכאן: \u0003מה מת\u0004 שיעורו לטמא \u0003בכזית אף עבודה זרה\u0004 שיעורה לטמא \u0003בכזית.\u0004","וכאן שואלים שאלה כללית, \u0003ורבנן\u0004 \u0005[ו\u0006לדעת \u0005חכמים]\u0006 \u0003למאי הלכתא איתקש\u0004 \u0005[למה,\u0006 לאיזו \u0005הלכה הוקשה,\u0006 הושוותה\u0005]\u0006 עבודה זרה \u0003לשרץ\u0004 — ללמד שכשרץ הריהי \u0003לא מטמא במשא,\u0004 והושוותה \u0003לנדה\u0004 — ללמד שכמו נדה \u0003אינה\u0004 מטמאה \u0003לאברין,\u0004 והושוותה \u0003למת\u0004 — ללמד שהיא \u0003לא מטמא ב\u0004שיעור \u0003כעדשה. אימא לחומרא\u0004 \u0005[אמור\u0006 את כל ההשוואות \u0005לחומרה]\u0006 ובדרך זו: \u0003למאי הלכתא אקשה רחמנא\u0004 \u0005[למה,\u0006 לאיזו \u0005הלכה הקיש,\u0006 השווה \u0005אותה הכתוב]\u0006 \u0003לשרץ\u0004 — \u0003לטמויי\u0004 \u0005[לטמא אותה]\u0006 \u0003בכעדשה,\u0004 והשווה אותה הכתוב \u0003לנדה\u0004 — \u0003לטמויי\u0004 \u0005[לטמא אותה]\u0006 \u0003באבן מסמא,\u0004 ו\u0003אקשה רחמנא\u0004 \u0005[הקיש,\u0006 השווה \u0005אותה הכתוב]\u0006 \u0003למת\u0004 — \u0003לטמויי\u0004 \u0005[לטמא אותה]\u0006 \u0003באהל\u0004 ככל החומרות שיש בטומאות אלה! ומשיבים: \u0003טומאת עבודה זרה דרבנן\u0004 \u0005[מדברי סופרים]\u0006 \u0003היא, ו\u0004בכל דבר שבדברי סופרים שיש בו \u0003קולא וחומרא\u0004 \u0005[להקל ולהחמיר]\u0006 בדרך כלל \u0003לקולא מקשינן, לחומרא לא מקשינן\u0004 \u0005[להקל אנו מקישים,\u0006 משווים, \u0005להחמיר איננו מקישים].\u0006","ועוד משנה אחת שלא לענין המסכת, המובאת כאן משום שאף היא מבוססת על רמז שבכתוב. \u0003מנין לספינה שהיא טהורה\u0004 ואינה מקבלת כל טומאה — \u0003שנאמר: \"דרך אניה בלב ים\"\u0004 (משלי ל, יט).","הרמז שבמשנה דורש ביאור, שכן מה שנאמר בכתוב ש\"דרך אניה בלב ים\" לכאורה \u0003הוא פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005],\u0006 שהרי ודאי \u0003אניה בלב ים היא!\u0004 אלא \u0003הא קא משמע לן\u0004 \u0005[\u0006דבר \u0005זה השמיע לנו]\u0006 הכתוב בדרך רמז: שדין האניה \u0003כים, מה ים טהור\u0004 מלקבל טומאה, \u0003אף ספינה טהורה\u0004 מלקבל טומאה. \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003חנניה אומר: נלמדה\u0004 הלכה זו \u0003מ\u0004דין \u0003שק.\u0004 שכן הושוו טומאות כל כלי עץ לטומאת שק. וכלל הוא, \u0003מה שק\u0004 המקבל טומאה הריהו \u0003מיטלטל\u0004 גם \u0003מלא ו\u0004גם \u0003ריקן, אף כל\u0004 דבר ה\u0003מיטלטל מלא וריקן\u0004 מקבל טומאה, \u0003לאפוקי\u0004 \u0005[להוציא]\u0006 \u0003ספינה\u0004 ש\u0003אינה מיטלטלת\u0004 ביבשה \u0003מלא וריקן,\u0004 שמפני כובדה אינה ניתנת לטלטול כשהיא מלאה.","ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל המעשי \u0005ביניהם]?\u0006 שהרי להלכה הכל מודים שאין ספינה מקבלת טומאה. ומסבירים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל\u0005]\u0006 לענין \u0003ספינה של חרס\u0004 או של חומר אחר שאינו עץ. \u0003מאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 שלמדים זאת מן הכתוב \u0003\"אניה בלב ים\"\u0004 — \u0003הא נמי\u0004 \u0005[\u0006אניה \u0005זו גם כן]\u0006 \u0003בלב ים היא.\u0004 אבל \u0003למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 שהטעם הוא בהשוואה ל\u0003שק, הנך דכתיבי גבי\u0004 \u0005[\u0006דווקא ב\u0005אלו הכתובים אצל]\u0006 \u0003שק\u0004 ומושווים לו בדינם, \u0003דאי\u0004 \u0005[שאם]\u0006 \u0003מיטלטלת מלא וריקן\u0004 — \u0003אין\u0004 \u0005[כן]\u0006 מקבלת טומאה, \u0003אי\u0004 \u0005[אם]\u0006 \u0003לא\u0004 — \u0003לא. אבל ספינה של חרס\u0004 — \u0003אף על גב\u0004 ש\u0003אינה מיטלטלת מלא וריקן\u0004 הריהי מקבלת טומאה.","\u0003אי נמי\u0004 \u0005[או גם כן]\u0006 יש הבדל ביניהם לענין \u0003ספינת הירדן,\u0004 שהיא ספינה קטנה שנוסעים בה בירדן. \u0003למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 שלמדים זאת מן הכתוב \u0003\"אניה בלב ים היא\u0004 \u0003\"\u0004— \u0003הא נמי\u0004 \u0005[זו גם כן]\u0006 \u0003בלב ים היא,\u0004 שהרי הנהר טהור כים, וטהורה. ו\u0003למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 שההשוואה היא לשק וכדי להיטמא הרי צריכה להיות \u0003מיטלטלת מלא וריקן\u0004 — \u0003הא נמי\u0004 \u0005[זו גם כן]\u0006 \u0003מיטלטלת מלא וריקן,\u0004 וראויה לקבל טומאה. ש\u0003אמר ר' חנינא בן עקביא: מפני מה אמרו\u0004 ש\u0003ספינת הירדן טמאה\u0004 (מקבלת טומאה) — \u0003מפני שטוענים אותה ביבשה\u0004 ומטלטלים אותה ביבשה, \u0003ו\u0004רק לאחר הטענתה \u0003מורידין אותה למים.\u0004 נמצא שהיא מיטלטלת מלאה ביבשה. \u0003אמר רב יהודה אמר רב: לעולם אל ימנע אדם את עצמו מבית המדרש ואפילו שעה אחת, שהרי כמה שנים נשנית משנה זו\u0004 שספינת הירדן טמאה \u0003בבית המדרש ולא נתגלה טעמה עד שבא ר' חנינא בן עקביא ופירשה.\u0004","ואגב דברי רב, הביאו מה ש\u0003אמר ר' יונתן: לעולם אל ימנע אדם עצמו מבית המדרש ומדברי תורה ואפילו בשעת מיתה, שנאמר: \"זאת התורה אדם כי ימות באהל\"\u0004 (במדבר יט, יד), ולשון הכתוב רומזת לכך ש\u0003אפילו בשעת מיתה תהא עוסק בתורה\u0004 הזאת. \u0003אמר ריש לקיש: אין דברי תורה מתקיימין אלא במי שממית עצמו עליה,\u0004 שמוכן להתמסר לה בכל כוחותיו, \u0003שנאמר: \"זאת התורה אדם כי ימות באהל\",\u0004 שאין התורה נקנית אלא לממית עצמו באהלה. \u0003אמר רבא\u0004"],["\u0003ול\u0004דעת \u0003חנניא\u0004 הסובר כי ספינה המיטלטלת כשהיא מלאה מקבלת טומאה, \u0003טילטול\u0004 הספינה \u0003על ידי שוורים שמיה\u0004 \u0005[שמו,\u0006 נחשב\u0005]\u0006 \u0003טילטול?\u0004 והוא עצמו משיב: \u0003אין\u0004 \u0005[כן\u0006 הוא\u0005],\u0006 \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003שלש\u0004 סוגי \u0003עגלות הן\u0004 הנבדלות זו מזו לדיני טומאה וטהרה. עגלה ה\u0003עשויה כקתידרא,\u0004 שהיא בנויה בדומה לכסא, וסגורה מן הצדדים — \u0003טמאה מדרס,\u0004 כיון שהיא מיוחדת לישיבה, ואם ישב עליה זב נטמאה. עגלה העשויה \u0003כמטה\u0004 — \u0003טמאה טמא מת,\u0004 שמקבלת כל טומאה, חוץ מטומאת מדרס הזב. ועגלה \u0003של אבנים\u0004 שתחתיתה כרשת — \u0003טהורה מכלום\u0004 (מכל טומאה). \u0003ואמר ר' יוחנן: ואם יש בה\u0004 בעגלת האבנים מקום שהוא \u0003בית קבול רמונים,\u0004 שהנקבים אינם גדולים עד כדי שיפול דרכם רימון הרי היא נחשבת ככלי, ו\u0003טמאה טמא מת.\u0004 ולמדנו מכאן, שעגלת אבנים אף שאינה מיטלטלת כשהיא מלאה, אלא נמשכת על ידי שוורים — מקבלת טומאה, שטילטול על ידי שוורים — שמו טילטול.","ואגב הבאת משנה זו מביאים גם את המשכה, \u0003שלש תיבות הן\u0004 לדיני טומאה: \u0003תיבה שפתחה מצדה\u0004 ואפשר לשבת ולשכב עליה — \u0003טמאה מדרס\u0004 אם יושב עליה הזב, שהרי תיבה זו ראויה לישיבה, וגם כשצריך לפתחה אפשר להמשיך לשבת ולשכב עליה. תיבה שפתחה \u0003מלמעלה\u0004 — אינה טמאה מדרס, משום שיש לקום כשצריכים לפתוח את התיבה, אבל \u0003טמאה טמא מת. ו\u0004תיבה \u0003הבאה במדה,\u0004 כלומר, גדולה מאד, שקיבולה יותר מארבעים סאה, \u0003טהורה מכלום.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003מדרס כלי חרס טהור,\u0004 שהזב היושב על כלי חרס ואינו נוגע בתוכו אינו מטמא. \u0003ר' יוסי אומר: אף הספינה.\u0004 ושואלים: \u0003מאי קאמר\u0004 \u0005[מה אמר,\u0006 מה כוונת\u0005]?\u0006 ר' יוסי בדבריו? \u0003אמר רב זביד: הכי קאמר\u0004 \u0005[כך אמר]:\u0006 לדעת התנא הראשון \u0003מדרס\u0004 הזב על גבי \u0003כלי חרס\u0004 — \u0003טהור\u0004 (אינו מטמא), \u0003ומגעו\u0004 של הזב בכלי \u0003טמא\u0004 (מטמא), \u0003וספינה של חרס\u0004 אף היא \u0003טמאה\u0004 במדרס הזב עליה \u0003כ\u0004שיטת \u0003חנניא.\u0004 ואולם \u0003ר' יוסי אומר: אף הספינה טהורה, כתנא דידן\u0004 \u0005[כ\u0006שיטת \u0005התנא\u0006 במשנה \u0005שלנו].\u0006 \u0003מתקיף לה\u0004 \u0005[מקשה עליה]\u0006 על הסברה זו \u0003רב פפא:\u0004 אם כן \u0003מאי\u0004 \u0005[מה,\u0006 מדוע\u0005]\u0006 אמר ר' יוסי בלשון \u0003\"אף\"\u0004 שממנו משמע שבא להוסיף על הדבר? והלא לפי הסבר זה לא בא להוסיף דברים אלא לומר היפך האמור קודם, שהוא אומר טעם כאשר קודם לכן הוזכר רק \"טהור\", ואי אפשר להשתמש לצורך זה במלה \"אף\"! \u0003אלא אמר רב פפא, הכי קאמר\u0004 כך יש להבין: \u0003מדרס כלי חרס\u0004 — \u0003טהור, ומגעו טמא. ושל\u0004 כלי \u0003עץ, בין מדרסו ובין מגעו\u0004 — \u0003טמא, וספינת הירדן\u0004 — \u0003טהורה כ\u0004שיטת ה\u0003תנא דידן\u0004 \u0005[שלנו\u0006 במשנה\u0005].\u0006 \u0003ר' יוסי אומר: אף הספינה טמאה\u0004 כשאר כלי עץ, ו\u0003כ\u0004שיטת \u0003חנניא.\u0004","ולגופו של הדבר שהוזכר שואלים: \u0003ומדרס כלי חרס מנלן\u0004 \u0005[מנין לנו]\u0006 ש\u0003טהור? אמר חזקיה:\u0004 הדבר נלמד ממה ש\u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"ואיש אשר יגע במשכבו\u0004 יכבס בגדיו ורחץ במים וטמא עד הערב\u0003\"\u0004 (ויקרא טו, ה), שבו \u0003מקיש\u0004 \u0005[משווה]\u0006 הכתוב את \u0003משכבו לו,\u0004 ובכך הוא מלמד: \u0003מה הוא,\u0004 הזב, \u0003אית ליה\u0004 \u0005[יש לו]\u0006 \u0003טהרה במקוה\u0004 — \u0003אף משכבו\u0004 גם כן מדובר דווקא בזה שיש לו \u0003טהרה במקוה.\u0004 וכיון שכלי חרס שנטמא אין לו טהרה כשאר כלים, לכן אף אינו נכלל בין הכלים המקבלים טומאת משכב הזב.","\u0003דבי\u0004 \u0005[\u0006בני \u0005בית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל תנא\u0004 \u0005[שנו]\u0006 בדומה לכך: במה שאמר הכתוב \u0003\"\u0004כל המשכב אשר תשכב עליו כל ימי זובה \u0003כמשכב נדתה יהיה לה\"\u0004 (ויקרא טו, כו) הריהו \u0003מקיש\u0004 \u0005[משווה]\u0006 בכך את \u0003משכבה לה: מה היא אית\u0004 \u0005[יש]\u0006 \u0003לה טהרה במקוה\u0004 — \u0003אף משכבה נמי אית\u0004 \u0005[גם כן\u0006 מדובר באופן \u0005שיש]\u0006 \u0003לה טהרה במקוה, לאפוקי\u0004 \u0005[להוציא]\u0006 \u0003כלי חרס דלית ליה\u0004 \u0005[שאין לו]\u0006 \u0003טהרה במקוה. מתיב\u0004 \u0005[מקשה\u0006 על כך\u0005]\u0006 \u0003ר' אילעא\u0004 ממה ששנינו: \u0003מפץ\u0004 (מחצלת העשויה מקני סוף) הוכחה לכך שהיא מקבלת טומאה \u0003במת מנין\u0004 לנו?"],["\u0003ודין הוא\u0004 שיהא כן \u0003ומה פכין קטנים\u0004 של חרס \u0003שטהורין\u0004 מטומאת \u0003זב,\u0004 שאינם נטמאים במושב הזב ואין הזב יכול לטמאם מבפנים משום שאי אפשר להכניס בהם אצבע, ובכל זאת \u0003טמאים\u0004 הם \u0003ב\u0004טומאת \u0003מת, מפץ שטמא בזב, אינו דין שיהא טמא ב\u0004טומאת \u0003מת. ואמאי\u0004 \u0005[ומדוע]\u0006 יהא המפץ טמא? \u0003הא לית ליה\u0004 \u0005[\u0006ו\u0005הרי אין לו]\u0006 \u0003טהרה במקוה! אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' חנינא: שאני התם\u0004 \u0005[שונה שם]\u0006 במפץ \u0003הואיל ואיכא\u0004 \u0005[ויש]\u0006 טומאה \u0003במינו,\u0004 כיון שכלי עץ האחרים שהם כמו המפץ באים מן הצומח נטהרים במקוה.","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 ר' אילעא לר' חנינא: \u0003רחמנא ליצלן מהאי דעתא\u0004 \u0005[השם יצילנו מן הדיעה הזאת],\u0006 ענה לו ר' חנינא: \u0003אדרבא, רחמנא ליצלן מדעתא דידך\u0004 \u0005[להיפך, השם יצילנו מן הדיעה שלך].\u0006 \u0003וטעמא מאי\u0004 \u0005[ומהו הטעם]\u0006 שאנו חושבים שטומאה במינו היא נימוק בעל משמעות לגבי דבר שהוא עצמו אינו נכנס לגדר זה — משום ש\u0003תרי קראי כתיבי\u0004 \u0005[שני כתובים נאמרו];\u0006 בפסוק אחד \u0003כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"ואיש אשר יגע במשכבו\u0004 יכבס בגדיו ורחץ במים וטמא עד הערב\u0003\"\u0004 (ויקרא טו ה), ומפסוק זה למדנו שמשכבו בדומה לו, שאף משכב הזב צריך שיהא עשוי להיטהר בטבילה. \u0003ו\u0004בפסוק אחר \u0003כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"ו כל המשכב אשר ישכב עליו הזב יטמא\u0004 וכל הכלי אשר ישב עליו יטמא\u0003\"\u0004 (ויקרא טו, פסוק ד), ופסוק זה כולל לעניין קבלת טומאת זב כל משכב, אפילו כזה שאינו נטהר בטבילה. \u0003הא\u0004 \u0005[הרי]\u0006 \u0003כיצד\u0004 ניישב את שני המקראות? אלא יש לומר כך: אם \u0003יש במינו\u0004 טהרה \u0003אף על גב דלית ליה\u0004 \u0005[אף על פי שאין לו\u0006 עצמו] \u0003טהרה במקוה\u0004 — יהא טמא. ואולם אם \u0003אין במינו\u0004 כלל טהרה, לאופן כגון זה \u0003מקיש\u0004 \u0005[משווה]\u0006 הכתוב את \u0003משכבו לו,\u0004 וכיון שאינו דומה לו שהרי אין לו טהרה במקוה, לכן המשכב טהור.","\u0003רבא אמר:\u0004 זה ש\u0003מדרס כלי חרס טהור\u0004 למדים \u0003מהכא\u0004 \u0005[מכאן],\u0006 שנאמר: \u0003\"וכל כלי פתוח אשר אין צמיד פתיל עליו\u0004 טמא הוא\u0003\"\u0004 (במדבר יט, טו), ומשמע: \u0003הא\u0004 \u0005[הרי]\u0006 אם \u0003יש צמיד פתיל עליו\u0004 — \u0003טהור הוא.\u0004 ו\u0003מי לא עסקינן דיחדינהו\u0004 \u0005[האם איננו עוסקים\u0006 גם במקרה \u0005שייחד אותו,\u0006 את הכלי\u0005]\u0006 \u0003ל\u0004שימוש \u0003אשתו נדה ו\u0004בכל זאת \u0003קאמר רחמנא\u0004 \u0005[אמרה תורה]\u0006 שהוא \u0003טהור,\u0004 והרי שכלי חרס הסגור ומכוסה אינו מקבל טומאה מכל מטמא.","ועוד הלכה הבנויה על רמז בכתוב: \u0003מנין לערוגה שהיא\u0004 (ששטחה) \u0003ששה על ששה טפחים שזורעין בתוכה חמשה\u0004 מיני \u0003זרעונין\u0004 בלי לחשוש לאיסור כלאיים בין המינים, באופן זה: שזורעים \u0003ארבעה\u0004 מיני זרעים \u0003על ארבע רוחות הערוגה ואחת באמצע.\u0004 ורמז לדבר ממה \u0003שנאמר: \"כי כארץ תוציא צמחה וכגנה זרועיה תצמיח\u0004 כן ה' אלהים יצמיח צדקה ותהילה נגד כל הגויים\u0003\"\u0004 (ישעיהו סא, יא) \u0003\"זרעה\"\u0004 בלשון יחיד \u0003לא נאמר, אלא \"זרועיה\",\u0004 הרי שגינה קטנה יתכן שיהיו בה מיני זרעים מרובים.","על רמז זה שואלים: \u0003מאי משמע\u0004 \u0005[מה המשמעות]\u0006 בכתוב שממנה למדים על חמישה זרעים דווקא? \u0003אמר רב יהודה\u0004 כך נדרש: \u0003\"כי כארץ תוציא צמחה\" תוציא\u0004 — \u0003חד\u0004 \u0005[אחד]\u0006 \u0003צמחה\u0004 — \u0003חד\u0004 \u0005[אחד],\u0006 \u0003הרי תרי\u0004 \u0005[שנים],\u0006 \u0003\"זרועיה\"\u0004 בלשון רבים הוא לפחות \u0003תרי, הא\u0004 \u0005[הרי]\u0006 \u0003ארבע,\u0004 והלשון \u0003\"תצמיח\"\u0004 מוסיף עוד \u0003חד\u0004 \u0005[אחד],\u0006 \u0003הא\u0004 \u0005[הרי]\u0006 \u0003חמשה\u0004 לשונות של צמיחה וזרעים, שכולם נאמרים על ערוגה אחת בגינה."],["\u0003וקים להו לרבנן דחמשא בשיתא לא ינקי מהדדי\u0004 \u0005[ומוחזק להם לחכמים שחמישה\u0006 זרעים \u0005בששה\u0006 טפחים \u0005אינם יונקים זה מזה].\u0006","ושואלים: \u0003ומנלן דהא דקים להו לרבנן מילתא היא\u0004 \u0005[ומנין לנו שמה שמוחזק להם לחכמים דבר הוא],\u0006 ואפשר לסמוך על מסורותיהם לענין זה? ש\u0003אמר ר' חייא בר אבא\u0004 שכך \u0003אמר ר' יוחנן: מאי דכתיב\u0004 \u0005[מה\u0006 משמעות כתוב זה \u0005שנאמר]:\u0006 \u0003\"לא תסיג גבול רעך אשר גבלו ראשונים\u0004 בנחלתך אשר תנחל\" (דברים יט, יד), כוונתו: \u0003גבול שגבלו ראשונים\u0004 וקבעו מה הם התחומים הדרושים לכל צמח, אותו \u0003לא תסיג,\u0004 ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 משמעות\u0005]\u0006 הלשון \u0003\"גבלו ראשונים\"? אמר ר' שמואל בר נחמני\u0004 שכך \u0003אמר ר' יונתן: מאי דכתיב\u0004 \u0005[מה\u0006 משמעות זה \u0005שנאמר]\u0006 \u0003\"אלה בני שעיר החרי ישבי הארץ\u0004 לוטן ושובל וצבעון וענה\u0003\"\u0004 (בראשית לו, כ), \u0003אטו כולי עלמא\u0004 \u0005[וכי כל\u0006 שאר \u0005העולם]\u0006 \u0003יושבי רקיע נינהו\u0004 \u0005[הם]?\u0006 שמודגש באלה שהם יושבי הארץ?! \u0003אלא\u0004 לומר \u0003שהיו בקיאין\u0004 יותר מאחרים \u0003בישובה של ארץ, שהיו אומרים:\u0004 קרקע \u0003מלא\u0004 אורכו של \u0003קנה זה\u0004 יפה \u0003לזית, מלא קנה זה לגפנים, מלא קנה זה לתאנים. ו\"חרי\"\u0004 נקראו בני שבט זה בשיכול אותיות ללמד \u0003שמריחים את הארץ\u0004 וקובעים מה ראוי לגדל בה. \u0003ו\u0004כהסבר לכך שנקראו יושבי שעיר הקדמונים בשם \u0003\"חוי\"\u0004 (עיין בראשית לו, ב) \u0003אמר רב פפא:\u0004 משום \u0003שהיו טועמין את הארץ כחויא\u0004 \u0005[כנחש],\u0006 ולפי הפעם היו קובעים לאיזה גידול היא ראוייה. \u0003רב אחא בר יעקב אמר\u0004 שלא משום כך נקראו \u0003\"חורי\",\u0004 אלא משום \u0003שנעשו בני חורין מנכסיהן,\u0004 כלומר, שגירשו אותם בני עשו מנחלתם, ועיקר שמם היה \"חיוי\".","ולגופה של ההלכה \u0003אמר רב אסי: ערוגה\u0004 שאמרו במשנה ששטחה ששה על ששה טפחים, הכוונה היא ש\u0003תוכה ששה\u0004 על ששה טפחים \u0003חוץ מגבוליה,\u0004 שאותם ששה טפחים אינם כוללים את גבוליה, ולשטח כל ערוגה יש להוסיף גם את המקום שתופס גבולה. \u0003תניא נמי הכי\u0004 \u0005[שנויה ברייתא גם כן כך]\u0006 \u0003ערוגה תוכה ששה.\u0004 ושואלים: ו\u0003גבוליה בכמה?\u0004 מה שטחם? ומשיבים, \u0003כדתנן\u0004 \u0005[כפי ששנינו\u0006 במשנה\u0005],\u0006 ש\u0003ר' יהודה אומר: רוחב\u0004 הגבול \u0003כמלא רוחב פרסה\u0004 (כף רגל). ו\u0003אמר ר' זירא ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003ר' חנינא בר פפא: מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' יהודה\u0004 — \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"והשקית ברגלך כגן הירק\"\u0004 (דברים יא, י), ומכאן למדים: \u0003מה רגל\u0004 רוחבה \u0003טפח אף גבול\u0004 שבין ערוגה לערוגה שבו יש לשים את כף הרגל בזמן ההשקאה \u0003נמי\u0004 \u0005[גם כן]\u0006 רוחבו \u0003טפח.\u0004","\u0003אמר רב:\u0004 כשלמדנו במשנה שניתן לזרוע בתוך \u0003ערוגה\u0004 חמש מיני זרעים ולא לעבור על איסור כלאיים — בערוגה הנמצאת \u0003בחורבה\u0004 (מקום שאין סביבו צמחים) \u0003שנינו.\u0004 אבל אם היתה ערוגה בין הערוגות אסור לזרוע בה מינים מרובים כל כך, שהזרעים מן הערוגות האחרות מתערבים עם הצומח בערוגה. ושואלים: אם מדובר בערוגה בודדת, \u0003והאיכא\u0004 \u0005[והרי יש]\u0006 את \u0003מקום\u0004 ה\u0003קרנות,\u0004 ואפשר לזרוע אף בקרנות ולהוסיף מינים אחרים בלא חשש (גאונים)! \u0003אמרי בי\u0004 \u0005[אמרו\u0006 בני \u0005בית\u0006 מדרשו\u0005]\u0006 של \u0003רב משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב :\u0004 דברי רב היו \u0003בממלא את הקרנות,\u0004 כאשר זרע את חמשת מיני הזרעים בערוגה ושוב אין להוסיף בה זרעים. על הסבר זה מקשים: \u0003וליזרע מאבראי ולא לימלי מגואי\u0004 \u0005[ושיזרע מבחוץ ולא ימלא מבפנים]\u0006 ויוכל להרבות במינים במקום למלא את הקרנות!"],["\u0003גזירה שמא ימלא את הקרנות\u0004 לאחר שזרע מתחילה את הערוגה, ויבוא לידי כלאיים. ושואלים: ומה בכך? \u0003ולא יהא\u0004 דינה של ערוגה זו \u0003אלא\u0004 כ\u0003ראש תור\u0004 (משולש) של \u0003ירק. מי\u0004 \u0005האם\u0006 \u0003לא תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 \u0003היה ראש תור ירק נכנס לתוך שדה אחר\u0004 — \u0003מותר\u0004 ואין בכך משום כלאיים, \u0003מפני שנראה סוף שדה\u0004 ולפי הצורה מבחינים ששני שדות אלה נפרדים זה מזה! ומשיבים: \u0003אין ראש תור בערוגה.\u0004 שהיתר זה של ראש תור הריהו רק בשדה גדול שניכרת בו צורת ראש תור, אבל בערוגה שקטנה היא והזרעים בה סמוכים זה לזה אין אפשרות להבחין.","\u0003ו\u0004אילו \u0003שמואל אמר:\u0004 במשנתנו אף \u0003ערוגה בין הערוגות שנינו\u0004 בהיתר חמשה מיני זרעים, ולאו דווקא בערוגה בודדת. ושואלים: \u0003והא קא מיתערבי בהדדי\u0004 \u0005[והרי מתערבים הם זה בזה]!\u0006 ומשיבים: \u0003בנוטה שורה לכאן ושורה לכאן,\u0004 שמטה את הצמחים בשורות שיגדלו לשני כיוונים שונים (מאירי) ואין הם נראים עוד כמעורבים.","\u0003אמר עולא: בעו במערבא\u0004 \u0005[שאלו במערב,\u0006 בארץ ישראל \u0005]:\u0006 \u0003הפקיע\u0004 (פתח) \u0003תלם אחד על פני כולה,\u0004 שמסביב לערוגה חפר תלם אחד, האם נחשב הוא כמפסיק בין הערוגות (גאונים, תוספות). \u0003אמר רב ששת: בא\u0004 ה\u0003ערבוב\u0004 של הערוגות זו בזו \u0003וביטל את השורה,\u0004 ועל ידי תלם זה אין עוד הפרש בין הערוגות. \u0003רב אשי אמר: אין עירובו מבטל את השורה. איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רבינא לרב אשי\u0004 ממה ששנינו במשנה: \u0003הנוטע שתי שורות של קישואים\u0004 ו\u0003שתי שורות של דילועין\u0004 ו\u0003שתי שורות של פול המצרי\u0004 — \u0003מותר.\u0004 שניכר כל מין לעצמו. אבל אם נטע \u0003שורה אחת של קישואים ושורה אחת של דילועין ושורה אחת של פול המצרי\u0004 — \u0003אסור,\u0004 שבשורה אחת אין כדי היכר לכל מין\u0003.\u0004 והאם לא נלמד מכאן שתלם אחד בלבד מתערב באחרים ואינו ניכר לעצמו? ענה לו רב אשי: המקרה במשנה יוצא מן הכלל, \u0003שאני הכא דאיכא שראכא\u0004 \u0005[שונה כאן שיש ענפים\u0006 נמשכים\u0005],\u0006 שהמינים הללו ענפיהם ארוכים ונוחים להסתבך זה בזה והם מבטלים את התלם שביניהם, אבל שאר ירקות שאינם כן, תלם אחד דיו להפריד ביניהם.","\u0003אמר רב כהנא\u0004 שכך \u0003אמר ר' יוחנן: הרוצה למלאות כל גינתו ירק\u0004 ולא להרחיק בין השורות הזרועות — \u0003עושה ערוגה\u0004 בת \u0003ששה על ששה\u0004 טפחים \u0003ועוגל בה חמשה\u0004 עיגולים (גאונים, רמב\"ם) \u0003וממלא\u0004 את \u0003קרנותיה\u0004 של ערוגה זו ב\u0003כל מה שירצה,\u0004 ובעיגולים זורע ממין אחר.","ושואלים: \u0003והא איכא דביני וביני\u0004 \u0005[והרי יש\u0006 את הזרעים \u0005שבין\u0006 העיגולים\u0005]!\u0006 שעל ידם מתערבים שוב כל מיני הירקות בערוגה! \u0003אמרי דבי\u0004 \u0005[אומרים\u0006 בני \u0005בית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ינאי\u0004 בתשובה לכך: מדובר כאן \u0003במחריב\u0004 ואינו זורע \u0003בין הביניים. ורב אשי אמר:\u0004 אפשר למלא את הערוגה כולה וכדי להבדיל בין הזרעים, \u0003אם היו זרועין\u0004 העיגולים בערוגה \u0003שתי, זורען\u0004 את אלה שבין הביניים \u0003ערב,\u0004 ואם היו זרועים \u0003ערב\u0004 — \u0003זורען שתי. איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רבינא לרב אשי,\u0004 שנינו: \u0003עבודת ירק בירק אחר,\u0004 כלומר, יש להניח לכל ירק תחום עיבוד שאסור לזרוע בו ממין אחר, וגודל אותו תחום הוא \u0003ששה טפחים. ורואין אותם\u0004"]]};
